/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230927-14","meetingId":"r05-cm09","date":"2023年9月27日","dateIso":"2023-09-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"環境性能の目標についてです。(1)のＺＥＢの目標水準ですが、当初、Ｎｅａｒｌｙ ＺＥＢを目標として掲げられたと思うのですけれども、今回ランクが下がって、再生可能エネルギーを除くＺＥＢ Ｒｅａｄｙの目標水準にしたということなのですが、これは設計事業者ともいろいろ相談、交渉の上でだと思うのですけれども、確認をさせていただきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"しかしながら、創エネのほうは太陽光の発電によるところが非常に大きいというところでございまして、敷地内の太陽光発電設置スペースというところにおきましては限りがあるというところで、検討の結果、Ｎｅａｒｌｙ ＺＥＢは達成しないということが判明したです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"確認","question":"岡山市役所もたしか１６階か１７階建てぐらいだったか、平米数、規模としては、岡山市役所のほうが大きいのか、大体同様だと思うのですけれども、これはあくまで目標なのですが、取得をしたら、西日本では岡山市役所なのだけれども、東日本で見ると、品川区役所が初となるのですか。それを確認させてください。","respondent":"大友新庁舎建設担当課長","answer":"しかしながら、ＺＥＢ Ｒｅａｄｙの中でもエネルギー削減量は、岡山市、中野区、それぞれ５３％程度というところなのですけれども、区といたしましては、国内最高を目指すということで、この削減量を超えてエネルギーを削減するということを目標に。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。確認できました。目標の達成に向けて、ぜひこれからも取り組んでいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"ただ、今回ＣＡＳＢＥＥはＳランクを目指すということで、これは当初の想定どおりなのかなと思うのですけれども、基本計画でいろいろな方向性を立てていると思うのですが、基本的には基本計画ですから、ここだけ確認をしたいのですけれども、それは森澤区長に答申をした基本計画にのっとって、第二庁舎の件はかなり大規模な変更でしたけれども、基本的には。","respondent":"山下新庁舎整備課長","answer":"今回、環境性能の部分につきましては、設計事業者等々との調整を踏まえまして、ＺＥＢ Ｒｅａｄｙということでの目標をお示ししているところですけれども、基本的な考え方といたしまして、基本計画に沿った整備を進めていくというところについては、変わりはないところです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"あのとき、第二庁舎の話も、まだそれに対して納得をしていない区民や、また議会の一定の議員もいるとは思うのですけれども、基本的には、この基本方針にのっとってやっていくということを改めて確認しました。どこに懸念があるというのは、ここでは指摘しませんけれども、ぜひそのことは遵守をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの委員からもお話がありましたが、ＣＡＳＢＥＥ－建築、そしてＣＡＳＢＥＥ－ウェルネスオフィスの最高ランクの取得に向けて進めていくということは、とてもよいことだと考えています。この目標を掲げていることについてですが、対外的に発表するというのは、どういうタイミングを考えていらっしゃいますでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"対外的な発表ということにつきましては、新庁舎整備ニュースなどで示していく形になるかと思うのですけれども、こちらの発行に合わせて、この目標で整備していきますということを、時期としては未定なところはあるのですけれども、発行の際に周知を図る形になるかと考えています。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"確認","question":"品川区はすばらしいです。そこで、１個だけ確認ですけれども、アクセシビリティの手引の取組で、障害者団体のヒアリングを踏まえ作成する素案について、区民の説明会をするという話なのですけれども、これは、当たり前ですけれども、障害者団体の方々にもしっかりと、例えば周知・啓発というのは、個別という言い方が正しいのか、そのような対応というのを取られているのか、確認だけ。","respondent":"山下新庁舎整備課長","answer":"ただいまご質問いただきました区民向け説明についての周知です。資料にも記載していますとおり、今現在、障害者団体等のヒアリングをまさに実施しているさなかでございまして、そういった中で、今やり取りをしています。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"ＺＥＢについてなのですけれども、ＺＥＢを目指すと、イニシャルコストは幾らかかかってくる。一方で、ランニングコストは削減効果が見込まれるということなのですけれども、Ｎｅａｒｌｙ ＺＥＢを導入した場合と、ＺＥＢ Ｒｅａｄｙを導入した場合で、コストの差というのはどのぐらい出てくるのでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"ＺＥＢ Ｒｅａｄｙにつきましては、イニシャルコストをかけることで達成するというところにはなるのですけれども、Ｎｅａｒｌｙ ＺＥＢの実現というところにおきましては、現状、技術的課題が大きく、実現が難しいので。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"Ｎｅａｒｌｙ ＺＥＢはそもそも現実に難しいので、あまり試算とかはそこまでしていらっしゃらなかったということで、それでよろしいのかということと、ＺＥＢ Ｒｅａｄｙで、ＣＡＳＢＥＥのＳランク取得というのは可能なのでしょうか。ＺＥＢとＣＡＳＢＥＥの取得基準というのが異なってくるから、それは別に関係ないということなのでしょうか。その辺りを教えてください。","respondent":"大友新庁舎建設担当課長","answer":"ウェルネスオフィスにつきましては、その中に住まう人や利用する人などの快適性とかを重視したところの指標になっているのですけれども、快適性や利便性、安全・安心性、運営管理プログラムなどの項目で評価をしていくというところになってありますが。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問","question":"私からは、オープンハウス説明会についてなのですが、まず周知方法について、どのような形で区民の皆さんにお伝えをされていくのかお聞きしたいと思います。","respondent":"山下新庁舎整備課長","answer":"前回の委員会でも少し触れたところはあったかと思うのですけれども、来月１０月に各町会・自治会を回ってまいりまして、町会長や自治会長の皆様には、こういった形で説明していくということをご案内していきたいと、今のところ考えてあります。","id":"exchange-010"},{"speaker":"松永委員","kind":"提案","question":"できましたら、町会・自治会でも周知をされるということなのですが、ぜひ掲示板等でも何か貼っていただければいいかなと提案をします。この説明会については、誰がどのような形で対応されるのか、伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"ただいまご質問がございました、オープンハウスに臨む体制というところですけれども、まず、私ども新庁舎整備課の職員が一義的に対応するというところのほかに、設計事業者にも助力を得ながら対応してまいりたいと考えています。","id":"exchange-011","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"数名で対応されるということで、理解いたしました。日時、場所、会場について質問なのですが、まず、例えばイオンとか、パトリア、八潮のほうなのですけれども、これは休日ではなく、平日ということでありまして、なかなか人とかが通らない時間帯ではないかと思います。ましてや１１月１９日の夢さん橋は、特にそうではないかと思います。","respondent":"山下新庁舎整備課長","answer":"昨年度、基本計画の素案の説明会を実施する際は、比較的区民が利用するところという視点よりは、区が持っている施設、区民集会所でしたり、五反田文化センター、スクエア荏原等々での開催という形で行ってまいりましたけれども、なかなか集客といいますか。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひそうした観点からも、今から日程を変えるのは難しいと思いますので、そうした視点も含めて、今後また改めて、こういった説明会がありましたら、そうした日程感を考慮していただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"えのした委員","kind":"質問","question":"場所とすると、多分、ザモールという施設になるかと思うのですけれども、そこに例えば、何かテントを立てて分かりやすく、オープンハウス説明会をやっているというパネルが置かれたり、そういった形で行われるのでしょうか。","respondent":"山下新庁舎整備課長","answer":"いわゆるのぼり旗のようなものまでは、今のところ考えてございませんけれども、ご紹介のありました掲示物でしたり、あとは人の声かけというようなソフトの面で、集客といいますか、皆様に足を運んでいただけるように努めてまいりたいと考えています。","id":"exchange-014"},{"speaker":"えのした委員","kind":"質問・要望","question":"ここは本当に人通りが多いところになりますが、ほかにもイベントをやったりしている場所でもありますので、ぜひ皆さんが気軽に立ち寄れるような、また興味を示していただけるような説明会の開催をしていただきたいと願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどまつざわ委員との質疑の中で、アクセシビリティのところで、まさに障害者団体等のヒアリングを行っているというお話があったのですけれども、以前の委員会でも指摘をしたのですが、アクセシビリティ以外のところで、新庁舎とか、あとは庁舎跡地の活用についてのご要望が出た場合には、それはアクセシビリティに限りますということでばちっと切らないで。","respondent":"山下新庁舎整備課長","answer":"こちらで手引の素案として、こんな考え方ですよというところは、ご説明をさせていただきまして、各団体にお持ち帰りいただき、団体内で意見を少し取りまとめていただきながら、次の段階としまして、お考えいただいたご意見をお伝えいただくということで、今。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これまでの議論の中でも、新庁舎の中に、例えば何か障害者の施設を作るということは考えていないということで、それは一定の了承の下で進んできたという経緯があるのですけれども、例えば跡地活用の中では、この前の見せていただいたアンケートの中にも、そのようなご要望も入っていたりして、このことは別に、新庁舎であろうと庁舎跡地であろうと、また、広町であろうと。","respondent":"泉広町事業調整担当課長","answer":"３の主な内容ですが、委員会の運営についてご説明した後、これまでの経緯や関連計画について情報共有するとともに、委員会の進め方や、ワークショップの実施概要、また、対話型市場調査の実施概要についてご説明いたしました。","id":"exchange-017"},{"speaker":"松本委員","kind":"提案","question":"現状は、ある程度ゼロベースでご提案いただくという流れなのかなとは思いつつ、せっかく第１回の検討委員会で様々なご意見が出ましたので、こうした資料も、対話型市場調査を行う際には伝えていただくというのも一つなのかなと思いますが、この点はいかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査につきましても、今回１回限りということで考えてございませんで、こちらも段階的に進めていくものと認識していますので、そういった段階ごとに、いただいたご意見を一定集約した形で、民間事業者の方にお見せして、意見を頂戴していくということを考えてあります。","id":"exchange-018","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"意見","question":"段階的なというところですので、今回のところでは、本当にゼロベースでやっていかれるというところを理解いたしました。いずれにせよ、どのように活用していくのかは重要な問題かと思いますので、丁寧に進めていただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問","question":"私から何点かお伺いします。検討委員会の第１回が行われたということで、参加者の方は２０名ぐらいいらっしゃったと思うのですが、いらっしゃいましたでしょうか。その中で、主な意見の抜粋というのが８つぐらいということで、恐らく最初ですから、皆様それぞれご意見をおっしゃっていたと思うのです。","respondent":"泉広町事業調整担当課長","answer":"第１回の検討委員会の会議録につきましては、第２回の検討委員会の中で内容を皆様に確認していただいた上で、公開をしていくということで考えてあります。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"検討委員会の皆様からの意見の周知について、理解をいたしました。それから、ワークショップなのですけれども、平日のほうの開催のスケジュールが２０名中１５名と、５名少ないというのは、結構大きいのではないかと思っておりまして、運営の準備上、難しいというお話もありましたけれども、願わくば、もう少し定員まで埋まるようにご対応いただけないか、ご再考いただければ幸いです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"地区の個性や特性というと、この跡地のどういったことが挙げられてきているのかというところがあれば、具体に何か言われていることがあれば教えていただきたいのと、その次の、数十年後の未来を見据えた長期的な視点。とても大事だと思います。この長期的な視点というところで、どういうやり取りがなされたのか、こういったところを少し詳しく教えてください。","respondent":"泉広町事業調整担当課長","answer":"一つは、地域の個性という部分では、大井町駅周辺は子どもが多いですとか、高齢者がたくさんいらっしゃるというところ、また、子どもの親御さんも含めまして、そういったところが、商店街であるとか、公園であるとかを核として。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"行政機能としての機能をきちんと果たせるとか、あと公益性と収益性、維持管理コスト、財源、こういう部分はもちろんあるので、そういうものを度外視した話にはできないのですけれども、こういう外せない機能性だとか財源といったことをしっかりと踏まえた上での一体性の上で、話題となるようなというか、区民の皆様が、品川区はここがすばらしいのだと言えるような。","respondent":"泉広町事業調整担当課長","answer":"大井町駅周辺、特に広町地区につきましては、駅至近であるといったところですとか、また、その駅自体も３路線が接続しているといったところの地域性は、しっかり広域的な目線も含めて、今回の検討委員会の委員の皆様でございましたり、ワークショップ、また。","id":"exchange-023"},{"speaker":"筒井委員","kind":"確認","question":"そうした前提がないと、それぞれ皆さんは夢やご希望をお持ちだと思うので、そうしたご意見を様々、自由闊達に出されてくると思うのですけれども、一方で、そうした新庁舎との関係性もあるので、ある程度の方向性を共有していかないと、収拾がつかなくなる可能性もあるので、その点、参加されている委員の皆様のご認識というのはどうなっているのか、また。","respondent":"泉広町事業調整担当課長","answer":"そちらにつきましては、今回の検討委員会第１回目の中で、これまでの経緯ですとか、上位計画を説明する中で、また、今後の委員会の進め方を説明する中で、新庁舎整備に際する区民負担の軽減ですとか、先ほどもいただきました一体的なまちづくりの視点、また。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"提案","question":"できるだけ意見を自由闊達に出す。第１回のワークショップの、これも予定だと２回しかワークショップが行われないということですから、そこで出た意見が議論の俎上に上がって、これに対していいねとか、いや、それはどうでしょうかという意見を交わすということはもちろんなのですけれども、各団体の代表の方、公募区民の方が出られている委員会ですから、様々なご提案等もあると思います。","respondent":"泉広町事業調整担当課長","answer":"主な意見でいただきましたワークショップ形式で進めたいといったところのご趣旨につきましても、今回、検討委員会のメンバーが２０名ということで、多いというところもございまして、そういった視点から、ワークショップ形式でやると。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"さっきから基本計画の策定委員会の話ばかりで恐縮なのですけれども、いろいろな事情もあって長引いたりして、１０回やりました。本当に実のある活用検討委員会、もちろん実があるものに、皆さんそういう方の代表ですから、なるのでしょうけれども、そこについてのご見解をもう一度伺って、質問を終わりたいと思います。","respondent":"泉広町事業調整担当課長","answer":"最大限、実のあるものにしていくといったところですけれども、検討委員会の中で様々工夫をいたしまして、区民の意見を引き出せるような工夫について、これからも検討を進めてまいりたいと考えているところです。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"１３ページの辺りとかで、運用ルールのところはあるけれども、システムの対応の四角のほうで、システム対応のところが空欄になっているといいますか、対応していないところなどもありますが、ヒューマンエラーは防がないといけないですが、ヒューマンエラーは絶対生じると想定した上で、どのようにシステムで、そのエラーを防ぐような対策を考えていらっしゃるのかを伺えればと思います。","respondent":"横田情報推進課長、河西情報戦略担当課長","answer":"こちらにつきましては、今回は戸籍・住基の文字のみということになりまして、住所の、例えば横棒だったり、平仮名の「の」だったり、数字の全角だったり半角だったりということにつきましては。ですので、運用とシステム対応両輪で、チャットＧＰＴの利用を進めていくという回答になります。","id":"exchange-027"},{"speaker":"松本委員","kind":"確認","question":"個人に関する情報であって、特定の個人が識別され得るもの、これはまさに個人情報保護法の定義かと思うのですけれども、神戸市のほうとかを確認しますと、そういった個人情報に加えて、これが品川区だと重要性分類II以上なのかなとも思うのですけれども、例えば、非公開の審議会の検討の情報などとか、そういったものも入力しないようにということが。","respondent":"河西情報戦略担当課長","answer":"１つ目の情報の内容に関してですが、まさに先ほどご紹介した重要性分類II、こちらの中身がかなり多くございまして、そちらに関しては、区の非公開情報を含みます。ガイドラインにするときには、もう少し具体的な内容が分かるような形で落としていきたいと思います。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"マイナンバーの総点検に関わるところでご説明いただきましたシステム標準化のところなのですが、非常に大事で、かつ重たい作業、重たい対応だということでご説明いただいたのですが、文字の統一も含めてなのですが、令和７年度末までにシステム導入が義務づけという中で、どのような計画を考えられているのでしょうかということで、結構重たいシステム導入に向けて、もう少し具体的に。","respondent":"横田情報推進課長、河西情報戦略担当課長","answer":"令和６年度の途中から令和７年度にかけて、システムのデータ移行ですとか、システムテスト、そのようなことを実施する予定になっております。１つ目、ヒューマンエラーへの対策ですが、試行運用に向けて、区では既に４回程度、研修を実施しております。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問・要望","question":"システム標準化の計画ですけれども、なかなか全体像がまだ見えない状況という中でも、大変な作業だと理解いたしました。大変だと思いますが、必要なことということで、頑張っていただきたいと思います。チャットＧＰＴのほうのご回答ですけれども、研修を区の職員の皆様に４回程度されているということで、これは念のための確認で、全員に向けてやっているのでしょうかというところで、教えてください。","respondent":"河西情報戦略担当課長","answer":"対象は、課の代表者と希望者に対して実施しております。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問","question":"そうすると、課の代表者と希望者以外の方も使うことがあり得るのでしょうかというところです。追加で質問させてください。","respondent":"河西情報戦略担当課長","answer":"ですので、希望する職員がいれば、皆さん利用できます。そのために、利用案内ですとか、そういったものを一緒に配付していますが、今後も研修を定期的に開催して、先ほどご説明した運用ルールの周知は徹底していきたいと考えております。","id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"効果測定のやり方のところは、おっしゃるとおり、定量的にやるのは難しいのかなと思いますので、職員の方からアンケートを取っていただくというのが合理的なのかなと思うのですが、ぜひよく職員の方々のご意見を聴いていただいて、柔軟に意見を取り入れながら効率的に使っていただけるよう、これも要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"１３ページの情報漏えい対策のところで、情報漏えい対策はしっかりと行っていただきたいのですけれども、区職員との会話からは学習されない仕組みを取り入れるということで、具体的に区職員との会話から漏れるということは、どのようなケースを想定されているのでしょうか。","respondent":"河西情報戦略担当課長","answer":"そのＢが、例えば個人情報や機密情報であったときは、区とチャットＧＰＴとのやり取りが一般の方に漏れてしまうということになります。そのような形で、チャットＧＰＴ自体、学習しないようにするという対応になります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"まだまだ私も勉強不足なところもありますので、いろいろと教えていただきたいと思います。１０ページで、試行運用が８月末ぐらいから開始されているかと思うのですけれども、今、大体１か月ぐらいたったかと思います。今の試行運用期間中に、何か区の職員の方からご意見だとか、トラブルだとか、現時点での動きというのがありましたら、教えてください。","respondent":"河西情報戦略担当課長","answer":"試行運用の開始に当たって、先ほどご説明したとおり、各課の代表者と希望者に対して利用研修を４回実施して、利用ルールですとか、効果的な使い方の周知を実施しておりますが、特に大きなトラブルですとか、そういったことは今のところございません。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"各委員の質疑も聞かせていただいて、幾つか確認させてください。報道では、自治体によるサポートの段階でログアウトしないまま、何件か複数のマイナポイントのひもづけ作業をやったときに、他人とのひもづけが行われてしまったということが起きたようですけれども、今回はその辺りの確認というのはデジタル庁からあったのか、あと、そのひもづけの中でミスがなかったのかどうか、その点を確認させてください。","respondent":"横田情報推進課長","answer":"ログアウトまできちんと確認をしておりますので、品川区では、このようなエラーは発生しておりません。国からの通知でも、今回のマイナポイントでのエラーはなかったと連絡が来ております。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"確認","question":"ヒューマンエラーは起こったとすれば、それはご本人が何か間違えたということで、例えばそういうことが起きた場合には、ご本人から区役所に、しつこいようですけれども、そこで登録をしたのに間違いが起きたのだという問合せはなかったのでしょうか。","respondent":"横田情報推進課長","answer":"戸籍住民課所管なので、詳細は分かりませんが、そのようなケースはなかったと聞いております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"確認","question":"チャットＧＰＴのところですけれども、先ほどからご説明があって、私も何度もやってみました。この件に関しては、もしかしてさっきご説明があったら申し訳ないのですけれども、投資価値があると判断をされたということですが、チャットＧＰＴには幾つかのコースがあって、自治体コースみたいなものの廉価版、無料版があって、それを採用していくということでよろしいのでしょうか。","respondent":"河西情報戦略担当課長","answer":"先ほどマイクロソフトのサービスが基になるというお話をいたしましたが、そのために費用がかかっているというのと、先ほど申しました、チャットＧＰＴの最新の文章生成プログラム、ＧＰＴ４.０にすると、有料になるというところで、自治体向けのプランというか。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"品川区というのは私の認識では、こういうデジタル化とか、ＩＣＴにたけた職員の方が多いということで、伝統的にそういうものがあるということは、いろいろな職員の方からも伺ってきましたので、ぜひ区民サービス向上に向けて活用をお願いしたいと思います。","respondent":"横田情報推進課長","answer":"文字の標準化のメリットですが、文字の管理コストという面と、あとは、大手のベンダーがたくさん文字を持っていますので、ベンダーロックインによっていろいろなシステムが移行しにくいということが、解消されるということがメリットになります。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"他自治体とのやり取りで、私が読んだものによると、これもベンダーロックインの一つなのでしょうけれども、震災があったところに他自治体の職員が応援に駆けつけて、パソコンを開いていろいろやり取りしようとしたら、システムが違うので、そういった支援ができなかったということがあって、それも一つの弊害だということが書いてあったのですが、例えばそういう具体的な事例というか。","respondent":"横田情報推進課長","answer":"戸籍システムの大手が１００万文字とか、そういう形で管理しておりまして、そこから違うシステムに移行したいといった場合に、文字を例えば１０万文字しか管理していないところであれば、１００万文字から１０万文字に、文字の同定作業というのが必要になってきますので。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。システムの専門家からすると、そこが一番大きいということなのだと思います。ただ、ネット上ですけれども、いろいろなメリット等も出ていたので、私はあえて質問したのですけれども、分かりました。システムの専門家から見ると、そこがすごいメリットなのだということで理解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040","title":"町会・自治会支援"},{"speaker":"えのした委員","kind":"確認","question":"システム標準化は、先ほどもほかの委員からご質問がありましたが、品川区の対象は１８業務で、大きな作業、タイトなスケジュールということで、計画のスケジュールも令和５年、分析から始まって、ご答弁ありましたけれども、ガバメントクラウドは、法律上は努力義務扱いとなっているのですが、もしシステム移行が少し遅れてきたということになれば、延ばしてもそれは構わないということなのですか。","respondent":"横田情報推進課長","answer":"なので、ガバメントクラウドを使わないで標準化の移行が遅れる、遅れないということは、ないということになります。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問","question":"すみません、私も勉強不足で、その辺がよく分からなかったのですが、では、令和７年度末までに移行しなくても大丈夫というニュアンスですか。","respondent":"横田情報推進課長","answer":"令和７年度までのシステム標準化は必須になります。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"もう１点、先ほども山本委員からご質問がありましたが、チャットＧＰＴの活用の取組で、職員の研修をやられているというお話でしたが、全職員が利用できるということで、システム上は情報漏えいがないものを使うということでしたが、やはり初めての取組ですので、これからも研修をやっていくとお話されていましたが、例えばチャットＧＰＴ研修を、資格ではないですけれども、修了した方は。","respondent":"河西情報戦略担当課長","answer":"今後、効果を含めて検討していきたいと考えております。","id":"exchange-043"},{"speaker":"えのした委員","kind":"質問・要望","question":"先行して横須賀市ですか、他自治体との垣根を超えた連携で活用事例などを共有して、これからも取り組んでいっていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのシステムはクラウドに置くということなのですけれども、そのクラウドに置かれたシステムというのは、移行するというのでしょうか、それは品川区として管理運用するという位置づけになって、クラウドというところを使わせてもらうのだけれども、中身のいろいろなメンテだとか、維持管理だとか、そういうのは品川区がしていくのだということなのか、そうではなく、国がそういうクラウドに。","respondent":"横田情報推進課長","answer":"ガバメントクラウドの移行につきましては、まず、選定するシステム利用料金なのですが、アプリの利用料金と、ガバメントクラウドの利用料金の２つを足したものになりまして、ガバメントクラウドにつきましては、システムベンダーが選定する形になっていますので、区はあまり。","id":"exchange-045"},{"speaker":"塚本委員","kind":"確認","question":"そうすると、今後品川区は共同利用であって、基幹システムのほうもベンダーが一律に提供するみたいなイメージというところなので、前から気にしているところなのですけれども、品川区がこれまで管理運用してきた、今度移行の対象となっているシステムに対する委託費みたいなものは、発生してこないという見方でいいのかというのを確認させてください。失敗したら大変なリスクになる。","respondent":"横田情報推進課長","answer":"２点目、突然全てのシステムが変わるのかというご質問ですが、段階的といいますか、システムが大きい住民記録システム、税システム、国保システムにつきましては、令和７年１月に移行する予定になっております。その他のシステムは大体が令和８年１月。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"チャットＧＰＴについては１点なのですけれども、これまでも研修のお話がすごくたくさん出ているのですが、チャットＧＰＴというのは、今までの委員のお話にもありましたけれども、今までのシステムの、使い方がよく分からないとか、固まってしまったので、どうなってしまったのでしょうかというものとは少し違っていて、対話型なので、本人の言葉の使い方のチョイスだとか、どこまで使えるかというところで。","respondent":"河西情報戦略担当課長","answer":"実際に研修の中でも既に実施しておりますが、チャットＧＰＴ、ＡＩが分かりやすいメールの書き方というのが、確かにあります。","id":"exchange-047"},{"speaker":"せお副委員長","kind":"質問・要望","question":"私からは少し細かいところで、２点ほど確認させていただきたいのですけれども、先ほど筒井委員から質問があったところ、私も分からなかったのですが、区職員との会話からは学習されない仕組みというのは、区職員とチャットＧＰＴとのやり取りからはという意味なのかなと思ったのですけれども、そこを確認させてください。","respondent":"河西情報戦略担当課長","answer":"ですので、個人情報、機密情報に限らず、職員が登録した全ての情報に関して、チャットＧＰＴは学習しないという機能を提供する予定です。","id":"exchange-048"},{"speaker":"せお副委員長","kind":"質問","question":"私は、個人情報などは、チャット履歴をオフにすれば学習しないというのをどこかで見たことがあったので、それのことかなと思ったのですけれども、この資料を読んだだけでは、私は最初には、個人情報と機密情報をＡＩ側が、これがそうだというのを瞬時に判断して、それを学習しないということなのかなと思っていたので、全て区職員が入力したものは学習しないという理解でよろしいのでしょうか。","respondent":"河西情報戦略担当課長","answer":"そのとおりです。ですので、区職員とのやり取りに関する情報は、全て学習の対象にはならないということでご回答いたします。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問・要望","question":"陳情者の方から、陳情の理由に幾つもの質問事項が列挙されておりますので、今ご説明いただいた内容と少し重複するかもしれないのですけれども、一つ一つ確認をさせていただければと思います。その次に、議会の承諾は不要なのでしょうかというところで、これについてもご回答いただければと思います。それから、その２行先に、評価額は幾らで契約したのでしょうかというご質問もあります。","respondent":"泉広町事業調整担当課長","answer":"その後の、今ＪＲ東日本が工事を進めている件ですけれども、こちらは土地区画整理法上、先ほどもご説明の中で申し上げました仮換地指定がなされまして、その効力が発生いたしますと、品川区では、使用し収益することができなくなるというところがありますので。","id":"exchange-050"},{"speaker":"山本委員","kind":"質問・要望","question":"いろいろとたくさん質問させていただきましたが、ご回答ありがとうございました。今回、庁舎建て替えを含む広町地区の土地区画整理事業は、ＵＲを事業者として、非常に複雑な形になっているというところもありますので、ぜひ行政として情報公開、透明化を進めながらしていただきたい、分かりやすく説明していただきたいというのが、一つ、思いとしてはあります。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"Ａ－１地区について、使用承認するに当たり議会の承諾は不要なのでしょうかという点なのですけれども、法定上、仮換地指定がなされると使用収益権がなくなるから、そうした議会の承諾などは不要ということなのでしょうけれども、仮換地指定がなされると使用収益権がなくなるという法律の根拠は、具体的に何法の何条なのか、改めて教えてください。","respondent":"泉広町事業調整担当課長","answer":"先ほど私のほうでご説明申し上げました使用収益に関わるお話だと思います。こちらの法令につきましては、土地区画整理法第９９条に規定があります。そういったところの規定の中でやっているというものです。","id":"exchange-052"},{"speaker":"筒井委員","kind":"確認","question":"品川区が資金計画書等の文書を非開示にされているということで、これは品川区の情報公開条例に基づいてだと思うのですけれども、またすみません、条文の確認で、これは情報公開条例の何条でしょうか。","respondent":"泉広町事業調整担当課長","answer":"こちらは品川区情報公開条例の第７条に規定があるものです。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。一方、品川区はそのまま条例に基づいて、非開示というご判断をされたという違いがあるのですけれども、それはどういった理由なのか。品川区はＪＲとかＵＲとの、非開示にするという取決めというか、協定書とか契約とか、そうしたものを結んでいるということなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"東京都が開示ということがございましたけれども、これは自治体の中でそれぞれが判断されるものということで認識しています。先ほど、協定等々の中でそういった取決めをされていないのかというお話がございました。","id":"exchange-054","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、具体的に民間業者との取決め、しっかり文書的な形の協定書とか契約書というものはないのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"要は、取決めはありますけれども、取決めがある中でも、こういった情報開示があった場合には、品川区情報公開条例の中の条文をそれぞれ確認しながら開示をしていますので、一定程度、情報公開条例の中で、しっかり区として判断させていただいているところです。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問","question":"こうした情報を非開示にしていこうという取決めが、事前にはあったということですか。そうしたことを踏まえて、さらに区のご判断で、もろもろ総合的に考慮されて、この非開示決定をしたという理解でよろしいのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"一方で、情報公開する場合には、その都度、その時点に応じまして、条例と照らし合わせながら、区で判断をさせていただいているです。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。では、品川区と業者の間では、基本協定等々の中で守秘義務の取決めがあったと。一方、東京都がこれを開示したということは、東京都は品川区と民間業者との守秘義務の取決めとかには、全く関与していなかったというご理解でよろしいのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"都の取決めの中には、当然、法令に基づき開示を義務づけられている場合には開示していくというところで、そういった取決めもございまして、そういった中で、区・東京都それぞれが、それぞれの条例の中で開示の判断をしています。","id":"exchange-057","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問・要望","question":"東京都はそうした取決めもある中、開示のご判断をされたということなのですけれども、品川区が非開示決定をされたという事情もよく理解できるのですが、一方で、品川区が非開示にして、東京都はこうして開示をされたということで、陳情者の方からは、なぜ品川区はかたくなに非開示にしてしまうのかという疑念を持たれてしまうということも、無理からぬところかなと考えていますので、今後品川区は、当然。","respondent":"泉広町事業調整担当課長","answer":"情報公開の考え方ですけれども、区といたしましても、情報公開を進めていくべきということで考えてあります。情報公開の申請があった場合には、情報と照らし合わせながら、情報公開を基本的には心がけていくというところで考えてあります。","id":"exchange-058"},{"speaker":"まつざわ委員","kind":"確認","question":"内容としましては、陳情の趣旨であります「区民に分かりやすく説明」という部分におきまして、先ほどご答弁、いろいろなやり取りを聞いていて、例えば価格設定に対しましても、委託業者を介して妥当な確認をしていたり、保留地の２,６１８m2、多分、正確には２,２００m2ぐらいになると思いますけれども、本来報告義務のない５,０００m2未満の報告も、課長からはしっかりと報告していくという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問・要望","question":"本日結論を出すで、結論は不採択でお願いをいたします。るる陳情に出ている質問点について、課長からの説明、また、今の質疑でもありましたけれども、特に議会として疑義を挟むようなものではないと思いますので、議会から説明を、あえてまた求めるというところには当たらないと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"山本委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。一方で、陳情者の方が陳情で言われていること、情報公開を進めてほしい、透明化をもっと進めてほしいというところには、賛同するところでもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。ただ一方で、陳情者のご質問に対して、品川区の情報公開条例上、非開示にすべきものがありますので、そうした意味で、今回はその説明をすることは困難だという判断です。なお、今後、非常に大きな事業に関わることですので、区民に対し、情報公開、透明化を、ぜひともできるところはしっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/994750?Template=document&Id=6156#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":46195,"voices":161}},{"id":"r05-20230928-19","meetingId":"r05-cm09","date":"2023年9月28日","dateIso":"2023-09-28","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時１８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、資料の中で防災会議ということで出てきているのですが、この中に活動内容として、災害発生時に、その災害に関する情報を収集するということなどが書いてあるのですけれども、災害発生時は災害対策本部も設置されると思うのですが、そことの関係性が、発生時と書いてあるので、どういうことかなと思ったので、伺いたいと思います。東京都地域防災計画の主な変更点を伺います。","respondent":"平原防災課長","answer":"さらには、台風対応のところで、どちらかというと地域防災計画が震災編を中心に書かれていたところ、風水害編の相当な充実といったところを今回してまいりたいと考えてございまして、風水害対応の強化を図ってまいりたいと考えているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう１点、在宅避難を基本にするということでご説明がありましたけれども、在宅避難の方も恐らく備蓄がそんなにあるわけではないと思いますので、長期間にわたってくると食料とかもなくなってくるということになると思いますので、避難所で在宅避難の方も物資を受け取れるということの周知と、しっかりと配給をしていっていただきたいと思うのですけれども、それを計画にどのように反映させていくのか。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"続きまして、１点、帰宅困難を飛ばしまして、在宅避難のところですが、在宅避難者のところ、備蓄物資がなくなったら、例えば拠点となる避難所のようなところに物資が集積されるので。そういった中で、さらなる帰宅困難者対策の充実を図ってまいりたいと考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ほかの目標もありますけれども、今回もそうしたことを示してやっていくということなのかどうかというところも確認させていただきたいと思います。そうした形で、今回の地域防災計画も見直していくことが必要だと思いますけれども、いかがでしょうか。在宅避難のところで、今回、１週間分備蓄してほしいということに変えるということですかね。１週間分備蓄するのも、自宅で大変だなと。","respondent":"平原防災課長","answer":"具体的に死者数を何人から何人という、想定から減らしていくという形もあるかなと思うのですけれども、そこについては、詳細は現在検討中ですので、今後の中でご説明できればと思いますが、一つには、先ほどの繰り返しになりますけれども、今回の被害想定で。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"予防策第一というところで、予防にも力を入れてと。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"これ、数字で言うのは簡単なのですが、では、その増えた５万人はどうするのですかという話になったら、恐らく現在の１８万人でも全く対応できないのではないかと思うのです。そして、大災害が起きたら、都市機能はほとんど停止してしまうではないですか。警察、消防、情報連絡員、いろいろ各方面から受援体制があると今お話しいただきましたが、実際にこの大都市でこの方たちは本当に支援に回れるのですか。","respondent":"平原防災課長","answer":"一方で、首都圏３,０００万人ということで、日本の４分の１ぐらいがここにということなのですけれども、ただ、首都直下地震ということを考えたときに、首都圏全域が何かという形ではなくて、今回、都心南部直下地震という地震モデルについては。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"今のお話で分かるのですが、いざというときにと考えた場合に、阪神・淡路大震災はありましたけれども、それは本当の１区域なのですよね。そして建物もたくさんある。東京都との整合性もあるのでしょうけれども、こういうこともいいですが、私は前も話をしていますけれども、やはり皆さん、備蓄に対して、先ほどもご答弁ありましたが、個々人のお宅で１週間分はあらかじめ確保していただきたい。","respondent":"平原防災課長","answer":"それからもう１点、自分の地域はというようなところですが、こちらについてもまさにおっしゃるとおりでございまして、今回の地域防災計画、先ほど冒頭の説明の中で一旦ご紹介させていただきましたが、地区防災計画という。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、今お話を聞きましたけれども、今回、受援体制ということですが、実際、拠点病院にしても、４割は派遣がゼロだと。現場での救命や対応力には懸念を抱いている。この大都市に多くの住民が住まれていて、それだけに対応できる病院、また、スタッフ、先生もいないわけです。その辺も考えて、しっかりと新しい防災計画、受援体制もつくっていくのでしょうけれども、対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"私、ずっと受援体制をきちんとやっていただきたいと。今までそれは自治体として処理できませんでした。それは１点、ぜひ考えていただきたいのですけれども、何か見解があったら伺いたいと思います。これが夏だったらどうだっただろうというのは両方の地域の方から伺っておりますので、そういうことの後の処理もぜひ計画の中に入れていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"区でもしっかりと必要な分の備蓄は進めているところですので、それと相まった形で対応させていただければと考えています。ニーズも様々変わってくるですけれども、先ほどプッシュ型支援とプル型支援という説明をさせていただきましたが、７日目以降、プル型の段階では、国と都と連携いたしまして、物資調達・輸送調整等支援システムを活用いたしまして。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしようと。区の備蓄の中に携帯トイレがあることも分かりましたし、それは皆さん、防災訓練のときなんかに配っているということで分かりましたけれども、やはり使っていただかないと、本当にそれが使いやすいものかどうかというのは分かりませんので、ぜひそのようにお願いしたいと思います。これは個別の商品の宣伝みたいになってしまうので、要望にとどめておきます。これは意見でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"大きな概要の視点からは少しずれてしまうと思いますが、そういう観点から、各地域では、避難所連絡会議に係長以上の職員は原則参加というような形で呼びかけているというご答弁がこの委員会で防災課長からあったと思われますが、現在の状況、参加状況とか、今後の計画としての工夫とか、もしお分かりであれば、紹介できる範囲でお聞きできればと思います。","respondent":"平原防災課長","answer":"もし進んでいないところがありましたら、１２月の訓練までに顔を出すようにということは、改めて伝えてまいりたいと思ってあります。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"ご答弁ありがとうあります。公助の、教職員の災害時の役割ということで、新たな人材の活用といったところであると思いますが、各地域の教職員の責任の明確化、代替となる人の明確化など、各地域で顔が認識できるようにと思いますが、この辺のことについて紹介できる範囲でお聞きできればと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"もう一方、教職員、今度は災害が発生した後、早期の教育機能の復帰という形で、平常に戻すというような視点も重要ですので、そういった視点をしっかりと地域防災計画の中で、教員の子どもを守る機能であるとか、あるいは、余力ができたときにお手伝いいただくとか。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ご答弁ありがとうあります。先ほどあったとおりで、１２月に総合防災訓練の一斉訓練が行われますが、さらに各地域・町会と区が連携を密にして、それぞれが顔の見える形で行っていただければと思います。こちら、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"区民のマンションなどに対しては、閉じ込め防止対策を講じる必要がある所有者などに、閉じ込め防止対策を促し普及啓発していくとありますけれども、閉じ込め防止装置の設置は現在どれくらい進んでいるのでしょうか。区としてそれは把握しているのでしょうか。","respondent":"平原防災課長","answer":"そういった視点で、すみません、私ども防災の立場では、どのぐらいの件数がといったところは把握できておりませんけれども、一方で、先ほどマンション防災を進めていくという話をさせていただきましたが、そのような中で。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"努力義務ではなく、今ではエレベーターに基本的に設置するようにということだと今伺いましたけれども、例えば古いマンションに関してとかは、閉じ込め防止装置が設置されていないものもあるかもしれないなと思うのですが、そちらは把握しているというか、何年以前のマンションだとその可能性があるとかということはあるのでしょうか。お聞かせいただけると助かります。","respondent":"平原防災課長","answer":"今、そういった視点で、私どもの立場では、エレベーターの閉じ込めの可能性があるというような視点で、いわゆる建築部局としっかりとそういう設置のところの連携はしていきたいと思うのですけれども、私どもの対策といたしましては、閉じ込められたときにどうするのかとか。","id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"もう１点なのですけれども、ペット同行避難についてお伺いしたいのですが、一般的な避難所であれば、ホームページでも地域ごとに場所の確認ができたり、ココシル品川でも福祉避難所などを探せたりすると思うのですけれども、区のホームページで、ペットと同行可能な避難所がうまく探せなくて、私が探せないだけなのかもしれないのですが、記載はあるのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"今回の地域防災計画の修正におきましても、そういった対応をしていくというところで、今、取り組んでいる最中ということですので、全ての避難所できちんと対応ができるようにした上で、しっかりと情報を発信してまいりたいと考えております。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"地域防災計画の中に、今回の資料では載ってきていなかったのでお尋ねしたいのですけれども、医療との連携体制がどのようになっているのかなというところがまず１点と、受援体制のところにも医療者のところが載っていないので、ボランティアとかで、医療の方々、県外からとかでも来られるのではないかなと思うのですけれども、そういう点について、どのように体制を整えているのか、教えてください。","respondent":"平原防災課長","answer":"災害時の医療連携についてですけれども、こちら２つございまして、まず１つ目は、災害時の緊急医療救護という関係、いわゆるトリアージを行うようなところですね、こちらについては、区の医療計画という形で、拠点病院の前でやっていただくというルールになっております。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"受援体制のところも、救護所に医療救護体制ということで医師の受入れもすると思うのですけれども、そこの体制もしっかり整えていただきたいと思っておりまして、医師・看護師がそろっても、なかなか医療物品が足りなくて治療ができなくて、結局病院に運ばないとどうしようもないというような現状があったり、医療関係者の備品、食糧含め、そういうところの整備も整っていないと。","respondent":"平原防災課長","answer":"委員ご指摘のとおりでございまして、しっかりと対応していく必要があります。一例ご紹介申し上げますと、先日、昭和大学病院で災害時の医療連携を想定しました訓練が行われました。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"実は私も昭和大学病院で、ちょうど防災係のチームの委員長をやっていましたので、そこの防災をやっていく中で、これは絶対さばき切れないよなというのを実際の現場で感じておりました。こちらは要望で終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"防災備蓄のところで、決算特別委員会でやろうか悩んでいたところなのですけれども、教えていただきたいのが、今回、１週間分に変えていくというお話があって、東京備蓄ナビというサイトで、多分東京都のサイトなのだと思うのですけれども、あなたの家庭はこんな備蓄が必要ですよというのがあって、すごく分かりやすいなと思って、やはりここでも１週間分を求めてきているのです。","respondent":"平原防災課長","answer":"そういったところの公助の充実と併せて対応してまいりたいと思いますので、そういったところも含めた形でご紹介させていただこうと思うのですけれども、ただ何分、先ほども公助の段階の上げ下げみたいな話がありましたが、心持ちとして見ると。","id":"exchange-019"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"１点、要望だけ。要望でこれは終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"つる委員","kind":"確認","question":"地域防災計画のところなのですが、これは毎回ジレンマなのかもしれませんが、近年、いい意味で、品川区含め、この近隣での大規模な災害がないので、なかなかそういう実態がなくて、訓練の中でしかいろいろ確認がないわけでありますけれども、今回、大規模修正されると。","respondent":"平原防災課長","answer":"そういったところを踏まえて行っていきますので、ない場合でいくと、こういうものが必要だよねというようなものになりますので、それが逆に、行く行くは備蓄していくのだけれども、今はないので支援として求めていくとか。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"分かりました。それはあくまでも人の命をしっかりと守っていくという意味でのことがやはり大事なのかなと思うのですけれども、その上で、この計画の中にもあったかどうか、ちょっと私も忘れてしまったのですが、ボランティアのときもそうなのですけれども、例えば助けますよね、手助け。現場のそういう計画も変わっていないとなったときに、その辺の判断はどういうふうにされていくのか、教えてください。","respondent":"平原防災課長","answer":"前段でございましたところ、臨機応変にというのは、災害対応は、最終的には区民の生命・財産を守るといったところが主眼ですので、逆に法令遵守をするあまり、それが守られないと本末転倒な話になりますので、そこはしっかりと柔軟な対応をしてまいりたいと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"勉強にもなりましたし、本当にこういうジレンマの部分もあるとは思うのですが、今、ご答弁を聞いて、一区民としても安心しましたし、また、こういった体制を整備していくことの大変さが改めて分かりましたので、引き続きいろいろな知見、力を、民間の方も含めて、充実していただきたいと思います。今日、本来は受援体制とかなので、備蓄にフォーカスしてしまうとあれなのですか。","respondent":"羽鳥防災体制整備担当課長","answer":"もちろん東京都は品川区だけの物資を京浜トラックターミナルで受け取るわけでありませんので、やはりそこは、他区の支援も含めて、優先するということにはなりますけれど、実際に区と連携しているのはＪＰロジスティクスですので、協力協定の業者として。","id":"exchange-023"},{"speaker":"つる委員","kind":"意見","question":"明確になって。１点大事なところが、区民、それから帰宅困難者等の物資の供給が滞りなくできる、今のご答弁の意味というのはそこなのですよねという、そこだけ答弁ください。","respondent":"羽鳥防災体制整備担当課長","answer":"東京都と整備いたしまして、京浜トラックターミナルを品川区の地域内輸送拠点としても活用できるようになりましたので、国や他自治体から支給されました支援物資に関しまして、早急に各避難所。","id":"exchange-024"},{"speaker":"つる委員","kind":"提案","question":"安心しました。ということを昨年も紹介させていただいて、この場所でも提案等させていただいたのですが、そこをきちんと担保していくということも、やはり平時の対応としては大事ではないかなと。使い切れない。だから、この辺について、また決算特別委員会の場でも言っていきたいかなと思うのですが、今の対策含めて、この辺の考え方、既に提案もしているのですけれども、教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"お渡ししたものが使われないというところは、いろいろな理由があると思うので、そこの調査は必要かもしれませんが、お渡しして使えないという声を吸い上げて、使ってみたくなるような、使えるような物資に、順次そこは切り替えていく必要があると思いますので、声を聞きながら。","id":"exchange-025"},{"speaker":"つる委員","kind":"提案","question":"例えば１００万円買って、９０万円分は地域とかに活用いただいて配布したということと、でも、１０万円については、処理し切れなかったから処分したという、それは会計処理上、あると思うのですが、この辺、購入時と出したときの処理というのは、会計処理上、どういうふうにしてなされているのか、教えてください。","respondent":"羽鳥防災体制整備担当課長","answer":"減価償却等の考えは特になくて、実際に買ったものに関しまして、実際、活用していくというだけで、通常の一般需用費の物品の流れと同じような会計処理をしています。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。会計処理については、そっちの担当部署にもいろいろ聞いていきたいと思うのですけれども、そういう意味で、まさに有効活用できる工夫もぜひしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ議論を聞きながらというところもあって、先ほどエレベーターの閉じ込めのお話がありましたけれども、閉じ込め防止装置は普及していっていただきたいと思いますが、実際、閉じ込められてしまうというケースは被害想定の中でもたしか増えていたと思うのですけれども、その際に、備蓄ボックスですか、それを設置していくことが必要だと思うのですが、そこを伺いたいと思います。","respondent":"平原防災課長","answer":"私ども、マンション防災、先ほど来ご説明させていただきましたが、今後しっかりと取り組んでいく中で、そういったものの重要性を考えてまいりたいと思っておりまして、そういったところはお伝えしてまいりたいと考えております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区でもぜひ設置をして、進めていっていただきたいと思います。医療との連携ですね、そこはいろいろ進めて、関係をつくっているということですけれども、日頃のそうした医療の充実、介護事業者がいっぱいあるということが、やはり災害時でもそうした人たちを助けていくという力になると思いますので、福祉の充実という点でも位置づけていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問","question":"障害者の方々とか高齢者の方々とかの実態というか、対策が反映できるような委員の構成が必要なのではないかなと思うのですけれども、そういう視点での委員の構成が、地域の関係者ということではあったのですけれども、どういう構成になっているのか、伺いたいと思います。","respondent":"平原防災課長","answer":"こちら、私どもも女性委員の増加というのは非常に重要な問題だと思っているのですけれども、何分、いわゆる充て職というようなところになっておりまして、どこどこという組織の方から出てきていただいているということもあって。","id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"高齢者も今、個別避難計画とかをつくったりしていますけれども、そういうところでも様々課題があると思いますので、こういうのもどうしたら反映できるか、そういう人材を委員の中に入れられるかという視点でもぜひ検討いただいて、切実な要望が反映される地域防災計画になるような委員の構成にしていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"女性視点のところですが、私どもも非常に重要だと考えていますので、今後とも他自治体の事例なんかも参考にしながら、いろいろ検討を進めてまいりたいと思います。","id":"exchange-031"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"被害想定のところで、東京都から令和４年５月２５日に出された新たな被害想定ということで、品川区の被害想定が随分下がったなというのが、比べてみて私はちょっと驚いたのですけれども、死者数も７７９人、真冬の１８時、風速８８メートルというところが被害が一番多いので、ここのところで比較したところで、死者数７７９人が２８８人で３７％に減っていたり、建物の全壊も。","respondent":"平原防災課長","answer":"さらには、東京都の被害想定の中で、今後、それがさらに進んだ場合の減災の考え方も出ておりますので、引き続き、そういった意味では、これで立ち止まることではなく、不燃化・耐震化を進めるべきだと私ども考えておりますし。","id":"exchange-032"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"それで、品川区がもともと１０年前の計画のところで減災目標を出していたのが、ほぼクリアできたという、それくらいの状況になっているというところは、本当に評価できることではないかなと思ったのですけれども、減災目標との関係でどう考えられているのかというのも一つ伺えたらと思います。","respondent":"平原防災課長","answer":"そういう中で、減災の示し方という点ですけれども、今、こちらについては詳細検討中ですので、今日の段階でこの方向でというお答えはまだできないところ申し訳ございませんけれども、先ほど委員からもご紹介いただきました、東京都が示しております耐震化・不燃化。","id":"exchange-033"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そういうところでいうと、そのために具体化するというところもすごく必要なのではないかなと思いまして、例えば家具転倒防止、これを、今、高齢者の場合では、非課税者は２万円まで無料でできますし、課税者も２,０００円でできるという制度がありますけれども、これを全世帯に広げていくだったり、今回のところでは、家具転倒防止と出火防止と耐震化というところが東京都では出されていますけれども。","respondent":"平原防災課長","answer":"高齢者をはじめとして、ご自身でつけることができない方に対しましては支援を行わせていただいているところですが、引き続きそういったところは連携しながら進めするのと同時に、直ちにそこを広げるというようなところの前に。","id":"exchange-034"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"それからもう一つ伺いたいのが、ここで出ていたのが長周期地震動なのですけれども、平成２７年１２月に、南海トラフ沿いの巨大地震による長周期地震動に関する報告というのが出されているのですが、この後に長周期地震動に対しての対策で出ているものがあったら、どういうものがいつ頃出ているのかということを教えていただきたいと思います。","respondent":"平原防災課長","answer":"一方で、いわゆる防災対策という点ですけれども、国による伝達の中に長周期地震動のランクがあるのですが、それを今度、いわゆる緊急地震速報と同時にお知らせするということが始まりました。そういったところで区のほうでも対応していく必要があるものと考えています。","id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"質問","question":"ここのところでは、超高層建築物に対しては、長周期地震動対策については、個別の建物ごとに想定すべき長周期地震動を用いて、改めて構造安全性の検証を行い、その検証結果に応じて改修等の措置を講じることが望ましいと書かれているのですけれども、そういう対策がどの程度とられていて、超高層の安全性がどういう状況になっているのかというところでは、区としてどう把握をされて。","respondent":"平原防災課長","answer":"大変申し訳ございません、個別の建築物の状況につきましては、私どものところでは把握しておりませんので、具体的にどういう対策をといったところまでは、一つ一つ数字を持っているところではございませんけれども、そういったものが発生したときにどうなるかという視点で。","id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"意見","question":"超高層の開発が次々と行われている品川区なので、長周期地震動の超高層建築物への影響というところは、しっかりと検証しながら、把握しながら、対策をとっていくことが必要ではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/556800?Template=document&Id=6642#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":47688,"voices":88}},{"id":"r05-20231002-4","meetingId":"r05-c-settlement","date":"2023年10月2日","dateIso":"2023-10-02","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時５８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"せお副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"せりざわ委員","kind":"確認","question":"おはようあります。私からは、１５０ページの歩行喫煙防止過料、関連して１１７ページの歩行喫煙防止推進経費から、喫煙の防止についてお伺いします。決算書には過料が９万６,０００円分計上されていますが、この過料の中身というのは、先ほどの５エリアの路上喫煙に対しての過料だけで、ほかのエリア外の歩行喫煙等も含まれているのか、もしくはごみ捨て等も含まれているのか、まずお聞かせください。","respondent":"河合生活安全担当課長","answer":"それ以外の過料はございません。この指定につきましては、５エリアというのは、通勤・通学等の通行量と併せて、また地域の環境、そして路上喫煙の状況等を踏まえて指定されているものです。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"ポイ捨てを指導されている方々との連携が取れているのか、推移がどうなっているのかを把握できているのかをお聞かせいただきたいのと、あと、１件１,０００円ですから恐らく９６件だと思いますが、これはやはり少な過ぎるのではないかと思っています。もちろんエリアによって、それぞれの状況というのは違うのだと思いますが、他区との比較として、品川区の実績をどう評価されているのかをお聞かせください。","respondent":"河合生活安全担当課長","answer":"したがいまして、今後も公衆喫煙所、指定喫煙所の整備等をやるとともに、効果的な指導・啓発でそういったところを抑え込んでいきたいと考えております。","id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"そもそも、この過料の件数の少なさというのは多分、巡回されている方がまだ、たしか月に１回ぐらい、警察の方と一緒に回っていると以前伺ったことがありますが、今おっしゃっていただいたように、シルバー人材センターの方が頑張って指導いただいているのだと思います。過料に至らないところの指導件数というところまで確認されているのかもお聞かせいただきたいと思います。","respondent":"河合生活安全担当課長","answer":"条例の改正の検討というところで提案がございましたが、今現在、やはり罰則などを伴う改正というのは、まず喫煙の環境等、整備も踏まえた上で検討だとは思いますので、まず環境の整備と指導・啓発を効果的に行うというところで、吸う人。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"もちろん、これからたばこを吸う人がしっかり吸える環境をつくっていくというのは、喫煙者の方々からの、そういった議員もたくさんいらっしゃいますから、そういったお声を拾い上げていくというのは、それぞれあっていいかと思いますが、例えば１１７ページの歩行喫煙防止推進経費というのは、そもそもの補助の在り方として、医療保健政策包括補助金として、もう医療分野。","respondent":"河合生活安全担当課長","answer":"今のご質問で、ごみ捨ての過料等も含めてというところなのですけれども、ごみ捨てのポイ捨ての過料が、著しく環境を害するというふうなところでありますけれども、捨てている状況といったものを確認したときには。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは２点、お伺いしたいと思います。７８ページの従前居住者用住宅使用料、また１１５ページの共通商品券普及促進事業について、それぞれお伺いしてまいります。初めに、７８ページの従前居住者用住宅使用料に関連いたしまして、令和４年度の従前居住者用住宅の最新の入居率と入居数、空き数についてお知らせください。","respondent":"小川木密整備推進課長","answer":"従前居住者用住宅の現在の入居状況ですが、１０月１日現在、５７部屋中３４部屋の入居、入居率といたしましては６０％といった状況です。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"５７部屋中３４部屋で６０％ということで、余裕があることを確認いたしました。","respondent":"伊藤災害対策担当課長","answer":"現在も、関係課、特に木密推進担当課とお話を進めておりまして、どういった形でお部屋を管理していくのか、鍵の貸し借りや、また、どのように電化製品を入れていくのかなど、検討は進めているような状況ですが、まだまだ検討段階ということですので、また進みましたらご説明。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"区民、被災者の声から、火元ではない類焼や水損でも、居住が困難となった方への利用ができ、また本年４月からは被災者から、ホテルでの２日間の仮住居ができ大変にありがたかったとのお声を聞いています。例年、品川区では１００件前後の火災件数があり、先週の金曜日の深夜にも品川区内にて３棟が延焼する火災がありました。あれば人員はどう組まれているのか。お聞きしたいと思います。","respondent":"伊藤災害対策担当課長","answer":"これにつきましては、土日祝日、年末年始にかかわらず災害対応をしているというような状況です。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"大変安心させていただきました。先日の一般質問での区長答弁で、被害認定に際し区職員が災害現場に赴き、その際に説明・配布する被災者援護一覧表を修正し、分かりやすい説明を行っていくとありましたとおり、丁寧な説明、さらなる周知と支援の拡充をお願いしたいと思います。続いて、１１５ページの共通商品券普及促進事業に関連しまして、プレミアム商品券についてお伺いします。","respondent":"小林商業・ものづくり課長","answer":"それに対して、最大３冊ご購入できた方、２冊ご購入できた方、あるいはもともと１冊ご購入で１冊、希望どおりという方がいらっしゃいまして、ただ、４冊ご購入を希望された方に対しては、販売冊数がそこまでいかないということで。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"４万冊で、現在２万１,０００冊ということで、こちらは余りというのはどういう対応をされているか、もう一度ご答弁をよろしくお願いします。","respondent":"小林商業・ものづくり課長","answer":"まず３冊以上を希望する方というのが１万６,３５５名いらっしゃったのですけれども、この中の抽せんをまず行って、３冊希望の方は、実際に１,８７３名、抽せんで選び、その中で外れた方がいらっしゃるわけですけれども、また２冊希望以上の方でまた抽せんという形で。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"我が会派からも、商品券と一緒に、決定通知書に併せて例えばＱＲコードを入れ込んで、そちらを読み取ると、取り扱っている２,０００店舗の情報がすぐに分かるように訴えてまいりましたが、現在の取組状況など、改善の最新の工夫されている情報等があれば教えていただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"ご指摘の点、ＱＲコードなどの活用なども含めまして、利便性をどうやって上げられるかというところは、商店街連合会とまた協議してまいりたいと思います。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"併せて、ご高齢の方だとスマートフォン等を活用できない方もいらっしゃると思いますが、こういった点での支援対策等があれば教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"ただいまのご質問にお答えいたします。高齢者の方で、直接にスマートフォンやホームページをご覧になれない方というのですか、使うのが苦手な方というのもいらっしゃるかと思います。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"本日はよろしくお願いいたします。私からは、７８ページ、自転車駐車場使用料に関連して、１６２ページ、放置自転車等保管料について併せて伺います。そして次に、９８ページ、母子保健衛生費の産後ケア事業について、そして時間が許せば１２０ページ、高齢者クラブ運営助成費について質問をします。そこで、駅付近の駐車場の利用状況、そして放置自転車の撤去数について、区の状況を教えてください。","respondent":"工藤交通安全担当課長","answer":"令和４年度の駐輪場の利用率の関係です。区内自転車等駐車場は２６か所ありますが、こちらについては全体で７０.４％の利用率となっております。放置自転車の撤去数については、おおむね８,０００台という形になってあります。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"駐車場利用率についてなのですけれども、恐らく２６か所、駅付近、また駅から遠いところも合わせての利用率になっていると思いますが、駅付近の利用の状況についてお伺いしたいという点が１点。私は手元にあるので言ってしまうのですけれども、撤去数については、令和３年が８,３６１台で、令和４年が８,９８５台と、６００件以上増えている。この状況について、区としてどのようにお考えでしょうか。","respondent":"工藤交通安全担当課長","answer":"続きまして、令和３年度と令和４年度の撤去台数の関係なのですが、こちらについては、令和３年度はコロナの影響がございまして、撤去活動に若干の制限をかけてございました。令和４年度につきましては、その制限を緩和した関係で、撤去台数が増えているところです。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"撤去数が増えているということ。そして、子育て中の保護者の方から駅付近でお話を伺うと、そもそも駅の近くの駐輪場の幅が狭くて、チャイルドシートをつけた自転車は幅があって、そもそもとめられる設計になっていない。先ほどご答弁で、駅近くの利用率を把握していないということでしたが、このような一つ一つの区民の声をどのように把握しているのでしょうか。","respondent":"工藤交通安全担当課長","answer":"２点目、点字ブロック等の上に違法駐輪がされてあるといったところですけれども、こういったところは非常に、視覚障害者の方々の危険につながるところですので、そちらについては指導・啓発を厳しく継続してやってまいりたいと思います。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"自転車の活用を進める。そして、この活用が進むと、さらに自転車の駐輪場の設備整備が必要になると考えられますが、区として、自転車活用推進計画と駐輪場整備について、どのようにお考えでしょうか。チャイルドシートを載せた自転車でもとめることのできる駐輪場の設計、そして駅付近の駐輪場の利用が偏ることに対して、区としては現在どのように対応を検討しているのでしょうか。教えてください。","respondent":"鈴木都市計画課長","answer":"自転車活用推進計画、昨年度から今年度にかけて２か年、公募区民の方にも参加いただきながら、策定に向け、検討を行っている状況です。先ほどいただいた様々な声については、今回、計画策定に当たって、区民アンケート、それから駐輪場の利用者アンケートなども実施しています。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、区民の方々の声を聞きながら、そして、駅付近は特に、実際の駐輪場の把握もしていただきながら、今後の計画、自転車推進を進めることは、とても健康にもいいので、いいとは私も思うのですけれども、まずは今困っているという声をしっかりと聞きながら、対策をした上で進めていただければと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"１２６ページ、季節性インフルエンザ定期予防接種特別補助事業補助金、１２０ページ、介護人材緊急確保対策事業費補助金に関わって、介護職員の処遇改善、時間があれば、１０１ページ、品川駅南地域周辺まちづくり事業について伺います。伺います。今、定点観測になっていると伺いましたけれども、数字的なところで把握しているところが、紹介できるものがあれば、直近でよいので併せてお願いいたします。","respondent":"坂野保健予防課長","answer":"コロナとインフルエンザということなのですが、３８週で８.８９人。これは東京都全体です。３７週が１６.０４人でしたので、ピークが過ぎて、がたんと下がっている。これがコロナです。インフルエンザなのですが、３８週で１２.１９人。その１個前の週が１１.３７人。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう年度でした。大田区では、１１月１日からの予防接種を受け付けた方の自己負担を免除する措置を取っておりますが、伺いますけれども、高齢者の命と健康を守るためにも、接種を促す予防接種の無料化を品川区でも行うべきではないでしょうか。毎年、恒常的にやっていただきたい。今からでも補正予算を組むなどして対応するよう求めますが、いかがでしょうかということが１つ。伺いたいと思います。","respondent":"坂野保健予防課長","answer":"令和２年度と令和４年度が東京都の包括補助がございましたので、２,５００円の部分が、何といいますか、公費負担されたわけなのですが、今年度はそれがないという形でございまして、試みの計算、試算をしてみますと、非常に概算ベースなのですが、もし今年度の数で。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"品川区で、令和２年度、令和３年度、令和４年度のインフルエンザ予防接種の接種者数と、およその接種率を伺いたいと伺います。それと、他区で無料にしているという区は、今、２３区中どれぐらいあるのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"一般財源を投入して無料にしている区は、今、手元に詳しい資料がないのですけれども、大体、２３区全体の半分よりはまだ多くはない区が、今年度、そういう感じで補助していると承知しております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"無料化で１０％以上上がるわけです。半数にはいかないけれども、かなりもう半数ぐらいやっている。それで、隣の港区は６５歳以上でやっていますし、渋谷区も６５歳以上、目黒区は７０歳以上、大田区は今年から始めたということで、近隣区でやっていないところは品川区だけなのですけれども、これはどうなっているのかと。無料化で効果もある。なぜ品川区はやらないのか、その理由を伺いたいと思います。","respondent":"坂野保健予防課長","answer":"令和２年度、令和４年度に関しましては、東京都の補助があってやっていたという経緯があります。今年度はそれがないです。来年度以降、これはどうなるかというところももちろんあるかと思うのですが、東京都の補助の趨勢を注視してまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、本当にこれでいいのでしょうか。やはり、他区、近隣区はもう全部やっている。これは、ぜひ手だてを講じていただきたいと強く求めたいと思います。伺いたいのですけれども、品川区は、区内特別養護老人ホームで、なかなか人材が集まらない実態や、あるいは派遣会社に頼らざるを得ない実態、また、これが結果的に経営も圧迫しているというような実態など、ご存じなのでしょうか。伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区内におきましては、そういった部分も注視しつつ、それ以外にも法人等で独自に採用できるような、いろいろな手だてを提案する、あとは実務者研修等の研修を受けた者に対して助成金を出すなどして、少しでも人材確保が務まるように、区としても支援をしているところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"提案","question":"社会的にもこれからますます必要な仕事で求められるし、ＡＩなどに任せることもできない仕事なわけですから、介護の現場に思い切って税金も投じて、社会的に底上げする政治をぜひ品川区からつくっていただきたいと私は思います。共産党区議団は２つ提案しております。これが１つ目です。この２つを要望し続けているわけですが、改めてこの２点を求めたいと思いますが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"区の独自策というところで、先ほど、夜勤がつらいといったお話を聞いているという声も、委員からお話がありましたが、例えば区の特別養護老人ホームにＩＣＴの見守り機器を設置させていただいたりすることによって。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ＩＣＴだけでは、やはり現場は人を求めているのです。人がいないことには、人が増えないことには、もうどうにもならないと思っていますので、そうした処遇の改善、人が集まるための対策を、区として独自に打っていただきたいというのを繰り返し求めます。それと、国に処遇改善交付金の復活を求めてくださいと言ったのですが、求めないということなのでしょうか。そこもはっきりお答えいただければと思います。","respondent":"菅野高齢者福祉課長","answer":"区の介護人材の確保の独自策というところでは、品川区は平成７年から介護専門学校も運営しておりますので、その辺りのところに引き続き努めたいというところと、国の処遇改善については今後も動向を注視してまいります。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"私からは、１４６ページ、ふるさと納税寄附金、１７３ページ、インターネット映像配信委託、５４ページ、特別区たばこ税について伺います。一方で、品川区に歳入として入ってくる分、令和５年度の見通しと令和６年以降の見通しをそれぞれお聞かせください。","respondent":"提坂税務課長","answer":"その先というのは、なかなか見込みを出すのは難しいところです。流入額につきましては、令和４年度が１,９２９万円、それから令和５年度は８月末の段階で１５７万円となっております。令和６年度以降について、流入額というのも読むのがなかなか難しいというのが実情です。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。非常に、比較数等も大変大きな差だと思うのですけれども、特別区長会としていろいろとご要望など出されていると思うのですけれども、今後、品川区としては、これに対して改善策、対抗策をどう立てていくおつもりなのか、お聞かせください。","respondent":"提坂税務課長","answer":"対策といたしましては、従前から引き続き行っていることではありますけれども、地場産品に乏しい品川区といたしましては、物より事ということで、体験型の返礼品をもっと拡充するということと、あと、寄附金の使い道を明確にして。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"物より事、体験型を増やしていくということで、それは非常にいいことかと考えておりますけれども、あと一方、特別区長会を通じて、今年の７月３１日にもうご要望を出しておりますけれども、いろいろ特別区長会、そうした改善やご要望を出しているのですけれども、それに対して、国、総務省側は、そうした反応、きちんとお応えしていただけるのかが非常に気になるところなのですけれども。","respondent":"提坂税務課長","answer":"７月に区長会から要望を出したときの国側の受け止めとしては、引き続き現状を受け止めて検討していくといった内容だったかと思います。","id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"分かりました。そうすると、品川区民も、そういうことだったら、では原則の品川区に納税しようかという思いも考えられると思うのですけれども、そうしたガバメントクラウドファンディングを必ず併せて利用しなくてはいけないというような規制をかけるよう、特別区長会を通じて、ぜひ言っていただきたいのですけれども、そうしたご提案について、いかがお考えでしょうか。","respondent":"提坂税務課長","answer":"お酒や食料品と、ガバメントクラウドファンディングの組合せですけれども、区民の方には残念ながら返礼品をお返しすることができないという実情がありますので、区民の方には、やはり先ほども申し上げたような、使い道を明記した寄附金を募るなどという形で。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"私が言っているのは、ふるさと納税制度はもう全体、全国で、返礼品目当てで行うのであれば、併せてその地方のガバメントクラウドファンディングに寄附をしなくてはいけないというような規制について言ったのですけれども、その辺りはいかがお考えでしょうか。","respondent":"提坂税務課長","answer":"その辺は品川区単独で判断できるものではないので、他自治体の動向も踏まえながら、動向を注視してまいりたいと考えています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"このままだと平行線をたどってしまうので、特別区長会を通じて、ぜひ厳しくご要望をおっしゃっていただきたいと考えております。よろしくお願いします。続いて、インターネット映像配信委託なのですけれども、３４６万円ほどかかっているかと思うのですけれども、このインターネット映像配信委託は、現行はどこかの業者に頼んで配信されているのでしょうか。今、現状の状況を教えてください。","respondent":"大澤区議会事務局長","answer":"インターネットの配信ですけれども、これは委託しておりまして、本会議の生中継と録画の中継、予算・決算特別委員会の録画中継を、インターネットを通して配信しているというものです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"一方、今、いろいろな、ほかの自治体の議会でも、ユーチューブで配信しているところが増えてきております。ユーチューブですと、編集しやすい。それによって、配信までの期間も短縮できる。ひいては、品川区、品川区政に対する関心ももっと呼び起こせるものかと思うのですけれども、その辺り、今後、ユーチューブで議会中継をやっていくというのはいかがでしょうか。","respondent":"大澤区議会事務局長","answer":"配信方法につきましては、しかるべき会議体でご議論いただきまして、ほかの方法でということでございましたら、事務局としましても、予算的なことやシステム的なことなど、いろいろあると思いますけれども、実現に向けてご対応させていただきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ、そうしたユーチューブ、最新の技術をどんどん活用していっていただいて、議会の広報力の強化に努めていただきたいと考えております。ぜひよろしくお願い申し上げます。続いて、特別区たばこ税について伺います。これは、たばこ税増税といったこともあるのでしょうか。特別区たばこ税が増えている原因についてお聞かせください。","respondent":"提坂税務課長","answer":"令和４年度と令和３年度を比較した場合、やはり２億６,５００万円ほど増収になっておりますが、コロナ禍の影響でテレワークの方が増えたということが、たばこの喫煙が増えたものなのか減ったものなのかというのが、なかなか分析は難しいところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"なるほど。コロナ禍も経て、そうしたテレワークなども進み、今まで考えられなかったような原因で、たばこ税が増えているということだと思います。したがいまして、これはやはり今後、急激に減ることなく、むしろ安定財源として、たばこ税が定着するというお考えでよろしいのでしょうか。","respondent":"提坂税務課長","answer":"安定した財源ということで、貴重な税目ということで注視してまいりたいと考えています。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１６０ページ、広告料収入と、６８ページの公園運動施設使用料について質問します。広告料収入について質問します。広告料収入の内訳について教えていただけますでしょうか。掲載している企業の分野の例や、媒体ごとの収入をお伺いできればと思います。目標対比にしても教えていただければ幸いです。","respondent":"遠藤財政課長","answer":"こちらの関係で約６１８万２,０００円、それから経理課で広告用の周辺案内板、このような形で広告がつきまして、こちらが２００万円余となっております。庶務課で教育委員会の広報紙の広告掲載ということで、５万円ほどの歳入をしています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"確認","question":"今、主に紙面等での静止画の広告を表示しているところだと思います。そこで、デジタルサイネージについてもお伺いしたいです。事務事業概要より、現在、品川区内においてデジタルサイネージは２９台設置されていると確認しました。さらに、静止画やテキストに比較して、視聴者の印象に残りやすい動画コンテンツについての導入状況をお知らせください。","respondent":"辻広報広聴課長","answer":"委員がおっしゃいますとおり、全部で２９台、庁舎や地域センターを中心に配置しています。内容としましては、最近ですと、手話のＰＲ動画や、あとは特殊詐欺の防止のことなど、各所管課からいただいたものを流していることが中心です。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"設置場所によって、特徴を捉えて様々なコンテンツを表示していることと理解いたしました。一部の区では、デジタルサイネージを活用して広告料収入の増加を図る取組があるようです。例えば江東区では、デジタルサイネージを活用する広告を募集していて、その財政効果は全体で１,５００万円ほど見込んでいて、当区の収入額の約１.５倍以上の収入を想定しています。この点の見解も併せて伺います。","respondent":"辻広報広聴課長","answer":"今後、デジタルサイネージの置き場所も含めまして、多分、別の場所になった場合には、また検討の俎上にのるかとは考えております。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"最後に、広告料収入の増加が品川区の収入確保にどのように貢献するとお考えか、また今後の展望についてご意見をお伺いできればと思います。広告収入を活用して、区の発展と住民サービスの向上に貢献する方法について、お考えをお聞かせいただけますでしょうか。","respondent":"遠藤財政課長","answer":"広告料収入のこれからの増加ですけれども、やはり一般財源として自由に使えるお金が少しでも多いというのは重要かと考えています。今後も広告収入をはじめ、様々な財源の確保に努めていきたいと考えているところです。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"次の質問に移りたいと思います。公園運動施設の使用料について質問します。今回、収入未済額が少々発生しています。未済が発生するケースと、未済が発生する主な要因やパターンについて、詳細を教えていただけますでしょうか。","respondent":"三井スポーツ推進課長","answer":"公園運動施設使用料の収入未済の内訳になりますが、まず口座振替で引き落としができなかった方が１０件程度で、約１１万円ぐらいになります。もう一つが、当日予約で利用した納付書払いでの支払いがなかった方が５件程度で、約３万円ほどとなります。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"公園運動施設の当日利用が可能であるという点は、利用者にとって便益のある点と思われます。その際、当日払いが今できないという状況と聞いたのですけれども、こちらの当日払いを可能にすることで、納付漏れが減少したりというお考えがありますでしょうか。伺いたいと思います。使用料金の支払いが滞った利用者・団体に対してのアプローチなのですけれども、さらなる検討がされているか、伺います。","respondent":"三井スポーツ推進課長","answer":"支払い方法の多様な手段があればということでご指摘いただきまして、今後やはり支払い漏れがないようにしていくためには、キャッシュレスなどの対応も含めて検討していく必要があると考えております。","id":"exchange-039"},{"speaker":"せらく委員","kind":"意見","question":"皆様が利用しやすい施設になるように、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に、児童相談所新築についてお伺いいたします。私は、児童相談所の準備から開設当初におきまして、特に児童相談所に対しての職員配置や、必要なときに必要な物品をすぐさま手配していただくなど、人事と財政部門からの理解と協力ということについて、２０１７年９月の行財政改革特別委員会、２０２０年９月の一般質問でお伺いしました。総務使用料、産業経済使用料、雑入についてお伺いいたします。","respondent":"崎村人事課長、遠藤財政課長、若生健康課長","answer":"そういった状況に応じた職員配置が可能となりますよう、所管部署と連携しながら柔軟な職員体制の確保に努めてまいりたいと考えております。今、都区の財政調整の部分ですけれども、９月６日に都区と協議が、一応、一旦整えた形になりまして、令和５年度は、令和４年度の協議を継続というところで。委員ご案内の骨硬度チェックは品川健康センターで行っておりますが、こちらにつきましては、指定管理者が独自サービスで任意に行っているものですが。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"児童相談所につきましては、開設に向けて引き続き子どもたちのために、区全体で一丸となって準備を進めていただきますようお願いいたします。３点目に、衛生費補助金、民生費補助金、学校保健特別対策事業費補助金についてお伺いいたします。こちらは時間がありませんので、要望までになってしまうかもしれないのですけれども、まずグリーフとは何でしょうか。は高田敏子さんの詩からご紹介いたします。","respondent":"榎本荏原保健センター所長","answer":"そういった中で、不安定な状態で、身体面にも影響が出ることがあります。保健センターでは、不調が続いている場合など、ご自身で悩まれてご相談がある場合もありますが、心の相談という形で、丁寧にお気持ちを聞いてご相談対応に乗っております。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"都支出金、１３４ページ、学校・家庭連携推進事業費、いじめ防止対策事業補助金、１３７ページ、マイスクール運営費より伺ってまいります。いじめ防止対策事業は、いじめ防止となっておりますが、不登校児童生徒や家庭の支援も行っていると伺っておりますので、これらを含めまして不登校対策について伺ってまいりたいと思います。改めて、学校・家庭連携推進事業の現状を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"私からは学校と家庭の連携推進事業について、お答えいたします。令和４年度は１１校、令和５年度は１６校で実施しております。校内にスペースをつくり、学校には来られますが教室には入りにくい児童・生徒の居場所となっております。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"ほかにもいろいろな取組がありますけれども、先日、会派でマイスクール八潮に訪問させていただきまして、保護者からも、活動が子どもたちに人気だとは伺っていたのですけれども、実際、校長先生よりお話を伺いまして、カジ釣りのお話が大変興味深く、八潮ならではの水辺の環境のよさと、勉強だけではない自分に合った居場所を見つけられる取組だと、改めて感銘を受けました。","respondent":"丸谷教育総合支援センター長","answer":"例年、年度末に向かって利用者数は増加する傾向があり、利用する曜日を調整しながら受入れを行っているという現状があります。送り迎えが難しいエリアのご家庭があることも認識しております。","id":"exchange-044"},{"speaker":"西村委員","kind":"質問・要望","question":"マイスクール八潮まで荏原からバスが出るといいなどという保護者の声も聞いたことがあったのを今思い出したのですが、なかなかすぐにハード面の整備ができずに試行錯誤してくださっているのはよく分かっておりまして、同じく会派の視察で景徳学園へ伺わせていただいた際に、荏原第五中学校でランチルーム登校があるというお話を伺っております。","respondent":"丸谷教育総合支援センター長","answer":"令和５年度からは、校内別室指導支援員配置事業を活用し、退職校長や大学生を支援員として、教室に入れない生徒の学習支援等に取り組んでおります。","id":"exchange-045"},{"speaker":"西村委員","kind":"質問・要望","question":"学校以外にどのような居場所をつくれるかというのが、今日質問させていただきたい軸なのですけれども、そういった意味におきましては、フリースクールとの連携も喫緊の課題かと思います。プレーパーク運営者の方に伺うと、実際に不登校になってプレーパークに来ていたお子さんがいると。区のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"区立図書館をはじめとする区内施設やフリースクール等との連携、またメタバースといった仮想空間の活用などが考えられると考えております。今後、国や都の動向も注視しながら、児童・生徒、そしてご家庭の安心につながる取組を検討してまいりたいと考えております。","id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"今日、一番ご提案させていただきたいのが、不登校になる前の行き渋りの入り口の段階でサポートできる支援をご提案させていただきたいと考えています。親御さんとしても、どうしていいか分からないので、選択肢を見せてあげる１つの方法として、品川区版の子どもたちと保護者のための不登校支援サイトの開設ができないかと考えています。","respondent":"丸谷教育総合支援センター長","answer":"今後、ホームページの内容をより充実させたり、品川区版のフリースクール等も含めた掲載をしたガイドブックを作成するなどして、保護者への十分な案内ができるように努めてまいりたいと考えております。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問・要望","question":"学校と家庭の信頼関係がベースではありますけれども、場合によっては家族関係が問題のこともあると考えています。親が希望すれば、ペアレントトレーニングなどの受講ができるように、先生からは促せなくても、促すことが難しくても、サイトに掲載できるとすごく理想的だと考えていますが、区のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"家庭に起因するような場合であっても、現在、ＨＥＡＲＴＳが対応させていただいて、必要な支援や関係機関とのつなぐ役割を果たしております。今後とも、そうしたこともできるということを広く周知してまいりたいと考えております。","id":"exchange-048"},{"speaker":"西村委員","kind":"意見","question":"少し違う話にはなりますが、一旦、息抜きをするという機会も大事かと思っておりまして、地方で親子で宿泊体験型の学習があったり、品川区もいろいろな市区町村と連携がありますので、こういったところとの、品川区を出た活動もあってもいいのではないかと思いますが、ご見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"そうした社会的な自立に向けた有意義な取組になっておりますので、今後も継続してまいりたいと考えております。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"放課後の過ごし方も、いろいろな選択肢があっていいですから、学校に行かなくても、バンドの練習ができたり、絵が好きな方は絵ができたり、そういった場所も、品川区の中で児童・生徒のために増やしていってあげたいと私は思っておりますが、区のお考えをお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒が様々な興味や関心を持ったものにチャレンジできる、そうした取組が大事だと考えております。現在では、放課後については、地域未来塾等で学校の中でサポートできるものが多くありますけれども、今後そうした場の提供についても検討してまいりたいと考えております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"５２ページ、特別区民税、１０２ページ・１３４ページの埋蔵文化財調査費、１２２ページのベビーシッター利用支援事業（一時預かり利用支援）補助金について伺っていきたいと思います。特別区民税ですが、最近ずっと決算特別委員会のときに伺っています。品川区の平均所得が、区民の税金所得が年間５００万円ぐらい。要は世代のバランスだと思うのですが、この辺りについて今の区の考えをお知らせください。","respondent":"佐藤企画課長","answer":"このような激動の時代におきまして、子ども・子育て支援、虐待・いじめ対応、高齢者・障害者福祉の推進や首都直下地震への備えなど、様々な行政課題があります。そういった面に関しまして的確に対応していくためには、財源の確保が非常に重要です。","id":"exchange-051"},{"speaker":"つる委員","kind":"提案","question":"しっかりと、議会側の声も受け止めていただきたいと考えています。政策評価委員会は１１月ですか。『品川区史』を、最近というか、２０１４年につくって、ちょうど１０年。これは、実は２００３年ぐらいだったでしょうか、先輩議員が、こうした委員会の場で、やはり郷土史の大切さというところで、この書籍を引用されながら質問をして、当時において推進をいただいたという質疑も確認させていただきました。","respondent":"宮尾庶務課長","answer":"今、郷土史の作成のご支援についてのお尋ねをいただきました。年間に、同じようなご相談、お問合せを、数件ですけれどもお寄せいただいております。その場合には、私どものほうに学芸員の資格を持った職員がおりますので、その職員が基本的にはいろいろなお手伝いをします。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"ベビーシッターの利用支援事業（一時預かり利用支援）補助金について伺っていきたいと思います。これは、２０２０年３月、予算特別委員会を皮切りに、この予算を活用して、１０分の１０だからというところで、品川区も活用し、求めて、２０２２年ですか、令和４年度から実施いただきました。この辺りの分析など、なぜそういうふうになっているのか教えてください。","respondent":"石井保育支援課長","answer":"こちらは、令和４年度後半にかけて、かなりの申請等をいただいてございまして、当初予算の要求時には、そこまでの状況が想定されずに、４,５００万円ということで計上したところです。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"当然、１０分の１０ですから、結果に基づいて請求すればそれだけ返ってくるところがあるわけですけれども、しっかりその部分については、例えばこれは年４回、今は清算する利用者のタイミングがあろうかと思います。４回、チャンスがあって、利用者にしてみれば、４回それぞれやるのもいいでしょうし、１回だけで済ませるという方もいらっしゃる。","respondent":"石井保育支援課長","answer":"今年度は１つの係だけに任せることをせず、課全体で、チームで審査を行っていくということで工夫をしていますが、さらに件数が増えるといったことがある場合については、委託等々の手法も含めて、もろもろ検討していきたいと考えています。","id":"exchange-054"},{"speaker":"つる委員","kind":"提案","question":"当然、利用できる時間、１４４時間、それから多胎児については２８８時間ということで設定いただいています。これを提案させていただいた当時も含めて、区民の方の声も、やはりこの事業が必要だから、これだけぎゅっと、たくさん利用者も多いということですので、引き続き、そうした両方の視点を含めて、この強化を図っていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"初めて質問いたします。こちらで質問する機会をいただき、感謝申し上げます。では、本日は、２６ページ、国民健康保険、３２ページ、後期高齢者医療、１２６ページ、健康増進事業費についてお伺いいたします。高齢者の健康維持、介護予防についてお伺いいたします。皆様ご存じのとおり、日本も高齢化の一途をたどり、この品川区でも２０１８年度以降は、後期高齢者数が前期高齢者数を上回っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"分かりました。すみません。そうしましたら、しながわシティマラソンの進捗状況についてお伺いいたします。こちらではどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問・要望","question":"今までの企画をまたよりリニューアルして、非常に品川区の観光などもアピールできる点がいいと思いますので、ぜひ新しい企画に向けて取り組んでいただきたいと思います。続きまして１２６ページ、健康増進事業費についてお伺いいたします。こちらの健康づくり支援事業に関して、現状をお聞かせください。","respondent":"若生健康課長","answer":"現状としましては、品川区では各種健康診査をやっておりまして、健康課で所管している健診といたしましては、二十歳からの健康診査、それから医療保険未加入者の方への健康診査、その他、肝炎ウイルス検診、眼科検診。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"提案","question":"１つ提案があります。毎朝、お互いに顔を合わせての健康確認や、外に出る習慣づけ、友人づくりにもなっており、高齢者をはじめ、地域の方々にとって多くのメリットがある、昔からの朝の風景です。多くのメリットのある地域のラジオ体操も、健康プランの一部に組み入れて、助成金を出すのはいかがでしょうか、区の見解をお聞きいたします。","respondent":"若生健康課長","answer":"最近、少し参加者がというところもあるとも耳にしています。地域の中で行われている活動の中で、健康プランへの位置づけや、助成金というようなお話もありますけれども、そういったものも含めて、今後そういった支援ができるかどうかというところは考えてまいりたいと思います。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"これからも、こういったケアと予防の双方で、元気な品川区をつくっていきたいと思います。これで本日の質問を終了いたします。一部、混乱した発言があったことをおわびいたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"山本委員","kind":"質問","question":"私からは、１０５ページの就学援助費、時間次第で１１５ページの中小企業事業資金融資あっせんについて伺います。１０５ページの就学援助費について伺います。","respondent":"柏木学務課長","answer":"就学援助のお尋ねです。令和４年度の実績ですが、申請者数は４,４９９人、認定者は３,３４３人で、申請者に対する認定率は７４.３％です。全児童・生徒に関わる受給率は１５.１％となっています。","id":"exchange-061"},{"speaker":"山本委員","kind":"意見","question":"１５％を超える方々が利用されているという現状、それから申請者に対して２５％ほど、利用できていない方がいらっしゃるという現状を理解いたしました。就学援助制度については、引き続き、保護者の負担を軽減するための援助・拡充に向けた検討が必要であると思いますが、区のお考えをお聞かせください。","respondent":"柏木学務課長","answer":"就学援助の事業につきましては重要な事業と考えています。就学援助の対象の拡大につきましては、品川区は特別区の中でも基準は高いほうと考えていますが、引き続き、他区の状況を注視しながら考えてまいります。","id":"exchange-062"},{"speaker":"山本委員","kind":"質問・要望","question":"私も、品川区はほかの区に比べて高い水準を維持していると思いますが、さらに取り組んでいただきたいというところでございまして、２点ご要望申し上げます。１点目は、物価高騰に応じた学用品費の月額援助額の増額。２点目は、生活の厳しさが増しておりますので、必要な世帯への援助が行き届くよう、援助対象者の所得金額の上限の引上げについてもご検討を要望いたします。区のお考えをお聞かせください。","respondent":"柏木学務課長","answer":"就学援助の月額の物価スライドについてですが、就学援助の支給額ですが、基本的に都区財政調整の基準額を基に、毎年度、見直しを実施しています。","id":"exchange-063"},{"speaker":"山本委員","kind":"質問","question":"課題もあるということですが、できる限りの前向きなご検討をお願いいたします。続けます。今年度から開始した学校給食費無償化は、とてもよい取組であると考えております。子育て世帯を応援するため、全ての家庭でかかる就学費用の負担削減に向けた取組は、品川区の子育て教育施策の中で重要な課題の一つであると考えますが、いかがでしょうか。区のお考えをお伺いいたします。","respondent":"柏木学務課長","answer":"保護者の負担の軽減は必要なことと考えています。学用品に限らず、保護者の負担を軽減することについて検討してまいります。","id":"exchange-064"},{"speaker":"山本委員","kind":"提案","question":"区のお考えが確認できて、ありがとうあります。手法として、私から３点、ご提案申し上げます。品川区が学校と連携し、無償ではなく廉価での買取り販売をし、幅広くリユース品を流通させ、利用できる仕組みを整備することはいかがでしょうか。発注先をコンペで比較し、１つのメーカーに大量発注するなどの工夫、取組を実施すれば、現状よりコストダウンが図れるのではないかと考えますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"幾つかご提案をいただきました。保護者の負担軽減は必要なことと先ほど答弁させていただいた考えには変わりはございません。学校とも相談しまして、方法等も含め、今後検討してまいります。","id":"exchange-065"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひとも、手法について今後ご検討いただきたいとお願いいたします。次に中小企業事業資金融資あっせんについてお伺いしたいと考えておりましたが、時間も限られておりますので、次の機会に移したいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問","question":"福祉の聡こと、やなぎさわ聡です。今日は有意義なお話ができればと考えております。よろしくお願いします。私からは、１２０ページの介護人材緊急確保対策事業費補助金の１点勝負で行きます。令和４年度になって、各１件ずつで合計２件ということで、かなり実績が乏しいのですけれども、区としてのお考えはいかがでしょうか。どういうことでこんなふうに使われていないのかということで、お願いします。","respondent":"菅野高齢者福祉課長","answer":"各法人、そういった専門職の確保については努めているところではあると思いますが、実績としてこういう結果になったというところで、今後どういった形で１件ずつだったのかというところも法人等に聞き取りをしながら、よりよい方策については検討していきたいと考えています。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"提案","question":"なぜかといいますと、東京都、神奈川県、千葉県、埼玉県は、ほとんど対象外なのです。遠隔地の対象外になっている。かなり地方に入っている。そういう意味で言えば、やはり、しっかりと、緊急介護職員確保と銘打っていらっしゃるわけですから、その辺のことも、もっと検討したり、いろいろな介護事業所にぜひ聞き取りを行ってほしいと思いますけれども、そういった取組を今後検討していただけるでしょうか。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘の、遠隔地からの人材確保支援につきましては、１法人ずつだったり、１年に一、二件だったりということがあるのですけれども、ただ、こちらにつきましてはないわけではないというか、例えば外国人の人材確保で、外国人の方とお話をしたときに。","id":"exchange-068"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういう事例もあるのかもしれないのですけれども、遠隔地の人材確保事業というのは、令和２年・３年・４年と、０件なのです。やはり使い勝手が悪いし、むしろ、条件をもっと緩和して、早急に実施してほしいと思います。ただ、直近のデータで、ヘルパーの有効求人倍率は１５倍です。１人の求人者に対して１５社、うちに来てくださいという状況です。争奪戦です。早急に実施していただけますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"その次の、引き継ぐ世代の人がいないというようなお話も聞いておりますので、区の実情に応じた形で、事業者の支援に可能な限り努めていきたいと思っているところです。","id":"exchange-069"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そのとおりなのです。ヘルパーの４人に１人、４分の１が、６５歳以上の高齢者なのです。もう間もなく、もう、いつ引退してもおかしくない状況なのです。ということは、急務なのです。なので、やはりこれはスピード感を持ってやらないといけないことだと思います。４人に１人なのです。５年もしたら、４人に１人が７０歳になってしまうという状況で、なのに離職率が高い。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"澤田委員","kind":"質問","question":"１１６ページ、民生費補助金、高次脳機能障害者支援促進事業、１６２ページ、リサイクル資源売払収入。この２つから、お伺いします。１１６ページの民生費補助金、高次脳機能障害者支援促進事業についてお伺いいたします。都の補助金として、高次脳機能障害者支援促進事業には１５７万９,０００円の歳入がありますが、どのように活用されているのか、内訳をお聞かせください。","respondent":"松山障害者支援課長","answer":"区立心身障害者福祉会館に配置しております、高次脳機能障害者の専門相談員の人件費相当分です。週に１日、障害者の方、ご家族の方のご相談をお受けしまして、訓練や復職など、本人が希望される支援につないでおります。２人の専門相談員が交互に対応しているものです。","id":"exchange-071"},{"speaker":"澤田委員","kind":"質問","question":"そのためにも、周知・啓発するためのリーフレットは重要だと考えますが、現在、心身障害者福祉会館などに設置されているリーフレットは、しばらくデザインが変わっていないのかと思うのですが、同じデザインのものが同じ場所にあると、人の目に入りづらくなってしまうという懸念もありますので、今年度、ぐるっぽでの高次脳機能障害を対象とした講座が開設されることを受けまして。","respondent":"松山障害者支援課長","answer":"今後、多くの区民の方にご理解いただけるよう、心身障害者福祉会館や、ぐるっぽ等の指定管理者の方々と協議をして、リニューアルの方向で検討を進めたいと考えています。","id":"exchange-072"},{"speaker":"澤田委員","kind":"質問・要望","question":"今は、事業者の方、関係機関の方に向けたリーフレットということですけれども、ぜひ多くの区民の方に手に取っていただけるようなリーフレットのリニューアルを、よろしくお願いいたします。相談窓口とケアマネジャーの方、病院、リハビリテーション施設、障害者施設など、様々な関係機関との連携をより一層深め、強化していただきますことを要望いたしますが、区としてのお考えをお聞かせください。","respondent":"松山障害者支援課長","answer":"高次脳機能障害の方への関係機関の連携についてのご質問にお答え申し上げます。連携機関といたしましては、東京都から指定されました荏原病院というところが、高次脳機能障害の普及・啓発の拠点病院となっております。","id":"exchange-073"},{"speaker":"澤田委員","kind":"質問","question":"困難を抱えた当事者やご家族のためにも、ぜひ今後とも引き続き検討会をよろしくお願いいたします。続きまして、１６２ページ、リサイクル資源売払収入についてお伺いいたします。増額に至った理由はなぜだとお考えでしょうか。令和４年度のリサイクルの収入の内訳として、何によるものが一番多いのでしょうか。区としてのご見解をお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"最近のプラスチックのリサイクルの傾向といったものが大きく影響しているのではないかと考えています。２番目の質問に対しても、収入の中で一番大きいものを占めているというのはペットボトル。それから、あとはアルミ缶なども、かなりの収入の多くを占めているものです。","id":"exchange-074"},{"speaker":"澤田委員","kind":"質問・要望","question":"収入の増額に至った理由としては、ペットボトルの単価の増額やアルミ缶の売却ということが大きいとのことでしたけれども、昨年度、環境省による、プラスチックに関わる資源循環の促進等に関する法律が施行され、プラスチック製品全般の資源化を求められることとなりましたけれども、よりリサイクルが推進されるように、ごみ資源をしっかり回収し、売り払うことができれば、その収入がすなわち区の収入となり。","respondent":"品川品川区清掃事務所長","answer":"今まで啓発している中で、収入金額、皆様がリサイクルで出している金額がこれだけ反映していますという説明というのは、あまりしてきていなかったかという傾向がありますので、そういう啓発を行う際には、ぜひそういう部分も参考にしながらやっていきたいと考えております。","id":"exchange-075"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、５２ページの特別区民税について、６０ページの特別区財政調整交付金、時間があれば、たばこ税、ふるさと納税と、お聞かせいただきたいと思います。その辺も、お考えをお知らせください。なぜかというと、品川区からも、４人の都議会議員が選出されるのですが、後ろにも元都議会議員がいますが、都議会議員になると、急に東京都の立場になってしまうのです。よろしくお願いします。","respondent":"提坂税務課長、遠藤財政課長","answer":"これはどういう状況かと申しますと、令和３年中の都内の中小企業が、景気が落ち込んだということで、様々な経済支援策などで、令和２年１月が底だったのですけれども。９月６日に、都区協議会で合意いたしまして、こちらは引き続き５５.１％ということで、金額については確保したです。こちらにつきましては、２３区が一丸となって交渉したという結果であるかと思っているところです。","id":"exchange-076"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。これは、子どもが見て、どう思うか。一回、一般財源に入ったら全部一緒なのだと言うのだけど、だって、払っている人は違うのだから、たばこ税として払っているのだから、この辺はしっかり考えていただきたいと思いますが、その辺の考えを教えてください。だって、品川区は魅力がいっぱいあるではないですか。何で、ふるさと納税になると急に、やらないと言ってしまうのですか。","respondent":"河合生活安全担当課長、提坂税務課長","answer":"ですので、私たちも住民等の声を聞きながら、前向きにやっているところです。民間喫煙所の補助事業というところで協力していただいているところに助成する形で、整備を進めていきたいと考えております。ふるさと納税のお尋ねですけれども、やはり物より事ということで、品川区の魅力をアピールできるというようなことを念頭に、様々な関係団体のご協力も得ながら、体験型や企画型の返礼品を開発しまして、品川区に来ていただく。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問","question":"私からは、１００ページ、防災・安全交付金の中から路面維持管理費、１２０ページ、高齢社会対策包括補助金、１２４ページ、ひきこもり支援推進体制立ち上げ支援補助金、順不同で質問します。エールしながわは令和元年より開始しておりまして、４年がたっているわけですけれども、今年度も予算計上されて、補助金の使い道は機能強化だというご説明が、今年の３月の予算特別委員会でありました。","respondent":"藤村子ども育成課長","answer":"令和５年度に関しましては、システム関係の導入等を考えているというところで補助金に充当しているような形です。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、事業評価を最後にいただいて、一定の社会体験で社会復帰ができているという評価をいただきました。当事者や家族の方など、支援を必要としている人に支援が届くようにしていけるためには、ひきこもりの早期発見とアウトリーチの仕組みづくりが必要ではないかと考えますが、この点についてご見解をお聞かせいただきたいのと、現在そういうことで取り組んでいることがあればご紹介ください。","respondent":"藤村子ども育成課長","answer":"委員ご指摘のとおり、ひきこもりの対策ということで、エールしながわに直接来られたり連絡をしていただけるような方というのは、今後、ひきこもりから脱却するというところの１つのプロセスを経ているのかとは思いますけれども、こちらに来られないような方々というところ。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"地域の方の情報提供といったことも大事だと思います。町田市では、ひきこもりの当事者の調査を行っております。特に、当事者や家族にとって、どのようにアプローチしてもらうことが支援につながりやすいのか、こうしたことの点をつかむ意味でも、調査をしながら、タイミングを捉えて、必要な方へ必要な支援が届くような仕組みの構築を検討してはどうかと考えますが、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"そういった中で、当事者と家族をつなぐような仕組みというところ、また調査についても今後どういった形で行っていけばいいかというところを考えつつ、必要な支援というところも併せて検討していけたらと考えています。","id":"exchange-080"},{"speaker":"こんの委員","kind":"確認","question":"次の質問に参ります。次は、高齢社会対策包括補助金の中で、高齢者の安否確認事業についてお聞きいたします。この実績についてですけれども、ここ３年の推移では、利用者の数は約８００件前後となっております。現在の高齢者数、約８万人強の人数から見て、利用者はこれだけなのですかと、とても少なく感じるわけですけれども、利用実績の現状についてどのように分析されていますでしょうか。","respondent":"東野福祉計画課長","answer":"品川区高齢者救急代理通報システムにつきまして、私から答弁します。利用者数の、まず推移ですが、令和２年度７８３件、令和３年度７７６件、令和４年度８３１件ということで、設置の件数が推移しています。","id":"exchange-081"},{"speaker":"こんの委員","kind":"提案","question":"実績の状態が分かりました。受給者を担当するケースワーカーは、１人で約１００人強の受給者を担当していると聞いております。ですので、緊急通報システムの設置が大事だと考えますけれども、受給者も併せて設置する、また周知する、受給者については安否確認体制の構築をこのシステムでつくったらどうかと提案いたしますが、いかがでしょうか。","respondent":"東野福祉計画課長","answer":"生活保護の関係につきましては、生活保護の担当の部局と連携を取りまして、区として周知方法につきましては考えてまいりたいと思います。区の広報やＳＮＳなどにつきましても、周知方法の拡大を考えてまいりたいと思います。","id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"周知方法を拡大してくださるということで、今、ＳＮＳでもという話ですが、高齢者はなかなか、ＳＮＳを使って果たして周知が広がるのでしょうかというところが気になります。生活保護の方については、周知はします。ですが、月３００円の代金はなかなか生活的に難しいということも考えられますので、双方、所管が前向きに検討していただくように調整を取っていただけたらと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、成果報告書の６１ページ、６２ページ、決算書では１４ページ、区民税、地方消費税、それから基金について伺いたいと思います。もう一つ、８６ページの生活保護費で扶養照会について伺いたいと思います。非課税世帯の推移がどうなっているのか、増えていることはないのか、また非課税世帯の所得は下がっていることはないのかと危惧していますが、どうでしょうかということで伺いたいと思います。","respondent":"提坂税務課長、遠藤財政課長","answer":"それで、その中でもとりわけ高額所得層が多いと思われる５０代から６０代前半の方の人口の伸びが顕著だというところが、住民税が増えている理由かと考えています。そちらの部分でかなり基金を使わせていただきましたので、少し今現在、少ないような状況がありますので、今後もできるだけ積み増すような形で考えているところです。","id":"exchange-084"},{"speaker":"鈴木委員","kind":"質問・要望","question":"例えば、商店街を回ったときに、７月から実施された省エネルギー対策設備更新助成金、上限８０万円が非常に助かったということを伺いました。申請期間が来年１月３１日となっていますけれども、私はこれを延期して、来年度もぜひ継続していただきたいと思いますが、その点を１点伺いたいと思います。家賃や電気代など、固定控除もしていただきたいと思いますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"品川区としまして、ゼロゼロ融資の対応ということでいきますと、借換専用資金という制度を設けてございまして、ちょうどコロナ時期に資金調達を行って、これから本格的に支払いが始まるという方で、これからまだ具体的に元本の返済が厳しいという方については。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問","question":"こういう商店街の大変な実態に対して、区としてどう捉えられているかということと、区として今後、やはり品川区の魅力である商店街に対して、それを元気づけていくためにどんな支援がされようとしているのかについて伺いたいということで伺ったので、お願いします。","respondent":"小林商業・ものづくり課長","answer":"このようなものに対して、設備資金、運転資金というものに対して、区が一定の負担をすることによりまして、今後の前向きな取組を支援するというような制度がございまして、こういう取組を含めまして、商店街の、元気が出るというのですか。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点では、やはり品川区の魅力、それから住み続けたい地域の魅力でもあります商店街を衰退させるのではなくて、元気で魅力のある商店街とするためにも、ぜひ豊かな財政を使って支援していただきたいということで、要望します。それから、地方消費税も前年度より９億９,０００万円増収になっています。この理由についても、どう捉えられているのか、伺いたいと思います。","respondent":"遠藤財政課長","answer":"新型コロナウイルス感染症対応地方創生臨時交付金のお話です。今年度の歳入につきましては、今、手元に持っていないのです。申し訳ございません。ただ、今年の５月補正で、全てそちらの金額については活用させていただきまして、充当させていただいているです。","id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問","question":"そのインボイスの問題で少し伺いたいのですが、今回の共産党、のだて区議会議員の一般質問で、企画部長が、「インボイス制度は消費税額を適正に納付するための手段。消費税は地方財政を支える財源でもある。インボイスの周知・啓発というのは何のために行ったのか、伺います。インボイス制度は、消費税を預かっていながら納めなかった免税業者に納めてもらう肯定なものとの考え方なのか、伺いたいと思います。","respondent":"遠藤財政課長","answer":"物価高が３％程度という形になっておりますので、もちろん一因ではあるかですけれども、ほかの要因も大きいのかと考えているところです。それから、インボイス制度の適正なですけれども、今回、課税事業者につきましては、登録番号等を書くような形になるということです。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"適正な納付というところでは、預かった税金なので納めてもらうというところでの公正というところではないのか、そこの点を伺ったので答えていただきたいと思うのですけれども、そういうことでしたら、預かった税金、益税ではないということで、国会の論戦でも裁判でも決着がついているということで、お話をさせていただきたいと思うのですけれども。","respondent":"遠藤財政課長","answer":"消費税につきまして、いわゆる価格の一部、益税など、いろいろな議論があったというところにつきましては、例えば新聞なり報道なりということで見ているところではありますけれども、そこの部分につきまして区として何かというところになりますと。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問・要望","question":"適正な納税という認識は改めていただきたいと思うのです。そのことは、国会答弁でも裁判の判決でも、はっきりと決着がついているということで、適正な納税という区の認識はぜひとも改めていただきたい。５５０万円です。実際の年収は１５４万円です。それから、アニメーターの方からも伺いました。ここにインボイスがかかってきたら、本当に大変な状況だということも、区も認識していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"田中委員","kind":"確認","question":"７対３の仕事をやっておきながら、７％分の財源しか入ってきていない。それで、主張する以上は、議会自らも改革をしなくてはいけないということで議会改革に臨んで、結果的な数字としては４,７００万円の減少になったのではないかと推測しておりますが、実際に減額されたことに伴って、議会運営上、何か問題が新たに発生したということがあるのかどうか、その点をまずは確認したいと思います。","respondent":"遠藤財政課長、大澤区議会事務局長","answer":"こちらは、通常であれば、先ほど委員がおっしゃったとおり、３割程度のお金をもらえるところですけれども、おっしゃったとおり、７％という形になりまして、残りの部分につきましては財政調整の特別交付金ということで。議会費を減額したことで、運営上特に困ったことがあるとは認識してございませんが、やむを得ず減額になった分、例えば行政視察に、この間、コロナの間は行くことができずに、視察の中でいろいろ皆さんに学んでいただいて。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"１番は世田谷区で、２番が実は品川区であります。つまり、本来、税金として入る仕事以上に、品川区の都市計画事業がなされているというプラスの評価をしておるのですけれども、その辺を踏まえた中での、この議論について、お考えをお聞かせいただきたいのと、議会費については、より有効に運営できるように、新年度以降の議会費の議論にも、今のご答弁を活かしていきたいと思います。","respondent":"遠藤財政課長","answer":"都市計画交付金につきましては、おおむね２５％という基準があって、それにプラスマイナスの、事業費に対してなのですけれども、最終、いただけるということなのですけれども、この事業費につきましても、なかなかその満額を見てくれなかったりというところもあるです。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"都区協議の中で、その上限を撤廃してほしいという項目も入っているかと思いますので、そこもしっかり主張していただきながら、特別区の財源確保に努めていただきたいと思いますが、特に決算特別委員会としての質疑でいうと、令和４年度の収支で、予算現額が約７億５,４００万円に対して収入済額が約５億９,５００万円ということで、予算よりも事業執行が減っているのです。","respondent":"遠藤財政課長","answer":"先ほど言った東京都の配分割合というところで、２５万円プラスマイナス１０％の、総額から逆算するような形で、いわゆるバッファを設けているところがありますので、そういうところを引き続き、こちらはできるだけ区の収入を確保できるよう努めてまいりたいと思います。","id":"exchange-093"},{"speaker":"えのした委員","kind":"質問","question":"私からは、１６２ページ、放置自転車等保管料についてお伺いします。自転車・バイクの放置禁止区域について、道路上や公園等の公共の場所に自転車・バイクを放置した場合、短時間でも撤去されますが、返還の際には撤去と保管の費用を徴収していて、自転車が３,０００円、バイク５,０００円になっています。短時間とは、具体的に何分、何十分、１時間程度なのか。","respondent":"工藤交通安全担当課長","answer":"短時間のご質問についてお答えします。具体的には、短時間に明確な定義はございませんが、１０分から２０分程度というようなところで捉えております。放置自転車の撤去の台数ですが、令和４年度、約９,０００台というところで撤去作業をしております。","id":"exchange-094"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。品川区と同様に、目黒区内の放置自転車は年々減少しているようですが、昨今の人件費高騰の影響もあり、撤去１台当たりの経費も高くなって、そのため撤去・保管料を引き上げました。改定前が、自転車３,０００円、原動機付自転車４,５００円、自動二輪車９,０００円。品川区としても、条例の改正が必要だと考えます。撤去・保管料の引上げについて、区のお考えをお聞かせください。","respondent":"工藤交通安全担当課長","answer":"条例の制定の部分につきましては、まずは電動キックボードが、委員ご説明のとおり、新たな乗り物ということで出てきております。こちらは、区としましては、まず交通安全に関するルールの周知、安全な乗り方等に関する周知を初めに行っていきたいと考えております。","id":"exchange-095"},{"speaker":"えのした委員","kind":"質問・要望","question":"６月１２日の建設委員会の答弁では、「放置自転車対策としては、駐輪場の整備、指導・啓発、撤去活動の３本柱で取り組んでいる。家に歩いて帰れない。重たい荷物をどうすればいいのかと、自転車撤去によりお困りの方が増えているとも伺っております。地域区民の現状も鑑みて、緩やかな撤去や、また指導・啓発の頻度、あと改めて周知も多くしていただきたいですが、区のお考えをお聞かせください。","respondent":"工藤交通安全担当課長","answer":"撤去の頻度ですけれども、こちらも頻度を多くした場合に、撤去自転車は増えるのですけれども、その分、費用も経費もかかるということで、その辺のバランスを見ながら、今後、有効な撤去活動をどうやっていけばいいかということを考えていきたいと考えています。","id":"exchange-096"},{"speaker":"えのした委員","kind":"質問・要望","question":"武蔵小山駅商店街周辺には、駐輪場が広範囲にわたってないというところです。区内２６か所ある区営の駐輪場が、武蔵小山駅周辺には１か所もないというのも要因として考えられますので、商店街と連携していただいて、店舗の休業日や、長期間テナントが決まっていない店舗前、また店舗内など、少しでも駐輪スペースを確保できるような取組をお考えいただいて、私からの要望とします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"石田（秀）委員","kind":"意見","question":"だけど、これは理由があって、私は区民の皆様に、もう、あなたのご協力のおかげですというのを、もっともっと打ち出すべきだと思っていて、これはもう２０３０年に飲料メーカーが、全量、ペットボトルはリサイクルすると打ち出したわけです。今、品川区のペットボトルは、皆さんがラベルを外してくださるレベルが高くて、７５％とか８０％ぐらいの方は外していただいているので、単価が高いわけだ。","respondent":"品川品川区清掃事務所長","answer":"そういうところが非常に、いろいろ買取り業者を選ぶところでも難しいところもあったりしますので、こういった点もいろいろ注視しながらやっていきたいと考えています。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ただ人口が増えたからということではないと思っているので、ある程度の所得の高い方が品川区にお引っ越しいただいたから、こういう形で増えたのではないかとか、こういうところの予想をまず教えていただきたいのと、先に行きたいのは監査委員の部分で、行政評価シート、これも今、六百六十何ページか、もらって、私はこれはもう、あまり量が多いと見なくなってしまうと思っているので。","respondent":"遠藤財政課長、吉岡政策推進担当課長","answer":"先になりますけれども、主要施策の成果報告書のお話ですが、こちらは地方自治法第２３３条５項の規定に基づいて、必ず議会に出す、報告するというものになっているところです。こちらについてご意見をいただいたところですけれども、今回約１０年ぶりに事務事業評価を実施するということで、全事業を行わせていただいたところではありますけれども、なかなか見にくいというご指摘もいただきました。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは、まず先に、どういう質問をするかを言っておきます。多分これも時間がなくなるので、後でほかのところでやらせてもらいますけれども、１つは、これは人材不足が必ず出てくるのだろうと思っています。これは多分やっていらっしゃるのだろうけれども、横断的にやるべきだというのを私は思っていて、これはぜひその考え方を教えていただきたいのと、これも収入もこだわってほしい。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"足の具合が少し悪いものですから、座って質問いたします。私からは、１７１ページ、議会費の中から区議会だより発行６回、約２,８７４万円からの質問です。区議会議員選挙が終わり、はや５か月が過ぎ、区議会議員として、区民の一員として、本区のためにも頑張っていきたいと思っています。区議会だよりからの質問です。６回まとめてでありますけれども、お聞かせいただきたいと思います。","respondent":"大澤区議会事務局長","answer":"区議会だよりの発行ですが、令和４年度につきましては、６回の発行のうち、定例号の４回および臨時号は全戸配布によりそれぞれ２４万部強、新年号は新聞折り込みと駅スタンドによる配布で１０万部弱、合計で１３０万１,６００部となっております。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区に対してどれぐらい興味があるのか。区民が本当に品川区に対してどういう気持ちを持っているのかにかかってくると私は思っています。品川区に興味を持っていただくこと。理事者の皆さんのお考えや、もしそういうアイデアがあれば、どのようにすれば一人でも多く、品川区のことに対して興味を持っていただくことができるのかという、何かアイデア的なものがあれば、お聞かせいただきたいと思います。","respondent":"大澤区議会事務局長","answer":"区民の皆様が、区に興味を持って、住み続けたいと思ってもらう要因というのは様々あるかと思いますけれども、先ほども少しご紹介しました、昨年度の世論調査の結果から見ましても、例えばインフラの整備や災害・防災対策。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問・要望","question":"しかし、一人でも多くの方々に区議会だよりを手に取っていただく、目を通していただくことは、私は大変大事なことだと思っています。これが、行政側の、品川区としての願いではないかと思っています。もしそれがあれば、何か、理事者の皆さんのお考えをお聞かせいただきたいのですが、いかがでしょう。","respondent":"大澤区議会事務局長","answer":"世論調査の結果ばかりで何ですけれども、世論調査の中でも、区議会へ関心があると答えた方は５０.２％と半数を超えておりまして、これも前回の調査時よりもアップしております。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"いや、本当に区民の皆さんが、ぱっと一目で何か目を引くようなものがあれば、写真や、あらゆることに対して努力されていることは大変よく分かりますし、これからもそのことは続けていただきたいと思っています。新聞自体にもっとイラストをつくったり入れたり、何かしたほうがいいのか。何かあればお聞かせください。","respondent":"大澤区議会事務局長","answer":"広報会議において、レイアウト等についてもご検討されているところですけれども、今後もコンセプトはそのままに、大事にすることはするのですけれども、タブロイド版からＡ４の冊子型に変えたように。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"私は、そこまで深く考えてやっているとは実際思っていませんでした。何をどうすれば、どのような記事を掲載すれば、目を通していただけるのか、頭の痛いところだと今まで思っていました。少しでも興味を持っていただくには、これからは何が今以上に必要だと皆さんはお考えになっているのか、お聞かせください。","respondent":"大澤区議会事務局長","answer":"そのような区民からのきっかけを待つだけではなくて、今、議会でも取り組んでいらっしゃいますけれども、例えば児童・生徒を対象とした本会議の傍聴や議場見学、新成人への区議会紹介のリーフレット配布等の活動もしていますけれども。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問・要望","question":"私たちは、ただそれを傍観しているだけではなく、我々区議会ができること、やらなければならないことはあると思いますけれども、それは何なのか、もしお考えがあればお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"木村委員","kind":"意見","question":"区議会議員からすれば、中には行政に対して興味を持ってくれている人がたくさんいると思っていることは確かであります。興味を持った、持つ、持たない。この境界線は何なのか。行政側としては、また私自身もあまりよく分かりませんけれども、もしよろしければ、そういう点をお聞かせください。それを教訓にしていきたいと思っています。","respondent":"大澤区議会事務局長","answer":"区議会や区政に興味を持つか持たないかということは、恐らく自分の毎日の生活にそのことが関わってくることに気づいているか、気づいていないかということだと思いますので。","id":"exchange-107"},{"speaker":"若林委員","kind":"質問","question":"議会側または区民が行政評価シートを見たり、また活用したりということは、また今後の大きな課題になると思いますけれども、まずは品川区として、このシートをどのように活用していくかというお考えをお聞きしたいと思います。活用というのは、いわゆるどういう成果をここから生み出していくのかというところをまずお聞きしておきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"行政評価シートの区の活用ですけれども、こちらは、区でこういった事業につきまして、課題を検証・分析・評価することで、より効率的で効果的な行財政運営につなげる、そして区政そのものをバージョンアップさせるといったものを目標として行ったものです。","id":"exchange-108"},{"speaker":"若林委員","kind":"提案","question":"先ほどもありましたけれども、例えばインフルエンザの高齢者の接種費用の、いわゆる公費負担、無償化というのでしょうか、こういったことも、ぜひ新たな財源の中で、品川区にはご検討いただきたいということが１点。ぜひとも、インフルエンザの高齢者の接種費用等々、都へも今後しっかりと要請を行っていただきたい。この２つをまずは要望しますけれども、いかがでしょうか。","respondent":"遠藤財政課長","answer":"依命通達の中で、いわゆる区民の幸せにつながるようにということで、それぞれ今編成していますが、先ほど１％というお話がありましたけれども、パーセンテージと金額とは別にいたしまして、今ご提案がありました部分、あるいは区民の幸せに使われるようなものを。","id":"exchange-109"},{"speaker":"若林委員","kind":"質問・要望","question":"このことを強くお願いしておきたいと思います。森林環境譲与税の活用に係る都内連携に関する協定を、品川区を含む１３の自治体が結びました。そこで、都内連携によって、令和４年度の決算でいうと早川町の事業に使ったりということですが、都と区の役割の違いとともに、今後、この協定によって、今やっている森林環境譲与税の活用事業が何か変化していくのかどうかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"森林環境譲与税ですが、７月に１３自治体で連携を組みまして、主にこのターゲットですが、多摩の森活性化を目的といたしまして連携したものです。","id":"exchange-110"},{"speaker":"若林委員","kind":"質問","question":"決算書、右のページの５５ページを見ると、備考欄に活用事業がわざわざ載っているということで、来年度からは森林環境税が、いわゆる住民税の枠組みを使って、区民１人１,０００円が国税として徴収されて、そしてそれが品川区に譲与されてくるということになります。分かりやすい。理解しやすい。「皆さんから１人１,０００円いただいた環境税が、幾らかけて、このような形で活用されています」。","respondent":"河内環境課長","answer":"来年度の取組、環境面につきまして、私からお答えさせていただきたいと思います。１つ、多摩の森活性化プロジェクトといたしまして、都区連携の中で１つ行うもの。それから、従前より行っていますエコライフ事業の中で、国産間伐材有効活用事業助成というものを行っております。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"特別区民税が増加したと、理由をいろいろ、ほかの委員もお話ししていたのですけれども、品川区は利便性がいいということもあり、５０代ですか、そういう方々が流入しているのだという話は分かったのですが、それは少し分析が甘くないですか。その方向性を教えてください。この約６５億円を何に使うのですかということ。もう少し大胆にすべきところがあるのではないかと思いますが、お考えをお聞きします。","respondent":"提坂税務課長、遠藤財政課長","answer":"先ほど、５０代の方の転入が多いということに関してのご説明ですけれども、結局、５０代の方は高所得者層が多いだろうと。それを受け入れる先として、今、委員がご指摘のとおり、タワーマンション等のお住まいが整備された。それから財政調整の協議事項のところですが、９月６日に都区協議会が整いまして、一旦は令和４年度の協議を継続するということで、５５.１％の確保ができたところです。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"再開発を進めている。そういうところがあって、人口が増えてきているのではないのですか。なので、ぜひそういう発想になっていただきたいと考えていますので、もう一度、これは区政に関わることです。どう持っていくのかということになると思いますので、方向性を教えてください。そこをどう持っていきますか。もう既に分かっていながら任命されたと思いますので、それをお答えいただきたいと思います。","respondent":"佐藤企画課長、遠藤財政課長","answer":"現在、長期基本計画・実施計画がありますけれども、コロナ禍も経て、気候変動危機や物価高、いろいろ社会情勢が変わっていますので、そういったものに合わせてタイミングよく、いろいろな施策を練って。","id":"exchange-113"},{"speaker":"まつざわ委員","kind":"質問","question":"私からは、決算書１２０ページ、高齢者見守り相談窓口設置事業補助金について質問をいたします。は決算書を拝見しますと、予算現額のうち金額というのがゼロ決算に計上されていますが、これは一体どういう事業のもので、どこかほかに、この事業に組み込まれているものなのか、お示しください。","respondent":"東野福祉計画課長","answer":"私から、高齢者見守り相談窓口設置事業補助金につきましてお答えいたします。この事業につきましては、当初、民生費の福祉計画費のうち、地域福祉推進費の支え愛・ほっとステーション事業に当たる補助金として予定されていたものです。","id":"exchange-114"},{"speaker":"まつざわ委員","kind":"確認","question":"支え愛・ほっとステーション事業に入れる予定があって、メニューの統合、そして補助金で７,２３８万円があるということが、確認が取れました。民生委員と支え愛・ほっとステーションとの違いというものが何かあるのか教えてください。","respondent":"東野福祉計画課長","answer":"区では、民生委員と支え愛・ほっとステーションの連携により、幅広く高齢者等への相談やアプローチを図ることで、多くの方の多様なお困り事に対応を図っているところです。","id":"exchange-115"},{"speaker":"まつざわ委員","kind":"質問","question":"支え愛・ほっとステーションの活動の中で、地域のみんなでつくる交流の場、また地域交流会というのが大変好評だとお聞きしております。１０か所の場所の記載がないというのも、紙媒体でしか情報を取れない高齢者の方にとっては、新しいものをやはり作成していって、もっと地域支援員、要はボランティアの方を募るように、周知にも力を入れていくべきではないかと考えますが、ご見解をお聞かせください。","respondent":"東野福祉計画課長","answer":"周知につきましては、パンフレットの更新としまして、先ほど委員からお話がありました、よりみちの場所の掲載や、中身の周知のための記載内容の変更等も含めまして、考えていきたいと思います。","id":"exchange-116"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、福祉を支えるすばらしい事業の拡充、そしてまた１２地区で１９か所と、よりみちなども新しくなっています。やはり、こういった情報というのは、パンフレットの更新等も含めて周知していくことが、支え愛・ほっとステーション事業のもっと拡充になると思いますので、そういった更新をしっかりと要望しまして、早いですが質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"１４６ページ、ほかの委員の方も何人かご質問されていましたが、ふるさと納税寄附金について、１７０ページ、時間の関係で、あれば議会費を質問します。全国の流出額ランキングでは１９位の位置にあります。改めて、ホームページには品川区としての考えが表示されていますが、先ほどの決算額との関係、そして区民税の損失率という関係から、改めて区長のお考えを伺いたいと思います。","respondent":"森澤区長","answer":"区長会で国に対して、やはりこの制度の是正、見直しというのは引き続き求めていくとともに、先ほど来、ご答弁も差し上げておりますけれども、ふるさと納税、区の特徴を活かした返礼品も含め、拡充とするとともに。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、特別区長会で国の制度の見直しなどの要望をしていただけるという話だったのですけれども、２３区、そして流出額の多い自治体と、まずどのように連携して、もう一歩踏み込んで何かできることはないのでしょうか。そういうところから、今言った国の仕組みの中で、果たしてそれはいかがなものかという観点で、どういう主張を国にしていっていただけるのでしょうか。","respondent":"遠藤財政課長","answer":"いわゆる、ふるさと納税制度の廃止を含めまして、これまでも見直しということで、特別区長会を通じて実施させていただいたところです。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"国に対しての、今、抗議というお話でしたが、ぜひ改善を求めていっていただきたいと思います。期待していますので、よろしくお願いいたします。では、議会費なのですが、私は不勉強なので確認も含めてお尋ねします。議会事務局の職員の方々の任免、そして指揮命令権というのは、どなたにあるのか確認します。","respondent":"大澤区議会事務局長","answer":"議長にあります。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"議長だということですね。万が一、区議会事務局の職員の方の中でパワハラやセクハラなどの被害が発生した場合は、職員の方はどなたに通報して、どのような対応が行われていくのでしょうか。","respondent":"桑村副区長","answer":"そういう意味では、区議会事務局の中では、体制を全般的な、今、セクハラ・パワハラの話がございましたけれども、そういうものの通報制度をつくるのはなかなか難しいということがありますので、一義的には今、区の職員全てがやっている通報制度。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうしたら、職員の中で万が一そういうことが起きた場合は、上司として議長はどのような対応を、何というか、指導というのでしょうか、注意というのでしょうか、行われていくのでしょうか。","respondent":"桑村副区長","answer":"これは、先ほど言ったように、人事課あるいは人権啓発課が中心となったものに訴えが出て、そこでやはり一定の調査が行われて、何かそういった、あるいは指導が必要だというときに、どちらが指導するかというのを、議長と区長の間。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"すごいというところで、すごく楽しみだと考えています。１４４ページ、防災ラジオ売払代金、１６６ページ、防災ラジオ販売事業費収入について伺います。ですけれども、前者の収入済額が３５６万８,０００円で、後者が収入済額は０円となっているところなのですけれども、この差はなぜこういう差が生じているのでしょうか。お願いします。","respondent":"羽鳥防災体制整備担当課長","answer":"今ご質問いただきました防災ラジオについてです。こちらは、当初、科目を雑入といたしまして、防災ラジオ販売事業費収入５５０万円を予算計上させていただきました。ただ、こちらは事業内容と整合させるため、年度の途中に物品売払い収入で科目更正させていただいたものです。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問","question":"今みたいなことというのはよく起こるのか、当初予算の段階で、ある程度想定できなかったのかとも思うのですけれども、この辺りはどうなのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"本来であれば、予算計上の際にしっかりと事業内容と整合を取るべきところだとは認識しております。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問","question":"分かりました。今後、よろしくお願いいたします。令和４年度の販売実績をお伺いしようと思ったら、今回の行政評価シートにしっかりと記載していただいていて、３,２６２台と記載されておりました。では令和５年度ですけれども、分かるところまででいいのですけれども、直近で今、販売実績がどのくらいあるのかと、在庫の数をお伺いできればと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"令和５年度に関しましては、９月１日時点ですが、高齢者等世帯の方で１５８台、一般世帯の方で１０５台、合計２６３台、金額といたしましては３６万８,０００円という状況になっております。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"こちらが、発送・配送委託が１,１５７万円計上されている。それで、送付用郵券が９１万５,０００円、計上されていました。配送委託のほうですけれども、令和４年度はそういう計上がされているのですが、令和５年度については予算見積書にはこれが計上されていないというところなのですが、これはどういう事情でしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"令和５年度に関しましては、申込み状況も落ち着きましたので、支払いの方法は、事前に納付書でお支払いいただいて後日配送するという流れに変更になりましたので、こちらの委託は令和５年度は行っていないという形になります。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"令和５年度については、そういう委託はしていないということなのですが、では令和５年度は、このラジオを送るのは、個別にお送りすることになると思うのですけれども、これを送るのは大体幾らぐらいかけて送っていらっしゃるのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"令和５年度、防災ラジオに関しましては、ゆうパックで発送しています。単価が５８５円となっております。","id":"exchange-127"},{"speaker":"松本委員","kind":"質問","question":"防災ラジオは、高齢の方だったら１,０００円ぐらいで売っていて、一般の方にも２,０００円で売っているものです。売っている単価よりも高いお金をかけるというのは、やはりどうなのかということで、先ほど、一刻でも早くというところはあったかとは思うのですけれども、ここは改めて、もう少し高いものを何とかできなかったのかと思うのですが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"理由につきましては、先ほども申し上げましたとおり、災害がいつ起こるか分からないということで、一日も早くということで体制を整えさせていただいた次第です。","id":"exchange-128"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。これは令和５年度はもうなくなっているということなので、今後こういった配送事業がある際には、きっちりと安いといいますか、単価は計算して出していただきたいと思います。次に、送付の郵券のほうなのですけれども、これは郵券も令和４年度で５,０００通ぐらい出されているということかと思います。どういう方にお送りされたのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"質問にお答えする前に１点訂正を。先ほどの単価の内訳ですけれども、配送料が２,２００円、配送手数料が２００円、合計２,４００円であります。大変失礼いたしました。","id":"exchange-129"},{"speaker":"松本委員","kind":"質問・要望","question":"そのときに、区に、防災無線が聞こえないのだというふうな連絡、電話のご意見などあると思うのですけれども、そういう方から電話が来た場合に、こういうラジオがありますというのを伝えていただきたいと思いますし、それに加えてその周りのエリアも聞こえていないと思うので、そういう方たちに対して直接、ダイレクトメールを送るなりしていただけないかと思うのですが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"防災行政無線が聞きづらいという方に対しましては、お問い合わせいただいた方には、防災ラジオのＰＲはしています。は広報紙等を通じて広く周知してまいりたいと思います。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"私は、１４ページ、歳入についてお聞きしたいと思います。歳入とは何ですか。そして、歳入はどのように決まるのでしょうか。教えてください。","respondent":"遠藤財政課長","answer":"歳入につきましては、１年間の区の様々な予算ということで、いろいろな収入の総額と考えているところです。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"考え方としては、予算を決めて、それに対して歳入を充てるということですよね。もう一度、それはお聞きしたいと思います。すなわち、歳出に対して、支出に対して、歳入を充てる。そういう会計年度独立の原則というものにのっとってやっていると。ここでもう一点、質問なのですが、歳入の使い道はどのように決められていますか。使い道に違いがあるかについてお聞かせください。","respondent":"遠藤財政課長","answer":"歳入の使い道というところなのですけれども、いわゆる一般財源という、どれでも使えるという、区で裁量でできる部分と、それから特定財源ということで、例えば東京都の補助金や国の補助金で一定決まっているようなものと、２種類あるかと考えております。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"大半の事業、一般財源に対しては、それぞれ、例えば区が福祉に力を入れたい、子育て支援に力を入れたいという需要に対して、自由にあてがえる。ある程度、幅がある。それを教えてください。そして、特定財源は使い道が決められている。決められていることなので、財源はもうほとんど動かせないと考えてよろしいでしょうか。","respondent":"遠藤財政課長","answer":"財源はある程度、決められているというところで、当然、継続性を持ってやる部分と、あるいは新規の施策でやるもの、あるいは一定程度、事業がもう必要ないだろうということで、廃止なり見直しなりというところで、様々なケースがあろうかとは考えているところです。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"今、品川区の一般財源は約１,１７０億円、特定財源は約７９０億円あります。ですから、あまり今の事業を、決められた事業以外には、今まで長年やってきたことについて動かすということはなかなか難しいのだろうと思います。これだけ様々な行政評価をやって、６６５ページにわたっていますが、いろいろ皆さん、職員の方が考えられて進みますが、これはそんなに変えられるのでしょうか。教えてください。","respondent":"遠藤財政課長","answer":"１８位というのは、数字が高いほうが１位という形になりますので、どちらかというと下のほうということで、非常に、いわゆる区で考えて施策を打つというところでは、比較的、余裕があるかと考えているところです。","id":"exchange-134"},{"speaker":"須貝委員","kind":"意見","question":"したがって、事業評価を数字に表すことは非常に難しいと思います。せいぜい、民間と競合する事業や、数字で評価できる事業の事業評価は可能ですが、各事業部の区民による相談などの窓口対応や電話対応、そして対面対応などの区民に寄り添う姿勢については評価できないと思いますが、これは私は、品川区としては最も大切なことだと思うのですが、この点についてご見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"そういったところから、似たような関連事業はそういったもので統合できる。そのような見直しも可能かと思いますし、また区民対応というところで、必要なところはどこかというところをしっかりと見るというところで、全件行ったです。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"実際、１例で私は、５８３ページ、行政評価シートを見ました。実際、学校は、子どもたちの学力定着はきちんとしているのですか。それを管理するのが教育委員会ではないのですか。それから、タブレットはきちんと使われているのですか。英語教育はどうなのですか。それを公開してほしいのです。もっと、やはり区民に、子どもたちに、学校に寄り添うという評価が必要ではないのですか。教えてください。","respondent":"吉岡政策推進担当課長","answer":"当然ながら、６６５事業がありますとおり、基本的にはアウトカム指標といったものを成果で出していただくようにというところで、各事業、各部に検討いただいたところではありますけれども、なかなかアウトカム指標が出せないというようなところもあります。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"行政評価をするということは、その事業が適切ですかということを、我々、区民に見せるためですよね。そうすると、何かこれは意味合いが違うのだと思うのです。実際、この事業はどうなのだ。それはどうするのですか。それは無駄ですかという判断をするのですか。そうではないのではないですか。これでは区民から全く離れているのではないのですか。それでいいのでしょうか。もう一度ご見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"事務事業評価につきましては、必要性、有効性、効率性といったものを評価・分析しているものですけれども、当然ながら、区民の方あるいは団体の方、こういったご要望、あるいはこういった部分も含めまして評価シートに掲載させていただいているところです。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問・要望","question":"その気持ちは分かります。先ほど石田しんご委員からもありましたけれども、こんなことをしていたら、本当に仕事ができるのですか。それだったら区民と相対して区民サービスに努めてほしい。区民の福祉のために、私はやってほしいと思うのです。何を区民が求めているのだ。そういう対話も、やはりそういう方向を、もっと区として進めるべきだと思います。最後に、もう一回だけ、ご見解をお聞かせください。","respondent":"吉岡政策推進担当課長","answer":"まさに委員がおっしゃるとおりで、福祉の増進に向ける、あるいは区民対応を強化する。そういったところに振り向けるために、今やっている事業の効率性を、より高めるというところで、この事務事業評価を行っているところです。","id":"exchange-138"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、８９ページの区内私立保育園経費に関わって補助金流用問題、９５ページ・１１９ページのすまいるスクール運営費について、環境改善などについて伺います。私立保育園経費です。保育の質を担保していくためにもしっかりチェックすることが求められていると思います。区は、国の通知でも流用を認めていると説明しますが、１０％以上流用しているということは問題だと考えていないのか、伺います。","respondent":"石井保育支援課長","answer":"委員ご指摘の１０％が問題かどうかについては、１０％という数字そのものでもって、問題だ、問題でないという議論をするべきことではないと考えています。","id":"exchange-139"},{"speaker":"のだて委員","kind":"質問・要望","question":"数値では問題とは捉えていないというお話でしたけれども、やはり、本来、保育園で使われなければならない巨額のお金が流用されているということになるわけなのです。区にある保育園に使われないということですので、品川区としてもチェックすることが求められると思います。そして、１０％を超えて本部経費に回すということは保育の質の低下にもつながると考えますが、いかがでしょうか。","respondent":"石井保育支援課長","answer":"例えば先ほど委員のご指摘の中に法人本部の経費というのはございましたけれども、例えば今、保育ニーズというのは多様化しているところがありますし、現場の保育士だけでは対処できない問題を、法人のスーパーバイザーが一緒になって入っていたり、区との連絡調整等々。","id":"exchange-140"},{"speaker":"のだて委員","kind":"質問・要望","question":"本部からスーパーバイザーが来ているという話もありますけれども、そうしたことも含めて、やはり品川区としてチェックしていただきたいと思います。これも本来、区の保育園の運営のために出されているという運営費が、他自治体に流れているということになるわけですが、これは問題と考えていないのか伺います。","respondent":"石井保育支援課長","answer":"そういったところで、もちろんこういった制度については国が考えている部分ですので、必ずしもその１つだけでもって不適当だと申し上げることはできないと考えています。","id":"exchange-141"},{"speaker":"のだて委員","kind":"提案","question":"直ちに問題とは考えていないということですけれども、これは１つの指標として私は提案しておりまして、そうしたところでのチェックというのは、しっかりとされているのかどうかを伺いたいと思います。","respondent":"石井保育支援課長","answer":"例えば東京都から疑義が生じた場合については、東京都からの疑義事項ということで、区を経由して各事業者に伝えられているところですので、様々な観点からチェックがなされているものと承知しています。","id":"exchange-142"},{"speaker":"のだて委員","kind":"質問","question":"区でもチェックしているということなのですけれども、それがやはり他自治体に流用されているということは、私は問題だと思います。本来、区内で使われるべき財政が流出しているわけです。それで、流用された保育園や区の子どもたちは使えないわけです。税金の使い方としても、有権者が関われないというのはおかしいと思います。区として、こうしたことに問題意識はないということなのか、伺います。","respondent":"石井保育支援課長","answer":"しかし、直ちに委員ご指摘の１０％云々といったところが、それそのものだけでもって問題だと考えているのではなく、委託費を支出するからには、きちんと保育の質の向上のために使うべきだと考えているところです。","id":"exchange-143"},{"speaker":"のだて委員","kind":"質問","question":"ただそれだけでは問題だと考えていないということですけれども、つまり、ではどうなった場合には問題だと考えているのか。あるいは、これが１０％ではなく２０％、３０％の場合、問題だと考えているのか、伺いたいと思います。先ほど課長は、品川区にも入ってくる部分もあるということでしたけれども、それで本当に税金の使い方としていいのでしょうか。伺いたいと思います。","respondent":"石井保育支援課長","answer":"区内の保育園のことに関して、まず保育が適正に実施されているかが一番の評価のポイントであると考えています。","id":"exchange-144"},{"speaker":"のだて委員","kind":"質問","question":"そこは区としてもチェックすることが必要だということと、税金の使い方として、区に来たものが別の自治体で使われる。ほかの自治体のものも品川区に入っているということで、そうした使い方でいいのかということも聞きましたので、伺いたいと思います。","respondent":"石井保育支援課長","answer":"他の自治体に流れているなどといったことについては、こちらから何も申し上げることはできませんので、まずは適正な保育がなされているかどうか、そこに着目するべきだと考えています。","id":"exchange-145"},{"speaker":"のだて委員","kind":"提案","question":"すべきだということは言っておきたいと思います。品川区としても、保育園運営費の流用についてルールをつくることを求めますが、いかがでしょうか。あまりに低い３割台などの人件費は是正すべきだと考えますが、いかがでしょうか。それで、これを満たさなければ返還を求めるというものです。人件費率について品川区のルールをつくるべきだと提案しますが、いかがでしょうか。","respondent":"石井保育支援課長","answer":"それを一概に言うことはできませんし、あとは当然、そこというのは、事業者の経営の判断の部分になってくることです。区としては、適正な保育が行われているということに着目すべきであり、経営の一つ一つにまで行政が事業者に対して口出しをするものではないと考えています。","id":"exchange-146"},{"speaker":"のだて委員","kind":"質問・要望","question":"私が今いろいろ指摘しているのは、やはり保育の質を上げていく、豊かな保育を提供していくというためにも必要だということで求めておりますので、ぜひそうした視点で、区としてもチェックしていっていただきたい、ルールもつくっていただきたいということで、要望しておきたいと思います。こうした面でも、配慮が必要な子どもたちも過ごしやすい環境整備を求めたいと思いますが、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"特別な支援が必要な児童など、発達障害とおっしゃっていましたが、そういった形のお子さんのほうが数が増えているというところも、１つの事実としていますので、そういった方が安心して過ごせるように、すまいるスクールの人員を少し増やしたりといった。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問","question":"私からは、８８ページ、８９ページにかけて、国庫支出金、生活困窮者自立支援事業と区内私立保育園経費について伺います。最初に、生活困窮者自立支援について伺います。それで、ただ、今までの決算の評価だと、あまり家計診断のほうが表に現れてきていなくて、ぜひそのことについて本日は伺いたいと思います。委託先の業務の状況についても、区としての評価を伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"実績というか、件数のご質問をいただいております。令和４年度の件数ですが、こちらで上がってきている数字が、延べ３４回、家計相談を対応させていただきまして、その内訳、６名の方に対して３４回、対応させていただいたです。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問","question":"品川区としては、信頼できるということでしょうか。３４回で６名というのは、人によって違ってくるということで当然だと思いますけれども、その結果、その方の状況が生活困窮から抜け出したなどというような点についての評価も伺いたいのですけれども、その点についていかがでしょうか。有効性のほうの評価をぜひ伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"６名のうち２名の方は、暮らし・しごと応援センターで引き続き職員が対応していると報告を聞いております。残念ながら１名の方は生活保護に入ってしまったりという方も聞いております。必要性・有効性のお話です。","id":"exchange-149"},{"speaker":"吉田委員","kind":"提案","question":"改めて伺うこともあると思いますけれども、どうぞよろしくお願いいたします。それで、もう一つが、区内私立保育園経費について伺います。１例を挙げます。人員の配置基準を満たしていたとしても、活発に動く子どもたちを保育士２人で目配りするのは難しいのではないでしょうか。区としての加配を検討すべきと考えますが、見解を伺います。この欄の記載は誰がどのように行っているのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"今回、委員ご指摘のところでは、改善策の実施状況を確認し、新たな課題が発生するようであれば、必要に応じてさらなる改善策を指導していくというようなことですけれども、こういった報告が園から電子メールで「事故報告書を提出します」と送られてきたときに。","id":"exchange-150"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、区としても、足りないのではないかという認識はあるのだと思うのです。これは、東京都に報告という形を取りながら、東京都へ配置を増やすように求めているようにも見えますし、事故報告に記載する、区のコメントというものを通して、そういうふうに求めていると理解してよろしいでしょうか。その辺を伺いたいと思います。","respondent":"石井保育支援課長","answer":"都の担当者もこういったものを読んでおりますし、そういったところで、区が例えば今回の事案について、こちらは保育士をもっと配置したほうがいいのではないか。こういったコメント一つ一つを、東京都が施策に活かしていくというふうなことはあると考えています。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、そのようにこれからも東京都や国に主張していただきたいと思います。それで、事故報告なのですけれども、私たちは毎年、情報公開請求しているのです。この間の補正予算のときも言いましたけれども、効果測定などということのためにも、これは文教委員会に資料として提供されるべき事故報告だと思いますけれども、その点について見解を伺います。","respondent":"石井保育支援課長","answer":"こういった内容ですけれども、まず現場で共有することが一番と考えています。私立保育園長会でも、個人名を抜いた形で共有等を行っているところですし、今後も適切な形で情報共有していきたいと考えています。","id":"exchange-152"},{"speaker":"あくつ委員","kind":"確認","question":"私からは、１１２ページ、総務費補助金から、ウクライナ避難民への支援についてと、関連して福祉計画課長や公園課長にもお伺いしますので、よろしくお願いいたします。もう一つ、１０９ページ、民生委員活動経費、１２１ページ、高齢者安否確認事業、町会自治会のお祝い事業等への名簿提供について伺ってまいります。ウクライナ支援についてです。これは、財源は歳入のどこに当たるのか教えてください。","respondent":"勝亦総務課長","answer":"こちらの補正予算の財源ですけれども、補正予算で一般財源で組んでいるものと認識しております。","id":"exchange-153"},{"speaker":"あくつ委員","kind":"確認","question":"１年前の第３回定例会の一般質問で、区内のウクライナ避難民の数を確認したところ、総務部長の答弁で、「避難者の状況ですが、東京都では、プライバシー保護、避難者の安全確保などの観点から、自治体ごとの避難者数については公表していないため、品川区においてもその趣旨を踏まえ、公表は差し控えたい」というご答弁でした。何で品川区は公表しないのか、改めてお伺いしたいと思います。","respondent":"勝亦総務課長","answer":"第一回定例会で過日ご答弁を総務課からさせていただいたととおり、プライバシーやセキュリティー上の問題といったものがあろうかと考えて、公表していないものです。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどの東京都の課長に聞いたら、それは自治体の判断ですということでした。自治体の判断として、そうしたら、他区は恐らくプライバシーなどあまり考えていないのでしょうね。これは、品川区では、令和４年３月２日から日本赤十字社のウクライナ人道危機救援金の受付というのを行っています。どの程度の募金があったのか、これは福祉計画課が窓口のようなので、教えていただければと思います。","respondent":"東野福祉計画課長","answer":"令和４年３月２日に、まず募金箱を設置いたしまして、その後２か月間、募金箱を設置してございました。現在までのウクライナ人道危機救援金の募金額につきましては、８５万９,９７６円となっています。件数でいくと９０件ほどになります。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問","question":"８６万円弱の募金がされているということで、ウクライナ避難民への支援ということで、区民からも非常に関心が高いと。先月９月２１日に国連でウクライナのゼレンスキー大統領が支援を訴える演説を行ったという報道がありました。ウクライナに連帯を示す。これは令和４年度に品川区議会と品川区長からロシア大使館に申し入れていると思うのですが、私はこの覚悟が必要だと思うのですが、ご見解を伺います。","respondent":"勝亦総務課長","answer":"支援につきましては、今、区内のご支援いただいている方には定期的にご連絡を取ったり、様々なご要望を受けて細かに対応している状況です。そういった意味では、人数にかかわらず、品川区は熱心にウクライナの避難民の方の支援を続けているところです。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"確認","question":"この前もそういうご答弁がありました。その間、決算特別委員会、予算特別委員会で、これは何度も確認して、今年の４月の予算特別委員会では、当時の総務課長から、最終的な調整を行っていますというご答弁をいただきました。そこから７か月がたって、令和４年度には実現しなかった。その最終的な調整、７か月間たっていますけれども、その７カ月間の最終の調整の結果について教えてください。","respondent":"勝亦総務課長","answer":"ご利用のご要望のあった健康センターは、品川・荏原につきましては無料で使えるようにご協力いただきまして、今、無料で９月から使えるということで、お知らせをしています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問","question":"９月２０日付のホームページ、小さなコラムというか、小さなニュースで、そのことが載っていました。これは日本語で掲載されているのですけれども、日本語のホームページを毎日見ている避難民の方は当然いないでしょうし、避難民当事者の方は日本語が読めない方もいらっしゃるかと思います。どのようにお伝えされているのか教えてください。","respondent":"勝亦総務課長","answer":"先ほど申し上げましたとおり、避難されている方には、個別に定期的に連絡を取ってあります。そういった意味では、担当から、メール、ＬＩＮＥ等を使って、お一人お一人に情報を提供しています。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"確認","question":"確認しますけれども、これはもう確実に伝わっているということでよろしいのでしょうか。","respondent":"勝亦総務課長","answer":"こちらから避難民の方ご個人にお送りしたメール、ＬＩＮＥ等をご確認いただければ伝わっていると考えております。","id":"exchange-159"},{"speaker":"あくつ委員","kind":"質問","question":"同じ７か月前のご答弁で、健康センターだけではなくて心身の健康の維持のための施設ということで、個人でフリー利用、予約なしで使えるような施設について、何らか使用料の免除ができるような形で最終的な調整をされているという、課長の答弁がありました。少し期待していたのですけれども、この点、全庁的にどのような調整をされたのか教えてください。","respondent":"勝亦総務課長","answer":"全庁的な調整というご答弁をさせていただいたかと存じてあります。ただ、何ができるかというところからではなく、何のご要望があるかというところから支援を考えてあります。","id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど、寄り添った支援で、様々、聞き取りなどされているということでしたけれども、どういった要望があったのか、それでは教えていただければと思います。出入国在留管理庁というところから表彰されています。このような心意気というものが、やはり品川区には求められるのではないかと思います。２つお聞きしましたけれども、取りあえず、そのことについてご見解をお願いしたいと思います。","respondent":"勝亦総務課長、高梨公園課長","answer":"翻訳機の貸し出しや、あと病院に行きたいのだけれどということで、例えば病院の予約や、場合によっては同行してお手伝いをするといった、きめ細かなご支援をしています。しながわ水族館へのウクライナ避難者の方への減免についてですが、当然、避難者の方々は区内に在住していただいてありますので、現在でも区民割引の減免はさせていただいておるところなのですが、免除というようなところにつきましては。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国でやるべきことは国でやっていただく。では、品川区ではどういうことができるのかということを、私としても、そのときのニーズということで、１年かかりましたけれども、先ほどようやく実現できました。特筆すべきものがあれば後で教えていただきたいのですけれども、そういったところを一歩乗り越えて、ぜひ品川区としてウクライナへの連帯を示していただきたいと思いますが、再度お伺いいたします。","respondent":"勝亦総務課長","answer":"今、ウクライナの状況、ウクライナに限らず世界では、貧困や戦争といったものに苦しんでいる方がいらっしゃいます。そういった方を、区として精いっぱい支援していくのは非常に大切なことだと考えています。","id":"exchange-162"},{"speaker":"こしば委員","kind":"質問・要望","question":"私からは、１５２ページの奨学金貸付金元利収入について、１６３ページ、各種事業参加費負担金について、７８ページ、区営住宅使用料、区民住宅使用料について、時間が余りましたら、１０２ページのスマートウェルネス住宅等推進事業補助金についてお伺いいたします。相手が人間です。この奨学金の内容について教えていただきたいと思います。対象者の年齢や１人当たりの上限額などについて教えてください。","respondent":"飛田子育て応援課長","answer":"こちらは平成３０年度からは制度改正を行い、在学応援資金を創設の上、返還免除型で導入しております。こちらの返済の実績ということでは、今、２５６件中１００件ほどが、滞納が発生しております。金額としては、２,００６万５,０００円となります。","id":"exchange-163"},{"speaker":"こしば委員","kind":"質問","question":"奨学金の返還は、まだ返済途中の方もいれば、また滞納者もいらっしゃると推察します。私も大学の奨学金を少しずつ返還して、ようやく３０代に入って完済した経験もありますので、滞納者の中には、少額でも払い続けている方もいらっしゃると思います。一方で、事情によって就職に就けず、支払いが滞っている人もいると思いますが、滞納してしまう人に対する品川区のアプローチについて教えてください。","respondent":"飛田子育て応援課長","answer":"現在、滞納している方に対しては、職員が直接お電話をしたり、また督促ということでお手紙を送ったりしております。なかなか返還をお願いしても応じない方もいますので、シルバー人材センターにも委託を行っておりまして、各家庭に、お宅に訪問して、注視しています。","id":"exchange-164"},{"speaker":"こしば委員","kind":"質問","question":"奨学金の返済は、返済者にとっては固定費です。返済者が相談に来ることもあると思いますけれども、横串を刺した、必ずしも所管だけではなく、それを横の展開をした連携もまた必要だと思いますけれども、その辺の取組についても、先ほどシルバー人材の方が訪問されていると、それも対面ではあると思いますけれども、逆に区役所での対応について教えていただければと思います。","respondent":"飛田子育て応援課長","answer":"横串というところでは、例えば独り親家庭等につきましては、母子・父子の福祉資金という方法で、就学金よりも優先される貸付資金もありますので、そういうところもご案内したりしておるところです。","id":"exchange-165"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひこういった横串を展開していただいて、決して無理のない返済計画を、共に連携して行っていただきたいと思います。続きまして、各種事業参加費負担金について伺います。こちらは、この項目で多くの事業が列挙されておるわけですが、収入未済であった事業がどのような事業なのかをまず教えてください。","respondent":"藤村子ども育成課長","answer":"こちらに収入未済で記載されております金額につきましては、全額、すまいるスクールの利用料という形になっております。","id":"exchange-166"},{"speaker":"こしば委員","kind":"質問","question":"すまいるスクールという答弁でございましたが、参加費用は月額で、夕方まででしたら２５０円、それ以降は１８時までで３,４５０円、１９時まで利用される場合は４,２５０円、月額でかかると認識しております。すまいるスクールでは、どのくらいの割合で、１８時ないし１９時まで利用する方がいらっしゃるのか、全体の登録者のうちどのぐらいの割合でいらっしゃるのかを教えていただければと思います。","respondent":"藤村子ども育成課長","answer":"６時までの登録というのが、今、手元ですぐ出てこないのですけれども、大体約９,０００人ぐらいご登録いただいておりまして、Ｂ登録という６時までの登録の方が１,７００人程度、Ｃ登録という７時までの登録の方が１,１００人程度というような概況になっております。","id":"exchange-167"},{"speaker":"こしば委員","kind":"質問","question":"多分、その相関関係までは難しいでしょうか。お答えいただければありがたいのですけれども、相関関係は分かりますか。","respondent":"藤村子ども育成課長","answer":"全体として、就業されている方というところが、保護者の方が就労されている場合は、Ｂ登録やＣ登録というのをご利用いただいているような形が多くて、Ａ登録という場合は、就業されていない方が保護者というような形になっているというのが、必ずしもそうではないのですが。","id":"exchange-168"},{"speaker":"こしば委員","kind":"質問","question":"１８時以降の利用を続けていく中で、負担に感じている保護者もいらっしゃると思います。なかなか支払いが難しいという方もいらっしゃる中で、区の取組について教えていただければと思います。","respondent":"藤村子ども育成課長","answer":"Ａ登録の場合、２５０円、Ｂ登録、３,２５０円、Ｃ登録、４,２５０円というところで、金額が上がっていくような形になりますので、それぞれのご家庭のご事情等ございまして、お支払いが通常、すまいるスクールの場合、口座引き落としという形でお支払いいただいておりまして。","id":"exchange-169"},{"speaker":"こしば委員","kind":"質問","question":"生活の事情によっては支払いが滞ってしまうという話もありますけれども、これは何も子ども育成課だけではなく、生活福祉課であったり、内部で社会福祉協議会との連携といった情報も知っておく必要があると思いますけれども、そういった連携もされているという認識でよろしいのでしょうか。","respondent":"藤村子ども育成課長","answer":"先ほども子育て応援課長から答弁がございましたように、仮にそういったお支払いということが難しいというようなお話がございましたら、社会福祉協議会など、別途、融資制度等のご案内というのをしている場面はあろうかと思います。","id":"exchange-170"},{"speaker":"こしば委員","kind":"質問","question":"続きまして、７８ページの区営住宅・区民住宅の使用料について、お伺いいたします。区営住宅使用料のうち、９０万円余の収入未済額が計上されています。この１７件が債権を手放してしまっているのですが、これはどういった理由で手放しているのか、教えてください。","respondent":"竹田住宅課長","answer":"こちらは、破産宣告を受けた、あるいは元居住者の連帯保証人等がお亡くなりになり、相続人等もいないということで、回収が困難だと思われる案件につきまして、債権管理審議会にお諮りし、回収不能とご判断いただいたものを不納欠損としている状況です。","id":"exchange-171"},{"speaker":"こしば委員","kind":"質問","question":"今の答弁ですと、破産や、相続人がいないというケースもあると。でも、中には相続人がいるけれども、相続放棄をするようなケースもあったりはするでしょうか。","respondent":"竹田住宅課長","answer":"先ほど申し上げましたのは、居住者や連帯保証人の相続人がいないケースを申し上げておりますので、相続人がいるケースにつきましては回収の努力に努めているところです。","id":"exchange-172"},{"speaker":"こしば委員","kind":"質問","question":"回収の努力をされているということですが、ご遺族の心情を考えると、なかなか家賃を、また亡くなった方の請求をしていくのは心苦しいところも現場ではあるのかとは思いますけれども、それは例えば戸籍住民課で、そういった督促といいますか請求はされておるのか、また別の所管になってくるのか、その辺を教えていただけますか。","respondent":"竹田住宅課長","answer":"ただ、あまりに遠縁の方、あるいは請求が長年行われていないような方について、回収が事実上不可能だと思われる案件については、債権管理審議会にお諮りして不納欠損処理という形になっているものも、数件あります。","id":"exchange-173"},{"speaker":"こしば委員","kind":"質問・要望","question":"確かに、遠縁の方などだと、なかなかそれを後追いするのは心苦しいところと思いますので、決して無理することなく続けていっていただきたいと思います。そして、あと１分少々、１０２ページのスマートウェルネス住宅等推進事業補助金。これは、大崎の再開発事業のために充てられた補助金が結局、収入未済額に計上されておるわけですが、これはなぜそうなってしまったのか、お答えいただければと思います。","respondent":"中道都市開発課長","answer":"令和４年度に建物の解体を予定しておりましたが、事前の調査によりアスベストが予定以上に多かったことや、既存の建物に残置物が非常に多かったというところで、繰越しを行いました。その繰越しにおける国の補助金２分の１を、今回、収入未済額と計上しています。","id":"exchange-174"},{"speaker":"こしば委員","kind":"質問","question":"こちらはまた、来年度ということは令和５年度には計上されておるということでよろしいでしょうか。","respondent":"中道都市開発課長","answer":"令和５年度におきましては、またさらに建物の予算を計上しております。収入未済額につきましては、令和４年度の執行を今年度、今、行っている最中で、収入として入る予定です。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491466?Template=document&Id=1532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":126869,"voices":407}},{"id":"r05-20231003-4","meetingId":"r05-c-settlement","date":"2023年10月3日","dateIso":"2023-10-03","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","topics":[{"id":"topic-01","title":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","agenda":"◯塚本委員長 ただいまより、決算特別委員会を開きます。 それでは、令和４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"おはようあります。本日も一日よろしくお願いいたします。私からは、２１１ページ、しながわマラソン大会開催準備経費、１８５ページ、国際友好都市交流事業についてお伺いします。昨日、歳入でも質問があり、ご答弁で、８月１日に実行委員会が行われたと伺いましたが、実行委員会の内容と、今年度の計画スケジュール、また、コースの検討状況も詳しくお知らせください。","respondent":"三井スポーツ推進課長","answer":"１０月以降も引き続き、コースに関する関係機関との調整をはじめ、大会運営計画案の検討や、事前広報活動の実施などをしていきまして、１２月には第２回の実行委員会で、コースおよび大会要項を決定していきたいと考えております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"意見","question":"第２回委員会、そして来年３月にはプレ大会、コースも詳しく分かって、最後は大井競馬場でゴールということで、とても楽しみにしております。令和５年３月、しながわシティランに向けたアイデアソンが開催されていたのですが、これは私も参加させていただきました。区のお考えをお聞かせください。","respondent":"三井スポーツ推進課長","answer":"ご参加いただいた方々との今後の関わり方については、何かご協力いただけないかということは、今後探ってまいりたいと考えております。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"確認が取れました。ランナーだけでなく、地域住民の方、観客、地域商店街など、各層を巻き込んだしながわシティランの実施を強く要望いたします。令和４年８月には、品川区国際友好協会で、区内在住の中学生・高校生と、オークランド市にあるリンフィールドカレッジの先生や生徒たちとのオンライン交流が行われました。９月には森澤区長をはじめ、訪問団がオークランド市に公式訪問されました。","respondent":"勝亦総務課長","answer":"行かれる前には、語学とか生活について、少し不安そうな様子でしたが、帰ってきましたら、非常に力強く、英語で現地での交流をしてきたということで、国際感覚の養いですとか、そういった力を育むきっかけになっているのかなと考えています。","id":"exchange-003"},{"speaker":"えのした委員","kind":"質問","question":"今回の公式訪問では、ニュージーランドホッケー協会との意見交換、ホッケー場の視察も行われております。私も先日、応援に伺いましたが、今まさにアジア大会で、ホッケー日本代表がパリ五輪出場を目指して活躍しており、昨日もパキスタン戦で勝利して予選グループ２位と、準決勝進出を決めました。オークランド市と品川区のホッケー交流で親交を深めるのはいかがでしょうか。区のお考えをお聞かせください。","respondent":"勝亦総務課長、三井スポーツ推進課長","answer":"そういった中で、ホッケーを通じた交流をぜひしてまいりましょうということで、区長・議長からもお話をいただきまして、ニュージーランドのホッケー協会からも好感を持って迎えていただいたという状況です。マラソンの国際交流について、私からお話しますと、マラソンの国際交流については大会のＰＲや、大会を魅力的にする一つの効果的なものかと考えていますので、大会を考えていく上で、今後参考にさせていただければと思います。","id":"exchange-004"},{"speaker":"えのした委員","kind":"質問","question":"品川区の友好都市は、アメリカのポートランド市、スイスのジュネーブ市、ニュージーランドのオークランド市の３市ですが、より一層の国際化、グローバル化のためには、友好都市の拡充が必要だと考えます。アジア圏の国との交流が重要だとも考えております。この取組を活かしたモンゴルとのビジネス協定はいかがでしょうか。スタートアップの海外展開支援について、区のお考えをお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"品川区は現在、モンゴル高専、モンゴルとの海外交流というのを進めているところですけれども、それ以外の、今ご指摘にありましたニュージーランドも含めて、区内事業者の声も聴きまして、こういうことの拡大の可能性があるかということを探っていきたいと考えています。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問","question":"モンゴル高専の方たちとの交流から始めてもいいかと考えております。そこからまたビジネスに通じる交流、そしてまた、国等を行き来する国際交流が発展すればと考えております。大使館との交流を拡充するのはいかがでしょうか。区のお考えをお聞かせください。","respondent":"勝亦総務課長","answer":"区内の大使館につきましては、一日交流をさせていただいて、区の、例えば大井どんたくにご出展いただくとか、関係する国のパネル展を庁舎で行うなど、交流を行っているところです。今後も引き続き、交流は拡充していきたいと考えています。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問・要望","question":"パネル展は私も先ほど取り上げましたが、見やすいとは思うのですけれども、今は映像の時代ですから、関係都市の紹介映像とか、大使館の映像とかを分かりやすくパネル展と一緒に展開されるのはいかがでしょうか。ぜひそちらもご検討いただければと思います。既存の国際交流都市と、これまでの形式にとらわれない、さらなる交流強化を要望しますが、新しい取組があれば、区のお考えをお聞かせください。","respondent":"勝亦総務課長","answer":"品川と友好交流、また大使館があって交流しているような国の紹介、それから、品川区との交流につきまして、積極的に、今いただきましたような映像ですとか、様々な手法を検討いたしまして、ＰＲ、お知らせをしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"これから未来を担っていく子どもたちの国際交流、こういった教育、そして、コロナ禍で体験がかなり失われておりますので、ぜひ積極的に、区内小学校、また中学校、高校も含めた国際交流、生で人と接して国際交流をしていくことが、これからの子どもたちの力になると信じておりますので、引き続き、国際交流都市と、また新しい形の国際交流を強化することを要望して、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、２点お伺いいたします。１９９ページの旧荏原第四中学校管理費、同じく１９９ページの大井第三地域センター移転関連経費について、どちらも地域活動費から、それぞれお伺いしてまいります。初めに、旧荏原第四中学校管理費より質問いたします。旧荏原第四中学校は、豊町３丁目・４丁目の区民避難所としても指定されている地域であります。","respondent":"吉岡政策推進担当課長","answer":"今後は、跡地活用方針策定委員会で方針案を策定いただくというところで、区といたしましても、そちらを尊重するような形で進めていきたいと考えているところです。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"地域のコミュニティの場として、地域の人間関係がつながれば、自助・共助にもつながると思われますが、こういったところで何かお考えはありますでしょうか。","respondent":"吉岡政策推進担当課長","answer":"そのほかに３つのコンセプトがございまして、２つ目が多様な人々の学び・交流を育む場、３番目として誰も取りこぼさない支援の場、４つ目といたしまして、豊かな心と体の健康を育む場ということで、交流を重ねながら、自助あるいは共助というところを強めていくというところは。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"移転する大井第三地域センターは、本年３月の予算特別委員会にて当時の地域振興部長から、施設面積の拡張、防災備蓄倉庫を設置することの予定や、町会の方の活動の活性化に寄与すると答弁がありましたが、例えば、大井第三地域センター、区民集会所に新設される防災備蓄倉庫の区民へ開放した見学会や説明会等を開催し、大井第三地域センター。","respondent":"宮澤地域活動課長","answer":"もとより地域センターの移転ということで、地域の方々にご利用いただく地域コミュニティの核として、拠点としての地域センターですので、地域への説明というのはしっかりしていく予定です。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"大井第三地域センターの自助・共助といった観点から、あと、ウェルカムセンター原を活用した取組といったところで、もう少し深く自助・共助といったところでお考えがあれば、お聞きしたいと思います。","respondent":"宮澤地域活動課長","answer":"新たに地域センターが移転する中で、防災訓練の町会ごとの訓練等々、何か活用できるかどうかというところは、地域と話し合いながら進めていきたいと考えております。","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問","question":"本日はよろしくお願いいたします。私からは、１８６ページの人権啓発費の中の人権啓発事業、そして男女共同参画推進事業について、併せて質問します。男女共同参画のための品川区行動計画「マイセルフ品川プラン」には、重要施策に、性的（セクシュアル）マイノリティへの理解促進と支援が挙げられています。区として重要施策にこの項目が挙げられた理由、経緯についてお聞かせください。","respondent":"加島人権啓発課長","answer":"調査対象数、回答数として８４２人ですけれども、これを区内全体に広げた場合、一つの大きな数になると思い、区として重点施策として、理解促進・支援を図っていくと考えた次第です。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問","question":"そこで、多様な性に関する理解の促進と、性的指向、ジェンダーアイデンティティに起因する日常生活上の困難等の解消に向けた施策についてお伺いします。区として、性の多様性の講座・講演会、そして、性的マイノリティ当事者が参加できる交流スペース「みんなのひろば」を実施していると思いますが、現在の開催状況、そして区民の方の参加数、もし課題があれば、その点についてもお聞かせください。","respondent":"加島人権啓発課長","answer":"ご案内のあったみんなのひろばにつきましては、昨年度は年２回実施いたしまして、今年度は年３回となっております。令和４年度の実績といたしましては、こちらは第１回・第２回合わせての参加人数になりますが、計１０人の方に参加していただきました。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"このような対象の設定だと、当事者自身にとっても、そしてまた、理解を深めたいと考えている区民の方にとっても、参加することにハードルがあるのではないでしょうか。みんなのひろばの年齢制限、そして参加対象を広げても、テーマをしっかりと伝えることで、興味のある区民の方々が参加することにつながると思いますが、いかがでしょうか。もし映画以外の内容などを検討している場合はお聞かせください。","respondent":"加島人権啓発課長","answer":"こちらのひろばの内容につきまして、令和２年度の開始以降、映画とフリートークの内容について実施してまいりましたが、当初は映画が参加者同士の会話のきっかけになればということで始めさせていただいたのですけれども、ある程度、始めて年数を重ねてまいりましたので。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"現在試行錯誤している段階で、様々な方法を検討してくださっていると思います。ぜひ対象者の記載については拡大していただき、そして内容についても前向きに対応していただければと考えています。品川区では、女性相談員による総合相談の中に、法律相談、カウンセリング相談、ＤＶ相談とあり、このカウンセリング相談の窓口で対応してくれるのではないかと思うのですが、この認識でよろしいでしょうか。","respondent":"加島人権啓発課長","answer":"委員がおっしゃるとおり、男女共同参画センターのカウンセリング相談の一環として、セクシャリティに関する相談を受けているところです。","id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひこのような冊子にも、品川区で対応しているということがすぐに分かるように、ＬＧＢＴＱ相談と明確に明記をしていただきたいと思いますが、いかがでしょうか。そしてまた、現在行っているカウンセリング相談の中で、性的マイノリティに関する相談があれば、その件数、そして相談件数に対し、区としてはどのように捉えているのか教えてください。","respondent":"加島人権啓発課長","answer":"そのようなお悩みを抱えているという電話は、職員のほうで１件お受けしたのですけれども、職員のほうで苦しいお気持ちに寄り添うような対応をしたところ、もう一度周りの方と話してみるということで、そのときは実際には相談の予約には至らなかったということがあります。","id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問","question":"相談件数がゼロ件ということは、やはり区への相談にはつながっていないということが、課題としてあると分かりました。恐らくこの記載の方法だと、東京都のほうに相談が行っているため、品川区自体に相談が来ていないのが現状ではないかと思いますが、そこでお伺いします。東京都の相談窓口に品川区民から相談があった場合、品川区にはどのようにフィードバックされるのでしょうか、お聞かせください。","respondent":"加島人権啓発課長","answer":"ただいまご質問にありましたＴｏｋｙｏ ＬＧＢＴ相談専門電話相談につきましては、東京都総務局人権部が外部委託により実施しているものでございまして、相談内容については、デリケートな内容であることから、区にフィードバックはございません。","id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"マイセルフ品川プランの中で、理解促進と支援を重要施策としても挙げられていますので、ぜひ品川区でも、他区で進めている専門家を配置したにじいろ相談窓口の設置、そして、相談内容から分かる課題を区としても認識した上で、今後の啓発活動や講座、そして、みんなのひろばの内容に反映していくべきだと思いますが、いかがでしょうか。区の考えを教えてください。","respondent":"加島人権啓発課長","answer":"区ではこれまで、カウンセリング相談でカバーさせていただいていると、進めてきたと認識しておりますが、これ以上に今できること、周知としての課題といったことを乗り越えまして、今できることとして、カウンセリング相談をはじめ、東京都パートナーシップ宣誓制度の活用。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"多方面から、性的マイノリティに対する問題について課題意識を持ち、取り組んでくれていると、ご答弁でいただきました。実は私もマイセルフ品川プランの講演会に、友人たちと共に参加させていただきました。この条例の中で、もし性的マイノリティ、どのような工夫をしていこうという意見などがありましたら、最後にお聞かせいただきたいと思います。","respondent":"加島人権啓発課長","answer":"条例に関する検討委員会におけます性的マイノリティへの支援というところですけれども、具体的な事業につきましては、計画改定時に落とし込んでまいりますので、まだ何かそのような意見が出た段階ではないのですけれども、この中で、性的マイノリティの方をはじめ。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"１８１ページ、しながわＷｉ－Ｆｉスポット事業、１９９ページ、地域センター等管理運営費に関連して、区民集会所のＷｉ－Ｆｉ、１９１ページ、契約関係事務費に関連して、公契約条例について伺いたいと思います。区は利用者からそのような声というのは聞いているのでしょうか、聞いていないのでしょうか。それと、改善の必要性があると考えているのか、いないのか、伺います。","respondent":"横田情報推進課長","answer":"６０分にしている理由ですが、フリーＷｉ－Ｆｉは公衆無線ＬＡＮの性質上、標的型攻撃の踏み台とされているという理由があることから、警視庁からの要請に従いまして設定しているものです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"ＳＨＩＮＡＧＡＷＡ ＦＲＥＥ Ｗｉ－Ｆｉ全体の利用時間が６０分だから、区民集会所だけ変えるのは困難という話もかつていただいたのですが、どういう意味なのか、もう少し伺いたいのと、それが難しいというのであれば、例えばポケットＷｉ－Ｆｉを貸し出すなど、区として時間内にオンライン会議ができるような環境を整える何らかの工夫というのはできないのでしょうか、伺いたいと思います。","respondent":"横田情報推進課長","answer":"警視庁からの要請もありますが、フリーＷｉ－Ｆｉ自体を委託契約として結んでおりまして、施設ごとの設定時間の変更というのは、技術的にも難しいところです。ポケットＷｉ－Ｆｉ等の貸出しにつきましては、今後検討してまいりたいと思います。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"これでいいのでしょうか。質問に入りたいのですが、この間、共産党も含め、議会では何度も公契約条例の制定を求める質問がされてまいりました。改めて伺います。公契約条例はいつ頃の制定を、区は今、目指しているのでしょうか。目標を伺いたい。実効性のある条例の制定が重要ですが、条例の検討に当たっては、その鍵となる労働報酬下限額を定める考えがあるのかないのか、伺いたいと思います。","respondent":"佐藤経理課長","answer":"労働報酬下限額等につきましては、先行している自治体の中でも、制定している区あるいは自治体があることは認識しておりますので、そういったところも踏まえて検討を進めていきたいと考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討が何年なのかということなのです。区自らがもう少し主体性を発揮していただきたい。２０１５年に公契約条例を施行した世田谷区は、前文で、低賃金の常態化、高齢化や若年層入職者の激減に伴う技能労働者の不足は、放置することができない課題となっていると。２０１５年で述べているのです。もう２０２３年です。この労働環境チェックシートの記入ですが、どのように行われているのか伺いたいと思います。","respondent":"佐藤経理課長","answer":"労働環境チェックシートにつきましては、平成３１年から労働環境の実態を把握するために、要綱を定めて実施しておりまして、予定価格２,０００万円以上の工事請負および委託契約につきまして、受託者の事業者から提出を求めているところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"日給ですから、８時間労働だとしても８で割りますと、時給にすると１,２５０円から２,２５０円です。ほかのところも大体そうです。伺いたいのですけれども、なぜ現場の労働者に聞いた調査結果では、賃金は労働報酬下限額に遠く及ばない実態なのに、区が行わせている労働環境チェックシートでは、他自治体の労働報酬下限額を下回るものはないという結果になるのでしょうか。伺いたいと思います。","respondent":"佐藤経理課長","answer":"ご説明いただきましたアンケートにつきましては、ある日に現場で働いている方に直接お伺いしたというものですので、チェックシートで事業者に提出いただいている内容と、必ずしも前提を一にするものではございませんので、必ずしも一致するものではないと考えています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"今の答弁では、私は納得いかないのですけれども、方法とか前提が違うというのは、それはそうかもしれないですが、あまりに大きな違いがあるのです。ですから私は、品川区も建設組合の皆さんのように工事現場に赴いて、直接労働者から賃金を聞き取るなどの調査が、公契約条例の制定に向けて必要だと思うのですけれども、いかがでしょうか。","respondent":"佐藤経理課長","answer":"現場の方のご意見ということですけれども、そういったところも含めまして、労働者の方へのアンケートにつきましては、この条例を検討する中で、引き続き研究していきたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"何とかしたい、現場の、業界の未来を開きたい、労働者が人間らしく働ける環境をつくりたいということで、区民の方、組合の皆さんは頑張っているわけですから、ぜひ区も、労働者に直接聞き取りなどを行っていただきたい。そこには、いろいろ表現も工夫されております。それについてはどのように検討していくのか、お願いいたします。","respondent":"佐藤経理課長","answer":"冒頭申し上げたとおりで、ほかの区の状況などを参考にいたしまして、引き続き検討してまいりたいと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"よろしくお願いします。私からは、２１１ページ、しながわマラソン大会開催準備経費、１８２ページ、総務運営費、関連して、事務事業評価についてお伺いいたします。１８３ページ、新年賀詞交歓会経費、１８７ページ、特別職報酬等審議会経費、そして時間があれば、２０５ページ、フィルムコミッション事業についてお伺いいたします。","respondent":"三井スポーツ推進課長","answer":"現在このコース案を示しているところですが、これでコースの魅力が全くないということは、全く不十分とは考えておりませんので、このコース案を検討しながら、魅力的な大会にしていきたいと考えております。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"体感的に９割方、必要だと書いているかと思います。したがいまして、真に必要な行政サービスの絞り込みのために、事務事業評価の適正活用、そして賢い支出、無駄削減の決断を行っていただきたいと考えておりますけれども、果たしてこの行政評価シートで、必要だという所管課からの多くの声が上がっている中、本当にそうした決断ができるのか、品川区、区長のご見解があれば伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"そうした状況変化に迅速に対応するために、こういった課題を適切に解決していく段で、行政ニーズも多様化、複雑化しておりますけれども、そういったものを的確に捉えて、エビデンスに基づいて、政策・事業を形成することが求められているという状況です。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に行きます。ですから、今後、新年賀詞交歓会を式典のみにするのか、飲食を提供するのか、どうなるか、まだ分からないところですけれども、もし仮に飲食を提供するならば、ぜひ受益者負担という観点も兼ねて、そして、先ほど来私が述べております区民の税負担などが増加している中、飲食提供ならば有料化をしていっていただきたいと考えておりますけれども、それについてお考えをお聞かせください。","respondent":"勝亦総務課長","answer":"新年賀詞交歓会についてのお問合せです。新型コロナの中で、飲食の提供を中止してきた部分もありますけれども、今後そういった飲食の提供の在り方、また有償・無償の在り方について、しっかり検討して進めてまいりたいと考えています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。確認が取れました。特別職報酬等審議会に移ります。議員としても、特別職報酬等審議会でどのような議論が行われているのか、議員に対して批判がある場合、議員としても改善するべきところを改善していかなくてはいけないと考えております。特別職報酬等審議会の審議と議事録の公開を、ぜひ行っていただきたいと考えておりますけれども、いかがお考えでしょうか。","respondent":"勝亦総務課長","answer":"審議の内容ですとか、そういったものにつきまして、情報公開の重要さは考えてあります。今後、必要なものは公開できるように、検討はしていきたいと考えています。","id":"exchange-031"},{"speaker":"筒井委員","kind":"提案","question":"ぜひ検討していただきたいと考えております。非常にいい事業だと考えております。一方、今、映画とドラマとかに特化している感じがあるのですけれども、提案として、ミュージックビデオ、音楽のプロモーションビデオ等々にも範囲を広げていっていただきたいと考えておりますが、その点、お考えはいかがでしょうか。","respondent":"篠田文化観光課長","answer":"委員ご指摘のとおり、現在フィルムコミッションの中では、比較的ドラマとか映画の部分を取り上げることが多いのですけれども、実は今年の３月に、コアラモード.という音楽ユニットがあるのですが、そちらのミュージックビデオを区内で撮影しているということで、こちらは今。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"情報のご提供、ありがとうあります。私も確認させていただきたいと考えています。ぜひ今後ともよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１９７ページの地域課題の自主的解決支援、２０１ページの児童見守りシステム運営費について質問します。地域課題の自主的解決支援事業について、主要施策の成果報告書１５ページにあります地域振興事業からお聞きします。区では、コンサルタントによる支援や、マンション管理組合の実態調査を実施していますが、その結果と、加入促進に向けた支援の取組についてお知らせください。","respondent":"宮澤地域活動課長","answer":"これらの調査結果等を踏まえまして、町会とマンションの関係づくりを促進するという点からも、コンサルタントを活用した伴走支援というのを現在実施しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"意見","question":"町会・自治会の課題として、役員の高齢化なども挙げられる一方で、若手などのデジタルを活用できる方もこれからどんどん増えてくるのではないかと思われます。そこで、区では町会・自治会ＩＣＴ活用促進補助金がありますが、デジタル機器の購入だけでなく、町会・自治会のデジタル活用による業務の効率化を促進していく支援の取組の考えをお聞かせください。","respondent":"宮澤地域活動課長","answer":"それらを進めることで、町会の負担軽減にもつながると期待しています。そのため、先ほども申し上げましたコンサルタントを活用した伴走支援の中でも、町会・自治会の方に集まっていただきまして、町会のデジタル化をテーマに交流会というのも実施したところです。","id":"exchange-035"},{"speaker":"せらく委員","kind":"意見","question":"好事例については、ぜひ町会・自治会を通して共有をして、展開をしてもらいたいと考えています。続いて、町会・自治会の活動の中には、小学校入学や敬老のお祝い事業というものがあり、これまで区では、それぞれの町会・自治会に対象となる方の名簿を提供していたと思います。区としてこちらの部分で何か支援できることはないか、お考えをお聞かせください。","respondent":"宮澤地域活動課長","answer":"できることとして、地域センターとして、各町会・自治会と密接に日頃から連携しておりますので、例えば町会・自治会の敬老のお祝い事業のお知らせのためのポスターやチラシのひな形等を作成したり、もしくは地域センター等でお配りするなど。","id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"児童見守りシステムについて伺います。２００５年に始まり、地域の方々のご協力を得ながら、児童の安全と防犯対策に寄与している「まもるっち」についてお尋ねします。まもるっち導入に関連する運営費の規模について、令和４年度では見守りシステムの運営費が１億５,０００万円以上という大規模な額であることが確認できますが、この費用がほかの自治体にとって障壁となっているとお考えでしょうか。","respondent":"河合生活安全担当課長","answer":"品川区も平成１７年から、いろいろ変えたりして蓄積してきたノウハウがあって、ようやく今、ここにあるのかなと認識しております。財政の内訳につきましてのご質問ですので、ご回答いたします。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"私からは、１７９ページ、シティプロモーション推進経費、１８３ページ、国際交流推進事業、１８８ページ、人事管理費、２０５ページ、文化活動支援事業、２１５ページ、戸籍事務費、時間があれば１９７ページ、区民まつり経費についてお伺いいたします。１点目に、戸籍事務費についてお伺いいたします。次に行きます。２点目に、シティプロモーション推進経費、国際交流推進事業についてお伺いいたします。","respondent":"吉野戸籍住民課長、辻広報広聴課長、勝亦総務課長、篠田文化観光課長","answer":"こちらですけれども、無戸籍になりますと、学業とか、児童手当とか、そういったサービスの提供とかが滞ると考えています。森澤区長が様々な場面に行かれたことと、その発信力によって、区のシティプロモーションに大きな寄与をしていると考えております。現地の副市長との文書の取り交わし、３０周年の記念交流事業、それからホッケー協会との面談・交流、スタートアップ支援施設の訪問、それから。不勉強で、この著書は私は存じ上げないのですけれども、ここで言われている「社会的包摂」というのが。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"実態把握の現状についても教えてください。確認できてよかったと思います。４点目に、人事管理費についてお伺いいたします。こちらは要望ですが、来年１月からのおくやみコーナーではスペース的に難しいと思うのですけれども、新庁舎においては手続面のご負担だけではなく、グリーフケアの観点から、お過ごしいただく時間を丸ごと包み込むような空間づくりを意識していただきますようお願いいたします。","respondent":"勝亦総務課長、吉野戸籍住民課長、崎村人事課長、田口人材育成担当課長","answer":"国内外との交流につきまして、今後も、コロナが明けてまいりましたので、区民の幸せですとか、地方創生といったものに資するものについて。おくやみコーナーですけれども、こちらは来年１月より実施を開始する予定でおります。昨年度の休暇取得の状況ですけれども、職員全員が年次有給休暇を１０日以上取得することを目標として掲げているところ。令和４年度からは、管理職向けのマネジメント業務改善推進研修などを実施しています。","id":"exchange-039"},{"speaker":"澤田委員","kind":"質問","question":"２１９ページの斎場運営費についてお伺いいたします。斎場運営費として、令和４年度の当初予算は７,０６５万円でしたが、支出額は６,８９９万７,４６９円となっており、この内訳に、「電気、ガス、水道料」とあります。原油料の高騰などにより価格が上昇している中、当初予算内で収まる低い価格の支出となったのはなぜだとお考えでしょうか。区としてのご見解をお聞かせください。","respondent":"吉野戸籍住民課長","answer":"負担金ですけれども、こちらはその都度、社会情勢等を踏まえて検討しているところでありますので、この価格内で、こういった物価高騰に関しましても勘案してやっている状態です。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"予算に価格高騰分も織り込み済みだったからということでしょうか。","respondent":"吉野戸籍住民課長","answer":"それぞれの社会情勢等も踏まえて、こちらは検討しているところであります。","id":"exchange-041"},{"speaker":"澤田委員","kind":"意見","question":"今年６月に業界団体が行った初の全国調査では、６日間から８日間の火葬待ちが全国で生じているということでした。他自治体ではありますが、火葬待ちをする際に、遺体安置に１日２万円ほどかかると言われ、金銭的な面から預けることができず、火葬までの５日間、棺を自宅に置かざるを得ず、遺体が傷んでしまい、化粧を施すことで何とか損傷箇所を隠し、葬儀を行ったという事例もありました。","respondent":"吉野戸籍住民課長","answer":"臨海斎場ですけれども、時間さえ選ばなければ、早い時間帯とか遅い時間帯であれば、待たずに利用可能となっております。","id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"現時点では、時間を選ばなければ火葬待ちというのは特にないということで、了解いたしました。これは品川区民にとって大変心強いことだと思うのですが、そこでお伺いします。臨海斎場には、霊安室の保冷庫が２４庫ありますけれども、その稼働率または混雑状況を、お分かりになる範囲で大丈夫ですので、お聞かせください。","respondent":"吉野戸籍住民課長","answer":"保冷庫の稼働状況ですけれども、利用率は令和３年度７９.１％、４年度は８２.４％になります。","id":"exchange-043"},{"speaker":"澤田委員","kind":"質問・要望","question":"現在の臨海斎場施設整備基本方針の施設整備スケジュールでは、火葬状況のピークとなる２０６０年に向けて、２０２８年度から着工し、２０３０年度には増築施設での事業開始となります。今後迎えるであろう多死時代に備え、２０３０年度の開始よりもう少し期間を早めていただきたいというお声も届いております。区としてのご見解をお聞かせください。","respondent":"吉野戸籍住民課長","answer":"委員ご指摘の点ですけれども、臨海部広域斎場組合議会でも、今後の大規模な災害に備えて、令和１２年度を前倒しにできないかという質問が上がりました。組合としましても検討してまいりますという回答がありました。区としましても、今後働きかけていきたいと考えております。","id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"続きまして、２０５ページ、フィルムコミッション事業についてお伺いいたします。先ほどほかの委員も質問されていましたけれども、フィルムコミッション事業として１,６２３万円が計上されておりますが、どのように使われていらっしゃるのか、内訳等を教えてください。","respondent":"篠田文化観光課長","answer":"そのほか、ロケ地の支援業務等に関しては、職員も対応しています。","id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"しなロケのホームページでは、どの場所で、どのようなドラマや映画に使われたかなどを知ることができます。さらに、撮影したドラマや映画のホームページのリンクを張り、撮影されたシーンなどをホームページで見られるようにするなど、積極的に紹介するのはいかがでしょうか。区の見解をお聞かせください。","respondent":"篠田文化観光課長","answer":"リンクを張ることにつきましては、こちらの全体の画面の配置等もありますので、今後検討してまいりたいと思います。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問","question":"私からは、１７７ページ、区提供番組制作費、１９１ページ、庁舎整備費、２１９ページ、選挙管理委員会運営費から関連して、それぞれ伺ってまいります。現状をまずお聞きしたいと思います。どのような番組を放映されているのか、また、区のお知らせ的なところがどのように放映されているのか、お聞かせください。","respondent":"辻広報広聴課長","answer":"現状では、年間で全部で１５６本撮っております。「わ！しながわニュース」は、イベント等の実施の報告等のニュース、それから「区からのお知らせ」は、これからのイベント等のもので、これは毎週更新しておりますので、年間でどちらも５２本ずつです。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問・要望","question":"詳細を伺わせていただきました。この夏に、女性起業家が集うランチ会に参加させていただきました。西本委員もそこに来られておりましたけれども、そこで高齢者を対象としてサークルを立ち上げて、定期的に会を行っている方々からお話を伺う機会がありました。ですので、区民チャンネルを活用して、申請の仕方を丁寧にそこで流していただくような工夫も、ぜひしていただきたいと思いますが、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"過去においては、コロナ禍のときに、区民全員を対象に行いましたしながわ活力応援給付金のときには、申請書の書き方というものを放映した実績があります。過去においてはその１回だけです。高齢者の方は、確かに申請書等を書くのが非常に難しいところもあると思います。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"特に高齢者の方は、よくテレビを見ていらっしゃる方も多いですし、ケーブルテレビを見ている方もいらっしゃいますので、ぜひ今後、工夫をしていただきまして、申請の仕方を具体的な動画として分かりやすく情報提供していただきたいと思います。続いて、庁舎整備費から、授乳施設に関してお伺いいたします。品川区の中での授乳施設の防犯対策についてということです。これは区有施設に限らないと思います。","respondent":"佐藤経理課長、小林施設整備課長","answer":"私からは、総合庁舎における授乳室についてご答弁申し上げます。総合庁舎におきましては、本庁舎の３階・７階にありまして、今ほど委員からご指摘のありました防犯対策というところでは、内側から鍵がかかるような形になってあります。委員からお話がございましたブザー、呼出しボタンですが、従来は施設の機能に応じて設置をしてきておりますが、今後整備していく施設につきましては、原則設置することで。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"特に防犯ブザーに関しては、新しいところだけでなく、今見直しをしていただく中で、必要なところには全て整えていただきたいということも要望させていただきたいと思いますので、どうぞよろしくお願いいたします。昨年の決算特別委員会でも、投票所における配慮が必要な方への対応を求めましたが、大事なことかなと考えていますので、改めて伺ってまいります。","respondent":"鈴木選挙管理委員会事務局長","answer":"必要のない方も、その紙にどう対応するかということで混乱が生じる可能性もありますので、ご提案の方法を含めて、よりよい支援ができるような方法を検討したいと考えております。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、２１９ページ、斎場運営費についてお聞きします。区民の方とお話していても、非常に聞かれることの多い品川区の火葬場についてお聞きしたいと思います。同じ質問になるところは、省略します。私から続いての質問となりますが、臨海斎場が２０３０年に施設の拡大予定ということですが、この拡大予定によって、どれぐらいの受入れが増えるのでしょうか、お聞かせください。","respondent":"吉野戸籍住民課長","answer":"こちらですけれども、臨海斎場には今、火葬場が１０基あるのですけれども、こちらを６基増やしまして、１６基に拡大する予定でおります。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そのほか、７か所は民営となっております。実際、今回の第３回定例会でも、行政が運営主体となる新規火葬場建築を求める陳情のほか、参考送付とはなりましたが、民営火葬場の火葬料金適正化や届出制について言及する陳情が２件出ています。臨海斎場と同じように、こちらの桐ヶ谷斎場も品川区で買い上げるお考えはないのでしょうか。区の見解をお聞きしたいと思います。","respondent":"吉野戸籍住民課長","answer":"公営の火葬場の建設については、今のところ計画はありません。ただ、臨海斎場に関しましては、先ほどお伝えしたとおり、火葬場の増設等を計画しておりますので、こちらで需要は満たされると考えております。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問・要望","question":"特に桐ヶ谷に対しては、予定はないということで、品川区でも、いつまでも安心して住み続けられる品川を目指して、区民の安定した生活環境を整えるために、様々な角度から問題解決に向けて、今後も取り組んでいっていただきたいと思います。どうぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"山本委員","kind":"質問","question":"本日もよろしくお願いいたします。私からは、１７７ページの広報経費、２１１ページの地域スポーツ支援について伺います。１７７ページの広報経費について伺います。品川区では、公式ウェブサイトのほか各種ＳＮＳ、アプリと、様々なツールにてデジタル上での情報発信をしておりますが、それぞれのツール利用の狙い、特徴、および閲覧や登録等の利用状況についてお教えください。","respondent":"辻広報広聴課長","answer":"公式Ｔｗｉｔｔｅｒは、直近の数字で登録数が２万７,０００、Ｆａｃｅｂｏｏｋが４,５００、ＬＩＮＥが３万４,０００、それから、アプリ系のものでは、例えば地図情報を使ったココシル品川、こちらのユーザーが月平均で４,９００人、それから。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問","question":"ご答弁ありがとうあります。この利用状況について区ではどのようにお考えでしょうか、お考えを聞かせください。","respondent":"辻広報広聴課長","answer":"そのほかＬＩＮＥですが、これは令和２年度の末に開始したのですが、こちらは３万４,０００ということで、ほかの情報ツールと比べても利用人数が多く、若い方からお年を召した方までたくさんのユーザーの方がいて、情報を流すのには非常に有益なものかなと思っています。","id":"exchange-055"},{"speaker":"山本委員","kind":"提案","question":"スマートフォンの世帯普及率は約９割と言われ、スマートフォン、タブレット端末での情報収集が増えている状況下、情報を集約し、利用者にとって簡単に知りたい情報を見つけられるアプリを活用し、重点的に展開することが有効であるのではないかと考えますが、いかがでしょうか。以上、品川区の総合的な情報発信に関する独自のアプリの開発についてご提案させていただきましたが、いかがでしょうか。","respondent":"辻広報広聴課長","answer":"ホームページは今、一応スマホ対応の画面などもありますが、どういった形が一番皆様に届くか。伝えるのではなくて伝わる形をどうやったら取れるのかというのは、区民の皆様の意見もお伺いしながら、今後いろいろ考えていきたいと思います。","id":"exchange-056"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうあります。続いて、残り時間は少ないですが、地域スポーツ支援についてお聞きしたいと思いますが、もう短いですので、要望としては、地域の少年少女スポーツチームの指導者の育成に対する課題があるということで、そういう区民の声を聞いておりますので、こういった支援について要望させていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今日も当事者目線から質疑をします。お願いします。１８７ページのＤＶ・カウンセリング相談です。私自身もＤＶの当事者です。といっても被害者でありまして、殴られたほうですけれども、過去の、昔のパートナーですけれども、そういうことで、ＤＶ・カウンセリング相談、ＤＶ全般で区が取り組まれている取組を教えてください。","respondent":"加島人権啓発課長","answer":"ＤＶに関して区の取組ですが、まず、ＤＶ相談、男女共同参画センターで実施しております相談窓口の設置、それから、男女共同参画推進講座の中で今年度、デートＤＶ、それからＤＶに関する講座を開催いたしました。","id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そこで、ＤＶ相談、専門相談員によるＤＶ相談、ＤＶやストーカーについての相談に応じますと、配偶者やパートナーなどの親密な関係にある人からの暴力に対して、悩まず相談してくださいとありますけれども、この専門の相談員というのはどういった方が対応しているのか、もしくは件数、ここ数年の推移なども、分かりましたら教えてください。","respondent":"加島人権啓発課長","answer":"相談件数の直近の推移というところをお答えいたします。令和４年度分ですけれども、ＤＶ相談につきましては５５件です。令和３年度につきましては６０件、それから、令和２年度につきましては５６件、遡ってで恐縮ですが、そのような推移となっております。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そのうちの３回は午後１時から４時という時間です。加えて、要は１か月間でキャパシティーが、１２人しか今相談ができないという状況になっていて、これだとなかなか相談したくてもできないなと思うのですけれども、この辺の区の受け止めはいかがでしょうか。拡充するとか、そういったことはお考えでしょうか、お願いします。","respondent":"加島人権啓発課長","answer":"ＤＶ相談は確かに、今ご案内いただいたとおり、日中が月３回、夜間が月１回という実施の状況になってあります。今現状やはり女性からの相談が多く、パートナーですとか配偶者が仕事に行っている間に、家を抜けて相談に来るという方もいらっしゃいます。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この平日の時間帯と夜間の時間帯での稼働率の内訳というのはいかがでしょうか。","respondent":"加島人権啓発課長","answer":"大変申し訳ございませんが、手元の資料では時間別の内訳はございません。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"できればそこをしっかりと把握していただいて、もし夜間のほうに偏っているのであれば、ぜひ対策というか、拡充をしていただきたいと思います。よろしいでしょうか。","respondent":"加島人権啓発課長","answer":"ご要望はお受けいたしましたので、この後、課で統計を取り直してまいります。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"よろしくお願いします。ＤＶ対策として、個人的には、被害者を守るというのは当然そうなのですけれども、加害者に対しての更生のプログラムなどがこれから求められるのではないかと思うのですが、そういった対応というか検討はされていますでしょうか。","respondent":"加島人権啓発課長","answer":"ただ、区で実施するに当たって、そういった体制の確保ですとか予算面にまだ課題が多いことから、現状につきましては、東京都ウィメンズプラザの支援につなげているところです。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"恐らく今の答弁ですと、必要性はそれなりに感じていただいていると受け止めました。ただ、やはりこういうプログラムというのは、１回当たり大体安くて３,０００円、高いと１万円ぐらいのお金がかかると。ただ、先進国ではかなり多くのところで、実際行われております。ちなみにＤＶ被害者の方たちの支援活動を行っている団体への支援、補助金などというのは、区ではどの程度行っていますでしょうか。","respondent":"加島人権啓発課長","answer":"支援団体への補助金というお問合せですけれども、こちらについては区で現在補助制度はございません。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ積極的に取り組んでいただきたいと思います。やはりＤＶ問題というのは子どもも関わってくるので、そういったＤＶの現場を見る子どもはトラウマにもなりますし、それが大人になったときに、子どもにまたしてしまうということにつながっていきますので、明石市の取組、アクションプランも策定していますので、そういった取組もぜひ参考にしていただきたいと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"まつざわ委員","kind":"確認","question":"私からは、１７５ページ、区施設営繕事務費について質問いたします。ホームページを拝見しますと、現段階におきまして、品川区ではＺＥＢ認証を５施設、ＺＥＨ認証を１施設で取得していると確認が取れました。全国自治体において最多であり、品川区が掲げる２０５０年ゼロカーボンや２０３０年ＳＤＧｓの達成に向け、大きく貢献する事業であり、ぜひ引き続き強い推進をお願いしたいと思います。","respondent":"小林施設整備課長","answer":"区としましても初のＺＥＢ施設ということもございまして、運用につきましては様々試行錯誤した部分ではありましたが、一定の成果があったものと認識しております。","id":"exchange-066"},{"speaker":"まつざわ委員","kind":"確認","question":"９７％、目標以上の削減が進んだということが分かりました。大幅なエネルギー削減の計画を立て、実行し、確認しながら改善していく。まさにＰＤＣＡサイクルです。だからこそ、この１年間の削減量がすばらしい成果になったのではないかと考えています。見えない部分でご苦労があると思いますが、快適性と省エネを両立させるための工夫、それに対してどのようにしていたのか、お示しください。","respondent":"小林施設整備課長","answer":"工夫という観点のご質問ですが、この施設、非常に天井の高い部屋が多くございまして、例えば今、ご案内いただきました空調という観点で申し上げますと、部屋全体を空調することはせず、人が活動するエリア、大体床から２メートル辺りになるかと思いますが。","id":"exchange-067"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"令和５年３月に中間見直しを行いました環境基本計画では、令和９年までに、区有施設のＺＥＢ化を１２施設で進めるとありました。２０５０年の脱炭素社会の実現に向け、行政がＺＥＢ施設を積極的に整備していくことは、民間事業者を牽引する上でも大変重要な取組です。公共施設を多数持つ都市部の自治体の特性から、強力なシティプロモーションの一つとして、強みになるのではないでしょうか。","respondent":"小林施設整備課長","answer":"当面使用し続ける区有施設もいろいろとあります。既存施設のＺＥＢ化も非常に重要な取組だと認識しているところでございまして、大規模改修などの機会を捉えましてＺＥＢ化をするなど、様々な角度から検討を重ねていきたい。","id":"exchange-068"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"来年度は、お話が出ました多くの取得認証とともに、現在建設中の北品川ゆうゆうプラザ、また出石つばさの家など、ＺＥＢを取得した施設の運用というものが始まってまいります。課長がお話のとおり、今までの知見といったものが大きく活用される大切な１年です。管理職におきましても適性などを踏まえた新たな人事制度、こういったものの検討などを期待、そして要望しまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問","question":"１８７ページ、ＤＶ・カウンセリング相談、２０１ページ生活安全推進事業、２１４ページ、戸籍及び住民基本台帳費について伺います。一番最後については、お墓のことについてお聞きしたいと思うのですが、今日は１０月３日でありまして、登山の日だそうであります。「なぜ山に登るのか、そこに山があるからだ」、これはイギリスの登山家マロリーの言葉であります。この不滅の友情は、言い換えれば信頼関係。","respondent":"加島人権啓発課長","answer":"そのうち１８件が男性からの相談で、割合としては６.８％となっております。最後に、令和２年度分につきまして、こちらは合わせて２６１件のご相談がございました。そのうち３５件が男性の方からの相談で、こちらは割合といたしましては１３％となっております。","id":"exchange-070"},{"speaker":"つる委員","kind":"確認","question":"そうしたところで、その声を受け止める、まずその窓口、入り口がすごく大切というところでは、現在、品川区は電話対応ということかと思いますが、例えば２３区で見ても、中央区、新宿区、北区、練馬区は窓口、それから、江東区、大田区が電話となっておりますけれども、ここについて品川区は今後、こうした傾向のある中で、窓口対応としての男性相談、こうした視点についての今のお考えを教えてください。","respondent":"加島人権啓発課長","answer":"少し男性の男らしさについてご発言がございましたが、区のほうで今後、男性の生きづらさに関する講座なども開催していきたいと考えているところです。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"次に行きます。生活安全ですが、これは、一般質問でさせていただきました個人宅向け防犯カメラの設置助成についてでありますが、これはもう要望ベースでありますが、ただ、ご答弁のときに、２定の答弁、これは多分、委員会の前だったからなのかもしれないですが、答弁では１,２８０台とご答弁いただいているのですが、令和４年度まで含むと１,４５６台になると思うのです。ここの数。","respondent":"河合生活安全担当課長","answer":"個人宅の防犯カメラの助成につきましては、第三者のプライバシーの保護とか、そういったところで、適正な審査とか指導等を行う必要がありますので、やはり受理体制とか、そういった治安情勢も含めて、どのぐらいの要望があるかというところは注視しながら。","id":"exchange-072"},{"speaker":"つる委員","kind":"提案","question":"これ、実は１９９０年、平成２年３月１９日、私の父が４７歳の誕生日のときに予算特別委員会の総括質疑で、この臨海斎場を一部事務組合でやったらどうだということを提案させていただいて、それが時代を経て今こういうふうになってきて、そして、２０３０年に向けて拡充という質疑がされているところでは、個人的にも、その施策の継続性というところでは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは２０１ページ、歩行喫煙防止、１９５ページから１９７ページの地域振興経費、２０９ページの歴史館についてお伺いします。特に町会の在り方について、昨日も人口増加がどのような動きになっているのかというのを質問させていただきましたが、これをなぜ質問したかというと、品川区は、いわゆる旧住民と新住民の方が混在していて、今、新住民の方が非常に増えてきている。","respondent":"河合生活安全担当課長、宮澤地域活動課長、篠田文化観光課長","answer":"特に指定地区５地区の中でも、紙たばこの煙の苦情が多いところにはコンテナ化を進めているところです。マンションの関係づくりを含めて、町会がどういった形で地域のコミュニティを発展させていけるかというところで、様々な角度から支援をしていると。歴史館で様々な形で収蔵品を持っているのですけれども、基本的に、区が持つ財産というのは、１０万円以上になると備品登録をする形になりますので。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。もう限界。これを本当にどうやって変えていくかというのは、区がある程度主導的にやっていかないとなかなか難しいのかなと思うので、人口がどのように流入されて流出されているのかというのも把握しながら、どういうふうに社会が形成されていくのか、なぜ町会が必要なのか、こういったことを改めて考えてやっていかなければいけない。自分の町会がどこかも分からない。","respondent":"河合生活安全担当課長、宮澤地域活動課長、篠田文化観光課長","answer":"喫煙所につきましては、やはりニーズに、比率に沿って、地権者の了承を取りやすい加熱式たばこも併せてやっていきたいと考えております。子育て世帯というところでは、補助金の中にも児童参加地域事業補助金ということで、親子向けということで、町会へのきっかけづくりというところで。今後、様々検討してまいりたいと思います。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１８３ページの非核平和都市品川宣言について、２１８ページの選挙費に関わって、投票権、参政権の保障を求めて質問します。非核平和都市品川宣言について伺います。さきの一般質問で、品川の平和宣言と核抑止論は相入れないと、核抑止論を否定していると思わないのですかと、私のこの質問に、区は宣言と核抑止論が相入れないということを認めず、直接の答弁を避けるばかりでした。","respondent":"勝亦総務課長","answer":"すみません、全文を読むわけに、手元にはあれなのですけれども、非核平和の核兵器の廃絶、それから恒久平和の確立に向けたということをうたっているものです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"核兵器廃絶と恒久平和の確立ということで説明されました。その中で、やはりそれに向けて、持てる国は即時に核兵器を捨てよと書いてあると思うのですが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"おっしゃるとおり、そのように記載されております。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"そのとおりに書いてあるということですね、やはりそこを見ると、この品川区の非核平和都市宣言は、核抑止論、これは、核兵器をいざとなったら使うぞということで相手を恐怖で抑え込むというものですけれども、この抑止論を否定していると思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"記載のとおり、核兵器を捨てよというふうに訴えているものと考えています。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"核兵器を捨てよと書いてあるということは、この核抑止論、核兵器を持って脅すということを否定していると思いますが、改めて伺います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言につきましては、非核平和都市品川ということで、核兵器の抑止について記載しているものではないと考えております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"ということは、核抑止論を否定しているのだと私は思うのですけれども、なかなか区はお認めにならないのですが、区の宣言は、即時に核兵器を捨てよという立場で区としても書いてあるのですから、そこに本当に立っているのかなと思ってしまうのですけれども、改めてその姿勢を伺いたいと思います。","respondent":"勝亦総務課長","answer":"「持てる国は、即時に核兵器を捨てよと」、そのように記載していると認識しております。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"なぜ品川区の宣言が核抑止論を否定しているということを表明できないのか。こうしたことを表明していくことが、さらに核兵器廃絶、また恒久平和の確立への強い発信になると考えていないのか、伺います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言によりまして、区が自治体として、平和に対する思い、そういったものを区民に着実に伝えていくということが、区の務めであると考えています。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民にそうした思いを伝えていくということは重要だと思います。区としてもそうした視点に立ってほしいと思います。この宣言には、加えて「開発された兵器で使われなかったものはない。これは、歴史の恐るべき証明である」ということも書かれています。存在すれば使用されてしまうのです。区は、今もこの宣言と同じ認識であるということでよいのでしょうか。確認させていただきたいと思います。","respondent":"勝亦総務課長","answer":"これは、歴史の恐るべき証明である」、このように記載されております。こういった、ここに書かれております非核平和都市品川宣言、こういったものを区民の方にしっかり伝えて、恒久平和の確立に向けた取組をしていくというのが区の役割だと考えております。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"書いてあることを伝えるというのですけれども、それをさらに発信して、現状に即した発信をしていくということが、私は必要だと思います。この間、品川区は平和首長会議にも参加されました。こうした品川区も加盟している平和首長会議と歩みを同調させて、さらに核兵器廃絶への発信、平和首長会議とともに核抑止論を否定して核廃絶へと歩んでいただきたいと思うのですが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"憲法の趣旨を踏まえたこの非核平和都市品川宣言の訴えを、非核平和、恒久平和を訴えていく、区民の方にお伝えしていくのが、品川区の自治体としての役目だと考えています。","id":"exchange-083"},{"speaker":"のだて委員","kind":"提案","question":"同じ答弁しかされないのですが、ぜひそこは一歩踏み出していただきたいと思うのです。さらに一歩踏み出していただきたいと思います。既に２３区の中でも、港区、新宿区、目黒区、杉並区、豊島区、板橋区、練馬区というところが加盟をしておりますので、品川区としても加盟していただきたいと思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"核兵器廃絶、恒久平和の確立に向けましては、区民の方にこういった非核平和都市品川宣言を踏まえたお伝えをしていく、それを踏まえた今までの事業をしっかり展開していく、そういったものを品川区は今後やっていきたいと考えております。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"特に子どもたちを派遣しているということは、さらに拡充をしていっていただきたいと思いますが、ぜひさらに一歩前に進んでいただいて、核抑止論では駄目なのだと、核廃絶こそ必要なのだということで発信をしていっていただきたいと、これは強く要望しておきたいと思います。次に、投票権について伺います。何人の方が実際に投票されているのでしょうか、伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"そのうち病院が１６、特養ホームを含む老人ホームが２０、それから、障害者施設が１という内訳になっております。この４月に行われました区議選において指定施設での投票については、４１１名の方から請求があり、利用していただいているところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"各施設での人数も後でご答弁いただけたらと思いますけれども、老人施設の中には、認知症グループホームなども入っているのでしょうか、伺いたいと思います。障害者施設１か所ということで、１か所というのはなかなか少ないと思うのですけれども、なぜなのか伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"障害者関係の施設の指定が１か所であることについてですが、これは、東京都で指定施設を指定するという制度になっておりまして、都の規定の中で、対象とする施設が病院、それから５０床以上のベッドがある老人ホーム、身体障害者支援施設。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"そうしたことになってしまうと、そうした指定施設も含めて、ほかのところでも、実際投票に行くということを支援して、投票権を保障するということが私は必要だと思うのですけれども、いかがでしょうかということと、入院、入所されている方というのは、具体的にはどうすればこの仕組みを使って投票できるのか、伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"いろいろな支援が必要な方の投票に関しましては、選挙管理委員会としましても、できる限り支援策を講じて、また福祉の担当部署とも連携しまして、投票の機会が確保できるようにということは、努めているところです。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"入所されている方の不在者投票のやり方、ぜひそれを区からも働きかけていただいて、病院などからも有権者の人に働きかけていただきたいと思います。郵便投票、予算特別委員会で聞いたときには、年１回言う機会があるということで言われたのですが、その状況を伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"指定施設につきましては、東京都の選挙管理委員会、それから区の選挙管理委員会から、説明会や関連の機会を通じまして、呼びかけは行っているところです。それと、施設のほうで、やはり先ほど申し上げた人的なもの等の制約があるということは聞いております。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問・要望","question":"１９４ページ、地域活動費の中の町会活動支援につきまして、先ほどせらく委員も取り上げられた観点からお伺いしたいと思います。それが、個人情報保護法によってできなくなっているというご答弁でありましたが、これまでも、個人情報保護法が以前からある中で、令和３年に改正されて５年に施行された。","respondent":"宮澤地域活動課長","answer":"これまでは目的外利用ということで行っていましたが、そういったところに関しては、個人情報保護法の運用の下では提供ができないということになっております。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問・要望","question":"関連しまして、今年の予算特別委員会でやはりこのことの議論がありまして、これまで活用できたものができなくなったことに対しまして、当時の地域活動課長から、その可能性について探っていきたいというご答弁がありましたが、その後、探った結果、どのような状況になっているのか、お聞かせいただきたいと思います。","respondent":"宮澤地域活動課長","answer":"個人情報保護法の改正に伴いまして様々確認していますが、やはり先ほどの答弁のとおり、個人情報の取扱いのガイドラインにのっとっても、目的外で本人の同意なく提供するということは、困難という結論です。","id":"exchange-090"},{"speaker":"田中委員","kind":"質問","question":"解釈論かもしれませんが、この個人情報保護法の目的に関しましては、デジタル化が進む中で、個人情報が様々な形で活用されてきている。そういう観点、この目的に照らした中で、やはり国によるガイドラインによって一切提供できないというご判断なのでしょうか。","respondent":"宮澤地域活動課長","answer":"町会・自治会が行っていますお祝い事業というのは、やはり地域のコミュニティ発展に大変有意義な事業だとは認識しております。その一方で、法律の改正に伴いまして、情報の活用というお話がございました。様々な情報を活用していく部分というのはあろうかと思います。","id":"exchange-091"},{"speaker":"田中委員","kind":"意見","question":"この個人情報保護法の中に地方公共団体の責務ということがありまして、地方公共団体は、「個人情報の適正な取扱いを確保するために必要な施策を策定し、及びこれを実施する責務を有する」とあるように、そうすると必要な施策として、町会への、町会活動を有効に生かしていただくための品川区の施策として盛り込むことによって、私はこの法に対してはしっかり対応できるのではないかと。","respondent":"宮澤地域活動課長","answer":"区としてもお祝い事業というのは実施しているところではありますけれども、町会・自治会の独自の事業に対してという観点からいきますと、法律の下の運用というところでは、やはり目的外の提供になってしまうところです。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味で両方のバランスが必要でありまして、管理をしっかりした上での有効活用というのが私は法の精神だと思えますので、そこはぜひノーと言わず前向きな、では、どういうふうに解釈したら対応できるのかという観点も含めて、ぜひ取り組んでいただきたいと存じます。特に目を引いたのは、町会名簿を積極的に作りましょう。","respondent":"宮澤地域活動課長","answer":"名簿の提供というところに関しましては、これまでは同意がないところですが、ご本人の同意があるものは提供しているというものです。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２０１ページ、地域支え愛活動経費、同ページで生活安全活動費、２２１ページ、公報関係費、この３点からお伺いしたいと思います。一部順序を入れ替えまして、質問します。現在の高齢者の被害状況について、簡単に状況をお聞きしたいと思います。区内の被害件数や認知件数、被害総額、また被害件数のうち自動通話録音機が未設置の件数などが分かれば、それぞれお答えください。","respondent":"河合生活安全担当課長","answer":"しかしながらアポ電は引き続きかかっておりますので、やはりアポ電は９割が固定電話になっておりますので、自動通話録音機の設置促進というのは今後また引き続きやっていきたいと考えております。","id":"exchange-094"},{"speaker":"こんの委員","kind":"意見","question":"現状、ありがとうあります。やはり自動通話録音機を設置することが防止につながっていくということが分かりました。先日、８０代の高齢者が、ご自身のスマホに届いたショートメールで、危うく詐欺被害に遭いそうになったという事件があったのです。こうしたことも対策を考えていく必要が今後あるのではないかと考えていますが、こうしたことについての区のご見解をお聞かせください。","respondent":"河合生活安全担当課長","answer":"高齢者の方もスマホを使うようになりましたので、私もその辺、いろいろ対策ができないかというところで、区の担当部署でスマホの教室、そういったところで対策をやっているか確認しておりまして、業者のほうでそこの共有はやっていただいているというところで。","id":"exchange-095"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。次の質問に参ります。選挙の公報関係費についてお聞きします。そこで、まず基本的なところを確認させてください。選挙公報は、誰に対して何のために配布されるものなのでしょうか。発行に当たって、候補者の掲載文や写真、レイアウトや規格など、掲載方法に規定はあるのでしょうか。この意味するところ、どのようなことを想定された条文なのか、その辺を確認させてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"この１７２条は、都議会議員選挙と、それから区市町村に関しては、それぞれの都道府県で国のやり方に準じて定めるという趣旨の規定となっているものです。","id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"それぞれお答えありがとうございました。いわゆる選挙公報の在り方を確認させていただきました。団体は、候補者に、障害者に関わる政策に絞って分かりやすい言葉で紹介したい、そのことにぜひ協力をお願いしたいと呼びかけて、そして協力を求め、正式な選挙公報に準じて回答はそのままの形で掲載する、こうした広報誌を作られたそうです。この点について区のご見解をお聞かせください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただし、ご指摘のとおり、法の規定に沿いますと、選挙運動の一つの形態ですので、基本的には選挙期間前の配布であったり、それから、各候補者の公平性の担保というところで、選挙管理委員会として対応できることは、現実的にはないのかなです。","id":"exchange-097"},{"speaker":"こんの委員","kind":"質問・要望","question":"今取り組んでくださっていることもご紹介いただきましたが、知的障害者の方の投票支援を考えることは、全ての有権者にとっても分かりやすい選挙を実現することだと考えています。今後、品川区の障害者団体が制作を検討する際には、ぜひ選挙管理委員会としても連携する、何か協力できることがあったらお願いしたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"提案","question":"それはどのようにやっていけばいいのかなと考えています。企画で判断してとかいうのもある。蓋を開けてみると、例えば我々にとってみると、複合施設になって提案してくることもある。なかなかそれが実現できないのだというお話も聞いたりするのだけれども、こういう形の政策の提案というのは、企画としては、どう今の現状を捉えているか、教えてほしい。","respondent":"佐藤企画課長","answer":"その辺に関しましては、今年度、人員を１名増やしていただきまして、政策推進担当というのを設けて、大規模用地の検討もしておりますし、政策の検討も進めているところです。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"提案","question":"こういうことも考えるのであれば、ある程度全体を見渡せる方、それから、各所管であれば所管のことは全体を見渡せる方、こういう方々がそういうところに携わらないとできないと思っておりまして、その所管を強くする庶務担当課長のレベル、それから、企画ももっと人を増やして、横串を刺してそれを専門的にやっていく方をもっと増やす、この２通りかなとも思うのだけれども。","respondent":"崎村人事課長、久保田企画部長","answer":"今、余裕を持ってといったところと、庶務担当機能の強化といったところ、職員を増やして対応といったところのお話をいただいたかと思いますが、職員アンケートなどからでも、やはりなかなか職員が足りなくて。具体的には、例えば区政運営会議等の場で広く部長と意見交換をしながら政策提案をしてもらうとか、また予算要求のやり方、また依命通達等も従来のやり方と変えまして。","id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"提案","question":"いろいろ政策も、今公約もあって、１００の事業もいろいろどんどんやられて、私はそれはそれで非常にいいと思うけれども、そういうところが多分これ、いろいろな提案をしてくるにしても、そういう体制を取るにしても、やはり区長のそういうお話がないとなかなかできないと思っておりまして、そこら辺の感覚だけでいいので、少しだけお話があればありがたいです。","respondent":"森澤区長","answer":"今ちょうど職員提案制度というのも行っておりますが、若い職員から様々な気づきを得た提案も出てきておりますので、そういったものもしっかり形にしていきたいと考えています。","id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひよろしくお願いします。１点だけ最後、お願いだけしておきますけれども、せっかくいろいろな提案がある、あとは各所管からいろいろな話が上がってきたときに、私は計画作成というのは、例えば企画でもいいです。先ほど言ったいろいろなところで、一回計画を作成してほしいと思う。これはお願いだけしておきます。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"こしば委員","kind":"確認","question":"よろしくお願いします。私からは１８５ページ、外国人学校児童生徒等保護者補助金についてまた、１８７ページ、ウクライナ避難民生活支援経費についてお伺いします。前提としまして、今、品川区に住んでいらっしゃる外国人の児童、就学児童は大体どのぐらいいらっしゃるのでしょうか。","respondent":"吉野戸籍住民課長","answer":"すみません、この件ですが、本来であれば、戸籍住民課では外国人の就学数は把握していない、全体の数しか把握していないところなのですが、学務課に問い合わせたところ、小学生が３００人ほど、中学生が８０人ほどと聞いております。","id":"exchange-103"},{"speaker":"こしば委員","kind":"確認","question":"区内に住民票があれば、日本国籍の有無を問わず所得限度額未満であれば児童手当がつくのは、所管には確認済みです。そして、住民票があれば、区外の外国人学校に通う外国籍であれば補助金をもらうことができるのが、現状となっています。その現状を踏まえまして、この補助金が始まりました時期、また内容、３か国の外国人学校に通われている国籍の数、あと目的について教えていただければと思います。","respondent":"勝亦総務課長","answer":"外国人学校児童生徒への補助金の経緯からです。こちらにつきましては、昭和５０年代にこういった支援をしてほしいということで請願がございまして、議会で全会一致で採択された後、制度として運用を図っているものです。","id":"exchange-104"},{"speaker":"こしば委員","kind":"質問","question":"それぞれの国の内訳、その３か国の中で、中国が何人など、その具体的な内訳を教えてください。","respondent":"勝亦総務課長","answer":"内訳です。先ほど申し上げました北朝鮮が２２、中国が１０、韓国が６という内訳になってあります。","id":"exchange-105"},{"speaker":"こしば委員","kind":"質問","question":"目的です。目的は、保護者の負担軽減ということだと思いますけれども、これは私も以前、質問させていただいたときに、そういった答弁をいただいておりますが、何を根拠にして負担の軽減のために補助金を出しているのか、教えていただければと思います。","respondent":"勝亦総務課長","answer":"こちらの目的といたしましては、保護者の教育費についての負担を軽減するということを目的にしておりまして、そういった文書や歴史的な経緯も踏まえて、行っているものと考えています。","id":"exchange-106"},{"speaker":"こしば委員","kind":"質問","question":"保護者の負担ということですけれども、であれば、ほかの外国人学校に通う外国人の児童・生徒の保護者にも、品川区は補助金を出せるという理屈にもつながってくると思うのですけれども、では、そういった方向性があるのかどうかも含めて、教えていただければと思います。","respondent":"勝亦総務課長","answer":"国際的な貧困ですとか、そういった部分につきましては、必要に応じてご支援をしていくという考え方はありますので、今後、必要があれば検討していきたいと考えております。","id":"exchange-107"},{"speaker":"こしば委員","kind":"質問・要望","question":"中国は、補助金が始まった当時の４,４３８億ドルから去年には１７兆７,０００億ドルと、もう４０倍も国民総所得が激増しているわけあります。所得制限の設定だとか、またさらにその先にある見直しも含めて、一度ここで立ち止まって、ぜひ見詰めていただきたいと思いますが、区の見解を教えてください。","respondent":"勝亦総務課長","answer":"繰り返しになりますけれども、こちらの国以外にも困難を抱えていらっしゃる方たちがいらっしゃいます。今、ご意見をいただきましたので、そういったご意見、いろいろな意見を踏まえながら、検討、研究をしていきたいと考えています。","id":"exchange-108"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ検証、検討をしっかり進めていただきたいと思います。続きまして、１８７ページ、ウクライナ避難民生活支援経費について伺います。今しました質問とはまた変わりまして、今一番サポートを必要としている在日外国人の方々が、まさに２０２２年の２月末から始まりましたロシア軍による侵略によって祖国を追われ、遠い日本に避難を余儀なくされたウクライナの人々ではないでしょうか。","respondent":"勝亦総務課長","answer":"ウクライナ大使館で携帯音声翻訳機を提供していますけれども、そちらがなかなか継続していただけないようですので、区でも携帯翻訳機等を準備して提供していきたいと考えています。","id":"exchange-109"},{"speaker":"こしば委員","kind":"質問","question":"携帯翻訳機等の貸出しもされているですが、そういった支援があって、その後、なかなかコンタクトが取れない、そういった事情も出てくるかもしれませんが、そのあたりのサポートについて教えていただければと思います。","respondent":"勝亦総務課長","answer":"なかなか言葉の問題を含めまして、まず、昨日のお問合せの答弁とかぶりますけれども、お一人お一人と定期的に連絡を取り合いながら、ご要望を伺いながら、必要な支援におつなぎしているという形でご支援をしている状況です。","id":"exchange-110"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、ぜひ品川区からも、そういった支援の申出をされている方々、所管は多分、出入国在留管理庁がやっていると思うのですけれども、ぜひそういった区民の方々にも情報提供をしていただきまして、行く行くはウクライナの人々が安心して日本での生活を行い、そして、最後は祖国のウクライナの地を踏めるような環境をつくっていただきますようお願い申し上げまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問","question":"私からは１７７ページ、上から９行目、広報紙発行経費からお聞きいたします。この決算の内容を一応お聞かせください。","respondent":"辻広報広聴課長","answer":"その下の声の広報ですが、こちらは視覚に障害のある希望者の方に、広報紙の内容を読み上げで録音し、お届けする経費です。その下、外国語広報は、８月を除く月１回、英語版広報誌を発行しておりまして、その経費です。","id":"exchange-112"},{"speaker":"木村委員","kind":"質問","question":"ということは月に４回ぐらい発行して、１週間に１回ぐらいの計算になりますけれども、こういう計算でよろしいでしょうか。そして、この広報の新聞折り込みですけれども、定期購読をされていない方も大変今増えているということをお聞きいたしました。新聞の折り込みの実績などがあれば、これが今どのようになっているのか、それもお聞かせください。","respondent":"辻広報広聴課長","answer":"広報しながわの発行ですが、毎月、１日、１１日、２１日号となっていまして、それ以外に特集号を組んです。それから、折り込み経費ですが、今年度は、部数としては８万４,０００部を折り込みしています。","id":"exchange-113"},{"speaker":"木村委員","kind":"意見","question":"新聞を取っていない区民は、広報しながわをどのように手に入れているのか。今、広報スタンドというものが区内には６１か所ありますけれども、具体的にお聞かせください。","respondent":"辻広報広聴課長","answer":"そういった方はどういうふうに入手するかということですが、今、委員がおっしゃっていただきました広報スタンド、こちらは駅ですとか、あとはコンビニエンスストアですとか、区内に設置しています。そちらに取りに行かれる。","id":"exchange-114"},{"speaker":"木村委員","kind":"意見","question":"外国語広報というのもありますけれども、これが１１回とありますけれども、これはスタンドなのか、それとも自宅配布なのか、これはどのように手に入れるのか、外国の方々に対してどのようにこれを知らせているのか、お聞かせください。","respondent":"辻広報広聴課長","answer":"外国版の広報ですが、外国の英字紙などに折り込みをしています。","id":"exchange-115"},{"speaker":"木村委員","kind":"質問・要望","question":"今ご答弁いただいた広報紙の個別配送もいろいろありますけれども、新聞を取っていない方、外出が困難な方などには非常に助かる制度だと思っています。この周知はどのように行っているのか、また今後の見込みなどがありましたら、お聞かせいただきたいと思います。","respondent":"辻広報広聴課長","answer":"そういった方には、外出が困難な方には個別配送のお知らせをしていく。それから、取らなくても、まだ健脚な方、足が元気な方でしたら、お散歩がてら外に行って、広報スタンドで取っていただくということも可能かと思います。そのような形で周知をしていきたいと考えています。","id":"exchange-116"},{"speaker":"木村委員","kind":"質問","question":"１人でも多くの区民の皆さんに、障害がある、ない、また高齢者になった、足に対していろいろ障害が出てきた人たちのためにも、ぜひともそういう点についてもお願いしたいと思います。次に、１９７ページの地域振興経費から、町会・自治会新規事業定着化補助、および児童参加地域事業補助についてお伺いいたします。町会・自治会においてどのような事業に活用されてきたのか、お聞かせください。","respondent":"宮澤地域活動課長","answer":"その中の、委員ご指摘の町会・自治会新規事業定着化補助金につきましては、町会・自治会が新たに立ち上げた事業の実施経費を補助するもので、新たな取組を支援するというところで、実績につきましては、コロナ前は令和元年度で３４件というところでしたが、令和２年度に４件。","id":"exchange-117"},{"speaker":"木村委員","kind":"質問・要望","question":"いろいろと大変な時期でありますけれども、頑張っていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"もし款が違う場合はご指摘してください。企画全般ですが、第２回定例会での私の質問に対して、区長からの答弁が不明瞭であったので、それを少し明確に教えていただきたいと思いまして、再度お聞きしたいと思います。なので、自分らしさというのは、区長にとってどういうふうに具現化していくのかということを、短期、中期、長期というお考えがあるかと思いますので、そのお考えをまず教えてください。","respondent":"佐藤企画課長","answer":"自分らしさですが、自分の価値観を大切にしまして自然体で行動が行えること、一人一人が有する個性や特性、能力を生かして、ありのままで暮らしていくことというところで、大きな視点で考えておりまして、生きづらさと昨今言われておりますので。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"それは分かります。それを聞いているのではありません。私が聞いているのは、区政運営に関してどういう方向性を持って、自分らしさを実現するのですかということを聞いているので、区長、答弁をお願いします。","respondent":"森澤区長","answer":"ただいま企画課長からお答えさせていただいたとおりだと考えています。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"非常に残念です。次に、人事です。きちんと区長の思いを私たちに伝えて、それで、どうですかというのを私たちに問うべきだと思うのです。その前に、いいですか、悪いですかと議場で示さなきゃいけないのですよ。なので、それはきっちり情報提供してほしい、そうやるのであれば。だけど、今回は新しい手法を使っての人事でありますから、それはきちんと議会で説明するべきだと思うのですが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"今委員がおっしゃいましたけれども、従来と同じ形で任命同意は出しています。ちなみに要件としましては、品川区に在住いただいている方で、地域でご活動いただいている方です。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"いや、そういうことではないですよ。きちんと答えてください。いいですか。教育委員の選任同意も、それから副区長の選任同意も、説明なしでやっているのですよ。そうでしょう。だって、教育委員会の公募については、次の週の委員会に下ろされたのですよ。それを私たちは知らないですよ。きちんと説明を受けていないですよ。おかしくないですか。それを聞いているのです。","respondent":"桑村副区長","answer":"どのような説明をしていけばいいかということだと思います。１つは特別職については、基本的に区長がどういうスタッフを選ぶかということであります。","id":"exchange-122"},{"speaker":"西本委員","kind":"提案","question":"いいと言っているのですからね。別に反対していません。それから、いじめ問題調査委員会についてですが、今回、設置、補正予算が出ましたけれども、これは区長部局になぜ必要なのですか。改善提案がされていますから、教育委員会はそれを受けてしっかりやるでしょう。なのに、なぜ今回、常設としていじめ問題調査委員会を区長部局がつくらなければいけないのですか。何のためにつくるのですか。","respondent":"勝亦総務課長","answer":"いじめ防止対策推進法の第２８条に基づきますいじめの調査委員会の結果の報告が出てあります。その中で、教育委員会、学校以外のところでいじめの問題を解決していく機関が必要であるという最終的なご報告、ご提言をいただいた中で、区長部局にこの組織を設置するものです。","id":"exchange-123"},{"speaker":"西本委員","kind":"意見","question":"時間がなくなったので、もっと突っ込みたいのですが、これは教育費のほうでしますが、役割分担がまず分からない。何をどうするか分かりませんので、これは教育費のほうでしっかりとやらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、まず、インターネット上の人権侵害情報については、例えば令和４年度においては法務局、また地方法務局において処理したいわゆる人権侵犯事件が、全国ですけれども１,６００件となっているということで、法務局がプロバイダー等に対して人権侵害情報の削除を求める要請を行った件数が、３分の１弱の５３３件であったということで。","respondent":"加島人権啓発課長","answer":"こちらを試行と申し上げましたのは、これで終わりという意味ではなく、そこで得た、先ほど検索の苦労というお話もございましたが、今現在、週１回実施している検査回数が適正かどうか、もっと増やしたほうがいいのか、ないしは減らしたほうがいいのか。","id":"exchange-125"},{"speaker":"若林委員","kind":"意見","question":"２,０００名というところ、何かもう来年度の人数が決まっていて、予算の関係でみたいなご答弁がありましたけれども、これはこれから予算を組んでいかれると思いますので、ぜひ予算を、もう一声頑張っていただいて、私の趣旨も酌み取っていただいて、頑張っていただくようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１８８ページの人事管理費と、１９５ページ、公金取扱事務費でよろしいでしょうか。その２点です。様々な推移を確認するためには、いろいろ探してみて苦労しました。せめて５年間は比較できるように、この「品川区人事行政の運営等の状況について」というのはアップしていただくようお願いしたいと思います。これは要望にとどめます。令和４年度においては、病気等休職者は何名いるかお伺いします。","respondent":"崎村人事課長","answer":"分限の休職者数ですけれども、令和４年度については約９０名ほどとなっております。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和３年度が７５名、そして令和４年度は９０名という形で増加していると。大田区の場合はコメントまで載せてあって、「職務の高度化、複雑化などを背景として、心の悩みを抱える職員が増加しています。さて、品川区では、病気休職中のメンタル不全者の数について、平成２９年度からお伺いします。さらに、メンタル不全者の中で、パワハラが原因で休職せざるを得なかった職員の数、こちらもお伺いします。","respondent":"崎村人事課長","answer":"平成２９年度からの実績ということでございましたけれども、手元に過去のデータがございませんが、病気休職者のうち、委員からご紹介がありましたように、大体７割程度が精神疾患による病気休職者となっておりまして、その数についても。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"確認","question":"メンタル不全者の中で、パワハラが原因で休職されたことは今はないということですが、今までないということで、確認でよろしいでしょうか。すみません、改めてもう一度。","respondent":"崎村人事課長","answer":"休職に入る際に、直接休職者に聞き取り等を行っておりますけれども、パワーハラスメントを原因として休職に入ったというような事例はございません。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"この点については、また別の機会にもう少しお伺いします。そこで、今、区民の方から、区の職員の方の中で、そういった、何といいましょうか、過去にパワハラで、意欲ある職員の方や、あるいは若い管理職の方が残念にも退職、お辞めになってしまったということがあるのだというお話を、幾つか伺ったことがあります。その経過を伺います。","respondent":"崎村人事課長","answer":"今回の事例につきましては、本年の３月に職員から人事課にご相談いただきまして、また、併せてその翌月にも他の職員から同様の相談がありましたことから、人事課を中心として調査を行い、処分を実施したところです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、人事課の方にあって、それで処分ということですが、その途中で、窓口と、それから庁舎担当の方がいると思います。それから、苦情処理委員会というのですか、それがあると思います。もう１回そこの辺の経過、そして、苦情処理委員会にかけたとすれば、そのメンバーというのをもしお話ししていただけるならば、お尋ねします。","respondent":"崎村人事課長","answer":"相談の窓口としましては、人事課の人事係長、また人権啓発課の係長が一次的な相談窓口となっておりまして、その後、正式に受理するとなったときには、人事課長と人事係長、あと総務部長が指名する職員ということで、３名で調査を実施したところです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう経過で今回の部長級職員の懲戒処分が決まったということです。ということで、こういったホームページで公表されるということは、私が知っているところではなかったわけで、過去にこういったパワハラで処分された職員はいらっしゃるのか伺います。先ほどは、パワハラにおいて休職せざるを得なかった職員の方ですが、パワハラで処分をされた方のほうです。","respondent":"崎村人事課長","answer":"過去、パワーハラスメントで懲戒処分を行ったという例はございませんでした。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"区の中でどういうことが起きているかということが、ホームページで分かりますので。その中で、区長のコメントが出ていました。「事案の共有および管理監督職員に向けた研修の充実など、ハラスメントの再発防止により一層取り組んでまいります」というコメントが出ていました。そこで、「より一層の」という点が入っていますので、その点を含めて具体的に、改めて今後の考えをお伺いします。","respondent":"崎村人事課長","answer":"ハラスメントに関しては、特に管理監督層を中心に、これまで３年に一度、必ずハラスメントの研修を受けるということを行ってまいりましたけれども、一方で一般職員については、職層研修の中で触れることはありましたけれども、例えばどういう行為がハラスメントに当たるかとか。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"意見","question":"研修を充実させて、予算計上も要求しているということですので、ぜひ二度とこのようなことが起きないようによろしくお願いします。もう一つ、時間がないのですが、会計のほうです。その負担が来年の１０月から増えます。今年度、幾らだったのか、それが来年度幾らになってしまうのか、それを令和６年度予算でどのように予定しているのか、お願いします。","respondent":"大串会計管理者","answer":"年によって変わってまいりますが、今現在、この振込手数料、年間で１,５００万円ほどです。ですが、これが先ほど申し上げましたように１件当たり１１３円に上がりますので、ざっとした試算ですけれども３,７００万円ほどの金額になろうかと考えています。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのサービスはしようがないのですが、何とか方策を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"西村委員","kind":"質問・要望","question":"２０３ページ、都市型観光プラン推進事業、２０５ページ、インバウンド向け整備・ＰＲ事業、２１１ページ、オリンピック・パラリンピックスポーツ等振興事業について伺ってまいります。地域経済に直接影響のあるこのような取組をどうお考えか、インバウンド対応力の強化を促進できないか、伸び代のある地域ややる気のある商店街、商店、団体に支援をできないか、伺います。","respondent":"篠田文化観光課長","answer":"そのほかの様々独自にされている方への助成ですけれども、その辺については、これまでの事例等も研究しながら、今後、検討してまいりたいと考えているところです。","id":"exchange-136"},{"speaker":"西村委員","kind":"質問","question":"例えば川崎市ですと川崎芸者を復活させようですとか、大田区ですと、このインバウンドを今こそ取りに行かなければいけないと言っておられるような機運を感じておりまして、それで言うと、品川区は羽田への行き帰りに立ち寄れる場所ですから、品川区としてこのインバウンド需要に関してどのようにお考えで、どのように捉えていかれるか、お聞かせください。","respondent":"篠田文化観光課長","answer":"先ほど申し上げた、川崎市、大田区とは３都市連携ということで、一緒に３つの都市で、海外に向けて情報発信等も行っているところです。","id":"exchange-137"},{"speaker":"西村委員","kind":"意見","question":"まさに羽田空港からの乗り継ぎ２時間で品川は滞留ができる、魅力のあるまちだと私自身も思っております。浅草、鎌倉は遠い。この２時間でできる体験を探したいというニーズは必ずあるが、観光客に回遊してもらう施策、打ち手が必要だと、先日、じゃらん研究員で観光庁の広域連携の専門家の方からもご意見をいただいたところです。区のお考えをお聞かせください。","respondent":"篠田文化観光課長","answer":"特に海外からのお客様に関しましては、欧米の方からは体験型が非常に人気が高いということも伺っていますので、私どもも何らか取組ができるように、今後考えてまいりたいと思っているところです。","id":"exchange-138"},{"speaker":"西村委員","kind":"質問・要望","question":"近年、子どもが学校から持って帰ってくるチラシでも、本当にホッケーの教室が区内中で開かれていて、先日はホッケーしなフェスにも伺いましたが、正直、これまでホッケーというのはマイナースポーツだと思っておりまして、こういったマイナースポーツを盛り上げるというのは本当に難しいと思ってきましたので、スポーツを活用すると、まちづくりというのはこんなことまでできるのだと。","respondent":"篠田文化観光課長","answer":"ですので、こういった機会を逃さず、私どもも、どういった形で有効な手立てが打てるのかということは、常に研究してまいりたいと考えているところです。","id":"exchange-139"},{"speaker":"西村委員","kind":"質問","question":"７月に社会人サッカーチーム品川ＣＣセカンドとのエキシビションマッチがありまして、伺いましたけれども、このデフサッカー日本代表が区内で行ってくださっている強化合宿の予算も区から出ておりますし、何より代表監督は品川区で生まれ育って、今も在住でいてくださっていると。いろいろなことが相乗効果になってきていると思いますが、一言、区からもいただけますでしょうか。","respondent":"三井スポーツ推進課長","answer":"今回、日本代表候補のトレーニングマッチも行いまして、いい関わりができたと考えています。今後も、デフサッカーを盛り上げていきたいと思っていますので、今後、次年度に向けていろいろ準備していきたいと考えております。","id":"exchange-140"},{"speaker":"松本委員","kind":"質問","question":"私からは、１８７ページ、男女共同参画推進事業、少し時間が足らないかと思いますが、２０１ページ、できれば歩行喫煙防止推進経費について伺います。令和４年度は東京大学大学院の瀬地山角教授が講師だったかと思います。講師料として幾ら支出されたのでしょうか。男女共同参画推進フォーラムの講師料は、歳出予算見積書上はフォーラム講演会の業務委託料に含まれているのか、伺います。","respondent":"加島人権啓発課長","answer":"令和４年度の男女共同参画推進フォーラムにつきましても、令和５年度同様、委託料の中に含まれております。こちらの委託料の支出の内訳ということですけれども、申し訳ございません、今、手元には所持しておりません。","id":"exchange-141"},{"speaker":"松本委員","kind":"質問・要望","question":"こちらは要望です。約２倍になっているのです。一応コロナ禍だった令和４年度ということが関係あるのかなと思って、平成３１年度の同じ委託料を確認したら、これは５７万円ということで令和４年度とは変わらない。令和５年度にいきなり予算が２倍近く増えているのは、よくあるのですけれども、これはどういった事情なのでしょうか、伺います。","respondent":"加島人権啓発課長","answer":"ＤＶ・カウンセリング相談ですとかというのが、こちらも委託料に含まれているのですけれども、カレンダーの関係で上下することがございまして、そういったものが影響しているのではないかと考えております。","id":"exchange-142"},{"speaker":"松本委員","kind":"質問・要望","question":"これはやはり、今の相談体制がというところで３０万円上がるかといったら、そうではないと思いますので、こちらについては、また来年度以降も精査させていただきたいと思っています。一方で、その４日後ですから２９日に、中止しますという判断が出たという連絡が来たのです。これが中止になった理由はどういう事情でしょうか、お願いします。","respondent":"加島人権啓発課長","answer":"人権尊重都市品川宣言、今年３０周年を迎える節目の大切な講演会となっておりますので、区としてその内容をなかなか見過ごすことはできないのではと考えまして、今回、中止の判断に至りました。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"これが中止に至る過程において、たしかあの番組は東京で放映されているかといえば、多分あれは関西系の番組だったのではないかと思うのですけれども、それで、発言があったということをすぐ区が把握できるかといったら難しいのではないかと思います。ということで、これはクレームがあったと理解していいのでしょうか。お願いします。","respondent":"加島人権啓発課長","answer":"そちらの映像を確認いたしまして、やはりネットニュースと相違がないこと、それから、全体のジェスチャーの中でもなかなか見過ごせないものがございました。そういったことを判断いたしましたのと、あと、区内からもやはり苦情のお声というのは届いております。","id":"exchange-144"},{"speaker":"松本委員","kind":"確認","question":"何を確認したいかというと、こうした事情がありますと、全国から一部の方たちががーっとクレームをしてくるということがあって、それが中止の判断のきっかけになってくるということがあり得ると思うのですけれども、今回に関してはそういった事情ではなくて、あくまでまずは区でその番組を確認して、それで、これはやはり呼ぶにはどうなのかなということで判断されたとお伺いしてよろしいでしょうか。","respondent":"加島人権啓発課長","answer":"中止の件につきましては、ただいま委員からもご案内がございましたとおり、発言内容を考慮いたしまして、区として中止の判断をしたものです。","id":"exchange-145"},{"speaker":"松本委員","kind":"質問・要望","question":"そういった事業が中止になるというのは、やはり極めて残念なことだと思います。当区においては、そうではなくて、もう呼ぶのだと、この人がこの講演会には適切だと決めたのであれば、クレームが来たとしても、もちろんその内容は精査すべきですけれども、そういったキャンセルカルチャーにしっかりと対抗していくというふうに求めたいと思いますが、ご見解を伺います。","respondent":"加島人権啓発課長","answer":"男女共同参画推進フォーラムではないのですけれども、昨年１２月に人権週間講演会を実施いたしまして、講師に安田菜津紀さんをお呼びいたしました。その際にも、安田さんのルーツを取り上げて、なぜこの方を講師に呼んだのかという問合せが人権啓発課にございました。","id":"exchange-146"},{"speaker":"松本委員","kind":"意見","question":"すごく心強い発言、ご答弁だったと思います。本当にいろいろな政治的な立場はあると思っていますけれども、私も今回、例えば田嶋陽子さん、政治的にどうかと言ったら、私も全然異なる立場もあると思います。今日は、以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"１７９ページ、シティプロモーション「わ！次に１８３ページ、賀詞交歓会、うちの会派では賀詞交歓会、飲食はもう有料でやったらどうだという質問をずっと、要望を含めてしていたのですが、今日の午前中の答弁で、もう無料飲食はやりませんと的確に答弁してくださったと思うので、そこを改めて伺います。自治功労者等表彰は秘書担当課長が担当しているのでしょうか。確認です。その辺についてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"だから、ここは徹底的にやはりやっていかないといけないと思うのですが、それについてはいかがでしょうか。しようがないではないですか、わんわんバッグ。その辺についていかがでしょうか。そこら辺のメンタルをどういうふうにフォローしていくのか、その辺についてお伺いします。当選することよりも、ポスターを貼る番号が４９番以降にならないでほしいと。なぜだと思いますか。質問します。","respondent":"小林施設整備課長、辻広報広聴課長、勝亦総務課長、岡秘書担当課長、崎村人事課長、田口人材育成担当課長、河内環境課長、河合生活安全担当課長、提坂税務課長、鈴木選挙管理委員会事務局長","answer":"平成３０年度から計画的に進めているところでございまして、その効果ですが、施設の規模や用途によって若干異なる部分はありますが。しながわ」の合い言葉についてです。こちら、区民と共に進めて８年目になるわけですが、現在、森澤区長の下、新時代の品川を進めていく状態です。賀詞交歓会につきましては、区と関係の深い団体との親睦を目的として実施していますけれども、おもてなしとのバランスはありますけれども。自治功労賞等の表彰は総務課の事業ですが、秘書担当で実施しております。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうなのです、４９番以降は高い、貼れない。脚立を用意しないとならないのです。「わ！しながわ」と賀詞交歓会、今日で事務事業評価をやってしまいましたね、２つ、カットしたのだから。秘書担当、せっかくあるのだから、ここの今回の項目で１つしかないわけですよね、答弁できるのが、この表彰しか。だから、せっかくですから、秘書担当をどんどん活用していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、１８５ページの私立学校関係費、そして、１８７ページの男女共同参画推進事業、それから、１８９ページの職員給与費で会計年度任用職員の給与費と、それから保健師の増員を求めて質問したいと思います。ここで改めて求めていきたいと思います。ぜひこの私立学校、国立、都立も含めて、学校給食費の無償化を品川区でも行っていただきたいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それに加えて、私立の学校に通う子どもたちは５,０００人ということなので、全ての子どもたちの１８％もいるわけですから、私立を選んだということで、私はこの子どもたち、それから家庭を差別すべきではないと思います。それともう一つ、勤勉手当というのが会計年度任用職員には反映されていないのですが、これについても反映されるべきだと思うのですが、いかがでしょうか。","respondent":"崎村人事課長","answer":"全体の母数としては約１,３８０人のうち、８１.６％が女性になっております。ベースアップ、定期昇給ですとか経験評価、経験加算のことなのかなと思うのですけれども、自治体によっては、こちら、昇給ですとか経験加算を実施している区もあるということは認識しております。","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問・要望","question":"聞いたら、手取りで２０万円に届かないと言うのです。ベースアップをしっかりとしていただきたい。それから、資格を持っている方に対してもしっかりと評価をして、そこに対しての加算なり手当なりを出すようにしていただきたいと思うのですが、いかがでしょうか。そこのところを是正するという意味からも、私はこの会計年度任用職員の待遇改善というのは欠かせないことだと思うのですが、いかがでしょうか。","respondent":"崎村人事課長","answer":"男女の賃金格差という部分については、特に会計年度任用職員も常勤職員もそうですけれども、賃金に差を設けているわけではありませんので、会計年度任用職員の処遇改善をしたからといって、そこの格差が縮まるといった認識はございません。","id":"exchange-153"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。この問題は医師会からも要望を受けていまして、医師会の要望書の中でも、区の保健師は現在２３区で２２位の保健師数ですと、様々なところがなかなかうまくいかないというところも書かれていまして、保健師確保のための予算の確保をご検討くださいという要望書を、私たちも頂いていますので、区にも行っているのではないかと思うのですが、その点いかがでしょうか。","respondent":"崎村人事課長","answer":"現員ベースで考えますと、２３区の平均が、１０万人当たり大体職員数１５.５名ということになっておりますので、それを満たすためには約１０名の増員が必要と、今のところの数字として把握をしています。","id":"exchange-154"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひとも計画的に保健師の増員ということで、もう本当に早急に、せめて２３区平均までは持っていっていただきたいということで、要望します。それから、このリプロダクティブ・ヘルス／ライツに対しての区の認識を伺ったときに、女性の生涯を通じた健康支援に関わる理念だということで認識しておりますというご答弁でしたけれども、この認識というのは今でも同じなのか、伺いたいと思います。","respondent":"加島人権啓発課長","answer":"私から、まず１点目、リプロダクティブ・ヘルス／ライツが条例の基本理念に加わった経緯というところですけれども、こちらにつきましては、男女共同参画センターでも啓発を進めております、ご質問がありましたがデートＤＶ、ＤＶといったことにも関連がありますことから。","id":"exchange-155"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これ、もう時間がなくて申し上げられないですが、合法かつ安全な中絶の権利、それから、避妊の権利、情報に基づいて女性が生むか生まないかを自由に決定する権利、それから、そのための性と生殖に関する教育と教育アクセスの権利、こういう権利が９項目、それから、その状態を享受する権利という、もう少し深く捉えて、ここに反映させていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、１７９ページ、情報公開等経費、１８７ページ、男女共同参画推進事業でＤＶ・カウンセリング相談について伺います。最初に情報公開等経費です。先日もある情報の公開を求めたところ、一部公開で決定通知が来ました。この情報公開請求という区民の権利に対して、問題がぴんとこなかったということも含めて、区全体の認識が甘いのではないかということを懸念いたしましたが、改めて見解を伺います。","respondent":"辻広報広聴課長","answer":"私どもとしましても取りまとめの課として、そこのところはきちんともう一度各機関にお知らせするといいますか、徹底するようにしたいと考えています。","id":"exchange-157"},{"speaker":"吉田委員","kind":"質問","question":"この問題について、本当によかったと思ったのは、広報広聴課に問い合わせたときには、私たちと問題意識を共有していただいたので、本当によかったと考えています。気づかずに間違った相手先に不服申立てをした場合、本来の請求先にきちんと回されて、弁明書など、その後の手続に入れると理解してよろしいでしょうか。そうすべきと考えますが、見解を伺います。","respondent":"辻広報広聴課長","answer":"前例としまして、行政委員会に審査請求を出すところを区長部局に出したというような事例はないのですが、もしも仮にそういうことがあったときには、それは出す先が違うということでもちろんお伝えして、適正に権利が行使されるようにはしたいと思います。","id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、これ、私たちも、さあ、不服申立てをしましょうとなってから、一応相手先を確認して間違いに気づいたというところもありまして、やはり情報公開請求をする側も、きちんとその辺のところを認識していないといけない。少しこの読み方がよく分からないのですけれども、基本は、これは必要な制度であるという評価だと理解しておりますが、少しこの評価の読み方を教えていただければと思います。","respondent":"辻広報広聴課長","answer":"一方で審議会、こちらは予算としては少し大きめに取っておりまして、予定していた回数よりも審議会の開催回数が少なかったので、報酬費が少なかった、執行率が低かったという記載になってあります。","id":"exchange-159"},{"speaker":"吉田委員","kind":"質問","question":"今、もう既に１件出してしまっているので、それは今後も争っていきたいと思います、最後まで。きちんと出してもらわないと困るので。次に、１８７ページ、ＤＶについて伺いたいと思います。先日、たまたまテレビを見ていましたら、やはりデートＤＶのことが取り上げられていました。質問です。これは、男女共同参画センター以外に、どこで目に触れることができるのか、教えていただければと思います。","respondent":"加島人権啓発課長","answer":"男女共同参画センターで発行しております「デートＤＶって何？」の冊子の件ですけれども、こちらにつきましては、設置しているというよりも、若年層に向けて配布をさせていただいています。","id":"exchange-160"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ただ、やはりいろいろな方に気づいていただくチャンスは多ければ多いほうがいいかなと思います。例えば地域センターとか、それから児童センターとか、そういうところにも配布することはできないでしょうか。ぜひ前向きに検討していただきたいのですが、いかがでしょう。","respondent":"加島人権啓発課長","answer":"デートＤＶというのは、若年層がゆえにその被害についてなかなか感知し難かったり、周りの方につきましても、デートＤＶをけんかだとか嫉妬というふうに見やすい傾向がありますので、委員からご提案がございました地域センター、児童センターへの設置というところにつきましても。","id":"exchange-161"},{"speaker":"吉田委員","kind":"確認","question":"ぜひ前向きに進めていただけたらと思います。それから、相談窓口ですが、品川区内ではきゅりあん３階の男女共同参画センターということで理解していいでしょうか。具体的な対応についてはいかがでしょう。きゅりあんで相談したら、次の救済段階に進むために別のところに行かなければいけないとか、きゅりあんで最後までご相談していただけるのか、その辺のことを確認したいと思いますが、いかがでしょう。","respondent":"加島人権啓発課長","answer":"ただ、デートＤＶの中でも性犯罪ですとか性暴力に関する相談になりますと、相談者の２次被害の防止、それから、医療機関への同行の必要性なども生じることから、こちらは東京都性犯罪・性暴力被害者ワンストップ支援センターにつないでいくように心がけているところです。","id":"exchange-162"},{"speaker":"吉田委員","kind":"質問","question":"デートＤＶも同じではないかと思います。それで、やはり２５％ぐらいは男性が被害者です。」という冊子にも、裏にいろいろな相談窓口はあるのですが、例えば女性の人権ホットラインとか、性暴力救援ダイヤルＮａＮａとかわいらしい名前がついているのですが、これだと男性は相談しにくいかなと思うのですが、その辺の男性に対する配慮というか、その辺はいかがでしょうか。","respondent":"加島人権啓発課長","answer":"東京ウィメンズプラザで男性のための悩み相談というのを実施しておりますが、確かに委員ご指摘のとおり、この裏表紙からはその情報が読み取れない形になっておりますので、改善を図ってまいりたいと思います。","id":"exchange-163"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちも啓発とか、気をつけるようにしますけれども、ぜひ一緒に進めていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、１８７ページ、ウクライナ避難民生活支援経費、１９５ページ、地域振興経費で、先ほどもありました町会・自治会応援事業への名簿提供について、時間があれば１９９ページ、マイナンバーカード関連事務拡大、２１７ページ、個人番号カード経費、コンビニ交付および本籍地からの証明書交付等について伺ってまいります。端的に２つ、改めて伺います。","respondent":"勝亦総務課長","answer":"ただ、今、委員がおっしゃいましたように、現状の中で人数をお示しすることは、こういったものに大きな影響はないだろうと改めて判断をするに至りました。今後、人数についてはまずお知らせいたしまして、今後さらなるウクライナへの支援を行ってまいりたいと考えております。","id":"exchange-165"},{"speaker":"あくつ委員","kind":"質問","question":"早速ですけれども、それでは、直近、何世帯、何人のウクライナ避難民の方が品川区にいらっしゃるのか伺います。","respondent":"勝亦総務課長","answer":"現在、６人の方が区内にいらっしゃいます。","id":"exchange-166"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私の認識だと、少し減ったのかなと。２点目です。その現場を私も見たということは昨日申し上げましたけれども、これは区民の１人として本当にその対応に感謝したいと思います。その上で、昨年来、私が求めているのは、品川区として支援への積極的な姿勢を打ち出すための、全庁的な対応ということでした。改めて慎重かつ迅速な、全庁的な調整と決断を求めていただきたいと思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"ウクライナの方を中心に、ＳＤＧｓでも平和と公正を全ての人にと定められております。そうした考え方の下、ウクライナの方への支援の拡充、こちらを今、区の幹部も部長級そろって聞いております。慎重、かつ積極的に支援の拡充を図ってまいります。","id":"exchange-167"},{"speaker":"あくつ委員","kind":"質問","question":"これからも積極的な支援、そして迅速な支援をよろしくお願いいたします。お伺いしたいのは、昨年、令和４年度までにいろいろな事業があったと思うのです。これ、名簿の提供はどういう仕組みでされていたのかということと、これは法律が一律適用になったから厳しくなったという先ほどのご説明でしたけれども、ハレーションが他自治体では起きていないのかどうかということを伺います。","respondent":"宮澤地域活動課長","answer":"町会・自治会への高齢者等の名簿の提供がどういう仕組みかというところからまずお答えいたします。それぞれ高齢者名簿であれば敬老の日を前に、また入学・卒業、また新成人というところのタイミングを見て、町会・自治会に調査をかけて希望を取っております。","id":"exchange-168"},{"speaker":"あくつ委員","kind":"質問","question":"こういうお祝い事業自体をやめてしまったところもあると聞いています。中野区などでは災害時の要支援者の名簿を、７５歳以上の方に向けて全部調査をかけて、そこに地域の見守り事業について提供してもいいですかというものもくっつけて送っています。例えば品川区でも、そうした同意を得た名簿、これは見守り活動の一環としてそういうものを活用できないのか、このことについてお伺いしたいと思います。","respondent":"宮澤地域活動課長","answer":"区では３年に一度、民生委員の方が高齢者の実態調査というのを実施しております。その調査の中で、見守り活動に関して、町会・自治会への名簿の提供、情報の提供についての同意を求めております。","id":"exchange-169"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一部活用していた町会もあるとは聞いていますけれども、今までは、地域の対象年齢の方の住基の情報が全部提供されていたわけですから、補完資料ということですけれども、知らない町会・自治会の方もたくさんいらっしゃいますので、このことについては周知をしていただきたい。ここについてもう一つ工夫をしていただきたいと思います。簡単にはご答弁できないと思いますけれども、ご見解を教えてください。","respondent":"宮澤地域活動課長","answer":"お祝い事業はもとより重要な地域コミュニティの事業と認識しておりますので、地域活動課としましても、町会・自治会に、例えばハンドブックという形で活動方法、支援の仕方等を示しておりますので、そういったところも活用しながら。","id":"exchange-170"},{"speaker":"あくつ委員","kind":"質問","question":"少し時間がなくなってしまったので、１点だけ伺います。保険証等とのひもづけに関して、品川区もマイナポイントのサポート事業をずっとやってこられましたけれども、９月３０日で終わりました。実際には金曜日、９月２９日で終わっていると思うのですけれども、それを通して品川区でひもづけのミスがあったのかどうか、そして、苦情が１件でもあったのかどうか、最後にお伺いします。","respondent":"吉野戸籍住民課長","answer":"ひもづけに関しましては、間違いはありませんでした。苦情等もありませんでした。","id":"exchange-171"},{"speaker":"せりざわ委員","kind":"質問","question":"１８７ページのＤＶ・カウンセリング相談、関連して１７９ページの犯罪被害者支援、時間が余れば１９７ページの地域美化推進補助について伺います。今日、何回かＤＶ・カウンセリング相談について質疑があったと思いますが、そもそもＤＶ被害の相談窓口というのは、国、都、あと品川区がそれぞれやっているかと思います。区がやる意義というのを改めてお聞かせください。","respondent":"加島人権啓発課長","answer":"先ほど令和２年４月１日付で配偶者暴力相談支援センターの機能を整備したと申し上げましたが、こちらは、今まで総合相談として相談の窓口を広く取っているところは変わりませんけれども、福祉事務所との連携がより取りやすくなったと感じております。","id":"exchange-172"},{"speaker":"せりざわ委員","kind":"質問","question":"区の強みも非常に分かりました。大阪府警のデータによると、２４時間の中では夜間・休日のＤＶ相談というのが８０％あると伺っています。今、日中をベースとしている品川区の相談支援体制の中では、逆に言えば８０％伸び代があるのかなとも思っています。そうすると、区で２４時間対応でＬＩＮＥとかができれば、もちろんそれはベストですけれども、現実、人材の確保だったり予算の確保が難しいと思います。","respondent":"加島人権啓発課長","answer":"１点目にご質問いただきました、国、東京都との連携というところですけれども、国では内閣府のほうで、今ご紹介ございました、２４時間、メール、チャット、電話によるＤＶ相談プラスというものを行っております。","id":"exchange-173"},{"speaker":"せりざわ委員","kind":"提案","question":"「ご了承ください」となってしまうと、私は難しいのかなとなってしまうので、少しでもハードルを下げるような取組をぜひしていただきたいと思います。そうすると、民生費の話にもなってしまいますが、養育費の保障とかも区でやっていただいていると思いますが、別れるという選択肢を品川区が提案してあげるというのも、これは踏み込んだ話になると思いますが、必要なのだと思うのです。","respondent":"加島人権啓発課長","answer":"本人がどうしたいのか、逃げたいのか、別れたいのか、それとも仲を修復したいのか、そういったお話をよく聞き取った上で、最善の支援につながる提案をしたいと考えております。","id":"exchange-174"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"電話予約の意味もあるということでありますが、逆にＤＶ相談をしたいという方は、電話である必要性はないのかなと思うので、それをネット上でできるような仕組みというのは、もう一度お考えいただければと思います。無理にそうさせるのではなくて、こういう道もありますよという道を示してあげるのも、相談体制としては必要なのかなと思いますので、最後は要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491466?Template=document&Id=1534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":120294,"voices":407}}]);
